<template>
  <section>
    <div class="card col-md-12 p-0">
      <div class="card-header col-md-12 p-0">
        <div class="theme-primary partition p-actions-expand tablehead">         
          <span class="p-name text-white">{{ $t('ProjectOverview') }}    <span class="scr-template-badge">{{ Template_Name }}</span></span>
          <span class="p-actions float-right">
            <a href="javascript:;"  title="Back to list" @click="BackToList" class="p-action-btn text-white float-right"
              data-toggle-tooltip="tooltip" data-original-title="Back to list">
              <em class="fa fa-angle-double-left pr-2" aria-hidden="true"></em><br />
              {{ $t('Back to list') }}
            </a>
            <a href="javascript:;" @click="AddView()" class="p-action-btn text-white float-right" v-if="logged_usertype !== 'NU' && logged_usertype !== 'CL'"
              data-toggle-tooltip="tooltip" data-original-title="Add Project">
              <em class="fa fa-eye pr-2" aria-hidden="true"></em><br />
              {{ $t('Add View') }}
            </a>
          </span>
          <span class="collapse-head-btns">
            <a href="javascript:;" class="collapse-btns" aria-label="Collapse">
              <em class="fa fa-angle-up text-white" aria-hidden="true"></em>
            </a>
          </span>
        </div>
      </div>

      <div class="card-body col-md-12 float-left w-100 pt-3 common-dashboard-shell pb-0">
        <div class="row mx-0">
          <div class="col-12  px-0">
            <div class="w-100 float-left">
              <div class="row mx-0 align-items-stretch cd-details-overview-row">
                <div class="col-xl-7 col-lg-12 mb-3 px-0 pr-xl-2 section_pp cd-details-overview-col">
                  <div class="section cd-details-overview-section">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-file-text-o cd-head-icon" aria-hidden="true"></em>{{ $t('Details') }}</span>
                      <small class="cd-panel-actions">
                        <a href="javascript:;" class="cd-link-action" @click="opendetailModel">
                          <em class="fa fa-eye" aria-hidden="true"></em> {{ $t('View All') }}
                        </a>
                      </small>
                    </div>
                    <div class="section-body border py-3 min_ht_220 cd-details-body" v-for="(item, idx) in ProjectDetailData" :key="'cd-det-' + idx">
                      <div class="cd-details-cols">
                        <div class="cd-details-col">
                          <div class="cd-detail-pair">
                            <span class="cd-detail-label">{{ $t('ProjectName') }}:</span>
                            <span class="cd-detail-value" :title="item.PROJECT_NAME">{{ item.PROJECT_NAME }}</span>
                          </div>
                          <div class="cd-detail-pair">
                            <span class="cd-detail-label">{{ $t('PlanStartDate') }}:</span>
                            <span class="cd-detail-value">{{ item.PLANNED_START_DATE != null ? $d(item.PLANNED_START_DATE) : '--' }}</span>
                          </div>
                          <div class="cd-detail-pair">
                            <span class="cd-detail-label">{{ $t('IndustryType_Name') }}:</span>
                            <span class="cd-detail-value" :title="item.IndustryType_Name">{{ item.IndustryType_Name }}</span>
                          </div>
                        </div>
                        <div class="cd-details-col">

                          

                          <div class="cd-detail-pair">
                            <span class="cd-detail-label">{{ $t('Template_Name') }}:</span>
                            <span class="cd-detail-value" :title="item.Template_Name">{{ item.Template_Name }}</span>
                          </div>
                          <div class="cd-detail-pair">
                            <span class="cd-detail-label">{{ $t('PlanEndDate') }}:</span>
                            <span class="cd-detail-value" :class="{ 'text-danger font-weight-medium': isPlanEndOverdue(item.PLANNED_END_DATE) }">
                              {{ item.PLANNED_END_DATE != null ? $d(item.PLANNED_END_DATE) : '--' }}
                            </span>
                          </div>
                          
                          <div class="cd-detail-pair">
                            <span class="cd-detail-label">{{ $t('Status') }}:</span>
                            <span class="cd-detail-value">
                              <span
                                class="badge cd-detail-status-badge"
                                :style="{ backgroundColor: item.status_bg_color || '#28a745' }"
                              >{{ item.STATUS_NAME }}</span>
                            </span>
                          </div>



                        </div>
                      </div>
                      <div class="cd-details-progress-head row mx-0 mt-3 pt-2 align-items-center">
                        <div class="col pl-0"><span class="cd-detail-label cd-detail-label--progress">{{ $t('projectprogress') }}:</span></div>
                        <div class="col-auto pr-0"><small class="cd-detail-progress-pct">{{ progressValue }}%</small></div>
                      </div>
                      <div class="progress mt-2 cd-progress-wrap">
                        <div class="progress-bar cd-progress-bar" role="progressbar" :style="{ width: progressValue + '%' }"
                          :aria-valuenow="progressValue" aria-valuemin="0" aria-valuemax="100">{{ progressValue }}%</div>
                      </div>
                    </div>
                  </div>
                </div>
                <div class="col-xl-5 col-lg-12 mb-3 px-0 pl-xl-2 section_pp cd-details-overview-col">
                  <div class="section cd-details-overview-section">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-list-ul cd-head-icon" aria-hidden="true"></em>{{ $t('Overview') }}</span>
                      <small class="cd-panel-actions">
                        <a href="javascript:;" class="cd-link-action cd-link-ai" :title="$t('AnalysisAI')" @click="UpdateAIAnalysis">
                          <em class="fa fa-magic" aria-hidden="true"></em> {{ $t('AnalysisAI') }}
                        </a>
                      </small>
                    </div>
                    <div class="section-body border p-3 min_ht_220 cd-overview-body cd-ai-wrap">
                      <AIAnalysisPanel
                        :key="'cd-ai-panel-' + projectId + '-' + Key"
                        :project-id="projectId"
                        :AIAnalysis="AIAnalysis || ''"
                        v-if="IsAIAnalysis"
                        :UpdateAIAnalysis="UpdateAIAnalysis"
                        @analysis-saved="onAiAnalysisSaved"
                      />
                    </div>
                  </div>
                </div>
              </div>
             
             
              <div class="row mx-0 align-items-stretch cd-dashboard-three-col-row">
                <div class="col-xl-4 col-lg-4 col-md-6 col-12 mb-3 px-0 pr-xl-2 section_pp d-flex">
                  <div class="section cd-apex-card cd-dashboard-stretch-card">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-search cd-head-icon search" aria-hidden="true"></em>{{ $t('OverAll') }} {{ $t('Task') }} {{ $t('Status') }}</span>
                    </div>
                    <div class="section-body border py-2 cd-chart-body cd-dashboard-stretch-body">
                      <VueApexCharts v-if="hasTaskStatusChart" type="donut" height="300" :options="taskStatusChartOptions"
                        :series="taskStatusSeries" :key="'cd-ts-' + dashboardChartKey"></VueApexCharts>
                      <div v-else class="text-center text-danger border p-3 norecord">{{ $t('NoRecordfound') }}</div>
                    </div>
                  </div>
                </div>
                <div class="col-xl-4 col-lg-4 col-md-6 col-12 mb-3 px-0 px-xl-1 section_pp d-flex">
                  <div class="section cd-apex-card cd-dashboard-stretch-card">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-exclamation-triangle cd-head-icon priority" aria-hidden="true"></em>{{ $t('OverAll') }} {{ $t('Priority') }} {{ $t('Tasks') }}</span>
                    </div>
                    <div class="section-body border py-2 cd-chart-body cd-dashboard-stretch-body">
                      <VueApexCharts v-if="hasPriorityChart" type="pie" height="300" :options="priorityChartOptions"
                        :series="prioritySeries" :key="'cd-pr-' + dashboardChartKey"></VueApexCharts>
                      <div v-else class="text-center text-danger border p-3 norecord">{{ $t('NoRecordfound') }}</div>
                    </div>
                  </div>
                </div>
                <div class="col-xl-4 col-lg-4 col-md-12 col-12 mb-3 px-0 pl-xl-2 section_pp d-flex">
                  <div class="section cd-dashboard-stretch-card cd-activity-triple-card">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-clock-o cd-head-icon" aria-hidden="true"></em>{{ $t('RecentActivity') }}</span>
                      <small class="cd-panel-actions">
                        <a href="javascript:;" :title="$t('viewallactivity')" class="cd-link-action" @click="openviewallactivity"><em class="fa fa-eye mr-1"></em>{{ $t('View All') }}</a>
                      </small>
                    </div>
                    <div class="section-body border py-2 cd-activity-body cd-chart-body cd-dashboard-stretch-body">
                      <div
                        class="cd-activity-row"
                        v-for="(childItem, childIndex) in sortedActivityData"
                        :key="'act-' + childIndex"
                        :title="childItem.MESSAGE + ' by ' + childItem.CREATED_BY_NAME"
                      >
                        <div class="cd-activity-icon-wrap">
                          <div class="profileicon cd-activity-icon">
                            <em class="fa" :class="childItem.ICON_CODES"></em>
                          </div>
                        </div>
                        <div class="cd-activity-copy">
                          <h1 class="cd-activity-text">
                          {{ activityLinePreview(childItem, childItem.CREATED_BY == UserId) }}
                        </h1>
                          <div class="customer-meta cd-activity-meta" :title="childItem.CREATED_AT + ' ' + childItem.CREATED_TIME">
                            <span>{{ childItem.CREATED_AT }} {{ childItem.CREATED_TIME }}</span>
                          </div>
                        </div>
                      </div>
                      <div v-if="!sortedActivityData || sortedActivityData.length === 0" class="text-center text-danger border-0 p-3 norecord">{{ $t('NoRecordfound') }}</div>
                    </div>
                  </div>
                </div>
              </div>
              <div class="row mx-0 w-100">
                <div class="col-sm-12 col-md-6 col-lg-6 col-xl-6 mb-3 px-0 pr-md-2 section_pp">
                  <div class="section">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-users cd-head-icon green" aria-hidden="true"></em>{{ teamWorkloadLabel }} {{ $t('Workload') }}</span>
                      <small class="cd-panel-actions">
                        <a href="javascript:;" title="view all team members" class="cd-link-action" @click="openviewallteammembers">
                          <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                        </a>
                      </small>
                    </div>
                    <div class="section-body border py-2 cd-chart-body cd-team-body">
                      <div class="cd-team-row" v-for="(item, index) in TeamList" :key="'tw-' + index">
                        <div class="cd-team-avatar-wrap">
                          <div class="profileicon proj cd-team-avatar-circle" :style="GetInitalbgColor(item,index)">
                            <span
                              class="initials cd-team-initials"
                              :class="{ 'cd-team-initials--compact': getInitials(item.USER_NAME).length > 2 }"
                            >{{ getInitials(item.USER_NAME) }}</span>
                            <em class="fa fa-user text-success status cd-team-member-badge" v-if="item.TEAM_PROJECT_ID != null"></em>
                            <em class="fa fa-users text-info status cd-team-member-badge" v-else></em>
                          </div>
                        </div>
                        <div class="cd-team-info">
                          <div class="cd-team-name-line" :title="item.USER_NAME">{{ item.USER_NAME }}</div>
                          <div class="cd-team-role" :title="item.DESIGNATION_NAME == null ? 'Team' : item.DESIGNATION_NAME">
                            {{ item.DESIGNATION_NAME == null ? 'Team' : item.DESIGNATION_NAME }}
                          </div>
                        </div>
                        <div class="cd-team-metrics">
                          <div class="cd-team-bar" aria-hidden="true">
                            <div
                              class="cd-team-bar-fill"
                              :style="{
                                width: teamWorkloadPct(item) + '%',
                                backgroundColor: teamWorkloadBarColor(index),
                              }"
                            ></div>
                          </div>
                          <span class="cd-team-stat">
                            {{ teamWorkloadPct(item) }}%<span class="cd-team-stat-sep">·</span>{{ teamWorkloadCount(item) }}
                          </span>
                        </div>
                      </div>
                      <div v-if="!TeamList || TeamList.length === 0" class="text-center text-danger border-0 p-3 norecord">{{ $t('NoRecordfound') }}</div>
                    </div>
                  </div>
                </div>
                <div class="col-sm-12 col-md-6 col-lg-6 col-xl-6 mb-3 px-0 pl-md-2 section_pp">
                  <div class="section">
                    <div class="section-header reddy cd-panel-head">
                      <span class="cd-panel-title"><em class="fa fa-sitemap cd-head-icon" aria-hidden="true"></em>{{ $t('resourceallocation') }}</span>
                    </div>
                    <div class="section-body border py-2 cd-chart-body cd-team-body">
                      <div class="cd-team-row cd-team-row--resource" v-for="(item, index) in TeamList" :key="'ra-' + index">
                        <div class="cd-team-avatar-wrap">
                          <div class="profileicon proj cd-team-avatar-circle" :style="GetInitalbgColor(item,index)">
                            <span
                              class="initials cd-team-initials"
                              :class="{ 'cd-team-initials--compact': getInitials(item.USER_NAME).length > 2 }"
                            >{{ getInitials(item.USER_NAME) }}</span>
                            <em class="fa fa-user text-success status cd-team-member-badge" v-if="item.TEAM_PROJECT_ID != null"></em>
                            <em class="fa fa-users text-info status cd-team-member-badge" v-else></em>
                          </div>
                        </div>
                        <div class="cd-team-info">
                          <div class="cd-team-name-line" :title="item.USER_NAME">{{ item.USER_NAME }}</div>
                          <div class="cd-team-role" :title="item.DESIGNATION_NAME == null ? 'Team' : item.DESIGNATION_NAME">
                            {{ item.DESIGNATION_NAME == null ? 'Team' : item.DESIGNATION_NAME }}
                          </div>
                        </div>
                      </div>
                      <div v-if="!TeamList || TeamList.length === 0" class="text-center text-danger border-0 p-3 norecord">{{ $t('NoRecordfound') }}</div>
                    </div>
                  </div>
                </div>
              </div>
              
            </div>
          </div>
        </div>
      </div>
    </div>
    <ProjectDeatilsOverView v-if="isProjectDeatil" :projectId="projectId"></ProjectDeatilsOverView>
    <ViewAllActivity v-if="isViewAllActivity" @closeActivity="isViewAllActivity = false"></ViewAllActivity>
    <ViewAllTeam v-if="isViewAllTeam" @CloseAllTeam="isViewAllTeam = false" :projectId="projectId" ></ViewAllTeam>
  </section>
</template>

<script>
import DataService from '../../../../../services/DataService';
import VueApexCharts from 'vue-apexcharts';
import moment from 'moment';
import ViewAllActivity from '../../../../../components/Modal/ViewAllActivity.vue';
// import ViewAllMilStone from '../../../../../components/Modal/ViewAllMilStone.vue';
import ViewAllTeam from '../../../../../components/Modal/ViewAllTeam.vue';
import AIAnalysisPanel from '../AIAnalysisPanel.vue';
import ProjectDeatilsOverView from '../../../../../components/Modal/ProjectDeatilsOverView.vue';
export default {
  name: 'CommonDashboard',
  components: { VueApexCharts, ViewAllActivity,  ViewAllTeam, AIAnalysisPanel, ProjectDeatilsOverView },
  props: {
    projectId: {
      type: Number,
      require: true,
    },
    checkPmUser:{
      type: Boolean,
      require: true
    },
    NewTabName:{
      type:String,
      require: true
    },
    TabsArray:{
            type:Array
        },
    useIndustryBodySlot: {
      type: Boolean,
      default: false,
    },
    Template_Name: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      limit: 50, 
      showMore: {},
      charLimit: 150,       
      AIAnalysis:null,
      Key:0,
      IsAIAnalysis:false,
      showMoreDescription: {}, // for Description
      showMoreProjectName: {},
      ProjectDetailData: [],
      secondsPerMinute: 60,
      minutesPerHour: 60,
      ActivityData: [],
      type: '',
      IsType:'',
      ExpensePieChartData: [],
      CompanyId: 0,
      UserId: 0,
      GlobalCurrency: 0,
      GlobalBudget: 0,
      totalbudget: 0,
      totalexpenses: 0,
      paidexpenses: 0,
      series: [],
      fullLeftJSON: null,
      CurrencyCode: 'PKR',
      chartOptions: {
        chart: { type: 'donut', height: 400 },
        labels: ['Apple', 'Mango', 'Orange', 'Banana', 'Grapes'],
        plotOptions: {
          pie: {
            startAngle: 0,
            endAngle: 360,
            donut: {
              size: '70%',
              labels: {
                show: true,
                label: 'Total',
                fontSize: '20px',
                color: '#333',
                formatter: (w) => {
                  return this.GlobalBudget;
                },
              },
              value: {
                show: true,
                fontSize: '22px',
                fontWeight: 600,
                color: '#000',
              },
            },
          },
        },
        legend: {
          position: 'bottom',
        },
      },
       COLORS : ["#059669", "#f59e0b", "#ea580c", "#7c3aed", "#0d9488"],
       lastIndex :-1,
      SortBy: '',
      SortExp: '',
      PageSize: 10,
      PageNumber: 1,
      searchCondition: '',
      TeamList: [],
      // MilestoneListingData: [],
      isViewAllActivity:false,
      isViewAllMilStone:false,
      isViewAllTeam:false,
      logged_usertype:null,
      TimeZone:null,
      ProjectStatusId:0,
      TemplateId:0,
      IndustryTypeId:0,
      hasTaskStatusChart: false,
      hasPriorityChart: false,
      dashboardChartKey: 0,
      taskStatusSeries: [],
      taskStatusChartOptions: {
        chart: { type: 'donut', toolbar: { show: false }, fontFamily: 'inherit', offsetY: 0 },
        labels: [],
        colors: [],
        stroke: { width: 2, colors: ['#fff'] },
        plotOptions: {
          pie: {
            expandOnClick: false,
            donut: {
              size: '52%',
              labels: {
                show: true,
                name: { show: false },
                value: { show: false },
                total: {
                  show: true,
                  showAlways: true,
                  label: 'Total Tasks',
                  fontSize: '13px',
                  fontWeight: 500,
                  color: '#5f6368',
                  formatter: (w) =>
                    String(w.globals.seriesTotals.reduce((a, b) => a + b, 0)),
                },
              },
            },
          },
        },
        legend: {
          show: true,
          showForSingleSeries: true,
          position: 'bottom',
          horizontalAlign: 'center',
          floating: false,
          fontSize: '12px',
          fontWeight: 500,
          offsetY: 4,
          itemMargin: { horizontal: 10, vertical: 6 },
          markers: { width: 10, height: 10, radius: 3, offsetX: -2 },
          formatter: (seriesName, opts) => {
            const i = opts.seriesIndex;
            const val = opts.w.globals.series[i];
            const total = opts.w.globals.series.reduce((a, b) => a + b, 0) || 1;
            const pct = ((val / total) * 100).toFixed(1);
            return `${seriesName} (${pct}%)`;
          },
        },
        dataLabels: { enabled: false },
        tooltip: {
          y: { formatter: (val) => `${val}` },
        },
      },
      prioritySeries: [],
      priorityChartOptions: {
        chart: { type: 'pie', toolbar: { show: false }, fontFamily: 'inherit', offsetY: 0 },
        labels: [],
        colors: [],
        stroke: { width: 2, colors: ['#fff'] },
        plotOptions: { pie: { expandOnClick: false, offsetX: 0, offsetY: 0 } },
        legend: {
          show: true,
          showForSingleSeries: true,
          position: 'bottom',
          horizontalAlign: 'center',
          floating: false,
          fontSize: '12px',
          fontWeight: 500,
          offsetY: 4,
          itemMargin: { horizontal: 10, vertical: 6 },
          markers: { width: 10, height: 10, radius: 3, offsetX: -2 },
          formatter: (seriesName, opts) => {
            const i = opts.seriesIndex;
            const val = opts.w.globals.series[i];
            const total = opts.w.globals.series.reduce((a, b) => a + b, 0) || 1;
            const pct = ((val / total) * 100).toFixed(1);
            return `${seriesName} (${pct}%)`;
          },
        },
        dataLabels: { enabled: false },
        responsive: [
          {
            breakpoint: 768,
            options: { legend: { position: 'bottom', horizontalAlign: 'center' } },
          },
        ],
      },
      isProjectDeatil: false,
    };
  },
  created: async function () {
      var vm = this;
      vm.projectId = parseInt(vm.$route.params.projectId);
      vm.CompanyId = vm.GetUserInfo.CompanyId;
      vm.UserId = vm.GetUserInfo.ID;
      vm.logged_usertype=vm.GetUserInfo.UserType;
      vm.TimeZone=vm.GetUserInfo.TimeZone;
      vm.CurrencyCode = vm.GetUserInfo.Currency.replace(/[()]/g, ''); 
      vm.CheckDisabled();
      await vm.UpdateOverView();
      vm.loadDashboardCharts();
        Promise.all([
          vm.FetchTeamListing(),
          vm.GetTeamForAssociateProject()
      ])
      .then(([users, teams]) => {
          var TeamListt = [...users, ...teams]; 
          vm.TeamList = TeamListt.splice(0,5);
      })
      .catch(err => {
          console.error("❌ Error loading data:", err);
      });
  },
  computed: {     
        sortedActivityData() {
            return [...this.ActivityData].sort((a, b) => {
                const dateA = new Date(`${a.CREATED_DATE} ${a.CREATED_TIME}`);
                const dateB = new Date(`${b.CREATED_DATE} ${b.CREATED_TIME}`);
                return dateB - dateA;
            }).slice(0, 5);
        },
        progressValue() {
          const val = this.ProjectDetailData?.[0]?.current_progress;
          return isNaN(val) ? 0 : Number(val);
        },
        teamWorkloadLabel() {
          const row = (this.TabsArray || []).find((t) => t.displayCode === 'PROJECT_TEAM');
          return row && row.displayName ? this.$t(row.displayName) : this.$t('Team');
        },
        /** Scoped slot props for industry-specific dashboard bodies */
        // industryBodyScope() {
        //   return {
        //     teamList: this.TeamList,
        //     sortedActivityData: this.sortedActivityData,
        //     userId: this.UserId,
        //     tabsArray: this.TabsArray,
        //     getInitials: this.getInitials,
        //     getInitalbgColor: this.GetInitalbgColor,
        //     openviewallteammembers: this.openviewallteammembers,
        //     openviewallactivity: this.openviewallactivity,
        //     addDashboardView: this.AddView,
        //     checkDisabled: this.CheckDisabled,
        //     truncateStr: (str, len) => (this.TruncateStr ? this.TruncateStr(str, len) : str),
        //     /** Expense / budget donut (loaded in parent via getExpenseListingForPieChart) */
        //     budgetSeries: this.series,
        //     budgetChartOptions: this.chartOptions,
        //     hasBudgetChart:
        //       Array.isArray(this.ExpensePieChartData) && this.ExpensePieChartData.length > 0,
        //   };
        // },
    },
  methods: {
    isPlanEndOverdue(endDate) {
      if (!endDate) return false;
      const d = endDate instanceof Date ? endDate : new Date(endDate);
      if (Number.isNaN(d.getTime())) return false;
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      d.setHours(0, 0, 0, 0);
      return d < today;
    },
    opendetailModel() {
      this.isProjectDeatil = true;
    },
    loadDashboardCharts() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          if (!res) {
            this.hasTaskStatusChart = false;
            this.hasPriorityChart = false;
            return;
          }
          if (res.STATUSDATA != null && res.STATUSDATA.length > 0) {
            this.applyTaskStatusChart(res.STATUSDATA);
            this.hasTaskStatusChart = true;
          } else {
            this.hasTaskStatusChart = false;
            this.taskStatusSeries = [];
          }
          if (res.PRIORITYDATA != null && res.PRIORITYDATA.length > 0) {
            this.applyPriorityChart(res.PRIORITYDATA);
            this.hasPriorityChart = true;
          } else {
            this.hasPriorityChart = false;
            this.prioritySeries = [];
          }
          this.$nextTick(() => {
            this.dashboardChartKey++;
          });
        })
        .catch((err) => {
          console.error('CommonDashboard chart load:', err);
          this.hasTaskStatusChart = false;
          this.hasPriorityChart = false;
        });
    },
    applyTaskStatusChart(data) {
      if (!data || !data.length) return;
      const palette = ['#1a73e8', '#34a853', '#fbbc04', '#ea4335', '#9334e6', '#00acc1', '#80868b'];
      const labels = data.map((item) => {
        const n = item.component_name || 'Task';
        return n.charAt(0).toUpperCase() + n.slice(1);
      });
      const series = data.map((item) => Number(item.total_count) || 0);
      const colors = data.map((item, idx) => {
        const c = item.status_bg_color && String(item.status_bg_color).trim();
        return c || palette[idx % palette.length];
      });
      this.taskStatusChartOptions = {
        ...this.taskStatusChartOptions,
        labels,
        colors,
      };
      this.taskStatusSeries = series;
    },
    applyPriorityChart(data) {
      if (!data || !data.length) return;
      const palette = ['#f4511e', '#fb8c00', '#fdd835', '#43a047', '#1e88e5', '#5e35b1', '#80868b'];
      const labels = data.map((item) => {
        const n = item.priority_name || 'Priority';
        return n.charAt(0).toUpperCase() + n.slice(1);
      });
      const series = data.map((item) => Number(item.total_count) || 0);
      const colors = data.map((item, idx) => {
        const c = item.color_code && String(item.color_code).trim();
        return c || palette[idx % palette.length];
      });
      this.priorityChartOptions = {
        ...this.priorityChartOptions,
        labels,
        colors,
      };
      this.prioritySeries = series;
    },
         CheckDisabled() {        
            if ((this.logged_usertype == 'CL' || this.logged_usertype == 'NU') && this.checkPmUser) { 
                 return true;
            }
            else {
                if (this.logged_usertype == 'CA' || this.logged_usertype == 'PM') {
                   return true;
                }
                else {
                     return false;                  
                }

            }
        },
     cleanText(text) {
        return text ? text.replace(/<[^>]*>/g, '') : 'N/A';
      },
      getShortText(text) {
        const cleaned = this.cleanText(text);
        return cleaned.slice(0, this.charLimit);
      },
      getRemainingText(text) {
        const cleaned = this.cleanText(text);
        return cleaned.slice(this.charLimit);
      },
      needsTruncate(text) {
        const cleaned = this.cleanText(text);
        return cleaned.length > this.charLimit;
      },
      toggleReadMoreProjectName(id) {
        this.$set(this.showMoreProjectName, id, !this.showMoreProjectName[id]);
      },
      toggleReadMoreDescription(id) {
        this.$set(this.showMoreDescription, id, !this.showMoreDescription[id]);
      },
      FetchTeamListing: function () { 
        var ths = this;
        ths.isLoading = true;
        return new Promise((resolve, reject) => {
            let url = '';
            if (ths.searchCondition !== '') {
                url = `projectId=${ths.projectId}&projectName=&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}&${ths.searchCondition}`;
            } else {
                url = `projectId=${ths.projectId}&projectName=&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}`;
            }
            DataService.GetTeamListing(url)
                .then((response) => {
                    ths.isLoading = false;

                    if (response.data?.result?.data?.length > 0) {
                        ths.TotalRecords = response.data.result.data[0].Total_Count;
                        ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
                        ths.CurrentPage = ths.PageNumber;
                        resolve(response.data.result.data); // ✅ send data out
                    } else {
                        resolve([]); // ✅ empty array if no records
                    }
                })
                .catch((error) => {
                    ths.isLoading = false;
                    reject(error);
                });
        });
    },
    GetTeamForAssociateProject() {
      var ths = this;
      return new Promise((resolve, reject) => {
          var url = `refId=${ths.projectId}&refCode=TEAM`;
          DataService.GetTeamForAssociateProject(url)
              .then((response) => {
                    ths.isLoading = false;
                    if (response.data?.result?.length > 0) {
                        resolve(response.data.result); // ✅ Return the raw array
                    } else {
                        resolve([]); // ✅ Return empty array if no data
                    }
                })
                .catch((error) => {
                    ths.isLoading = false;
                    reject(error);
                });
        });
    },
    // FetchMileStoneList: async function () {
    //   this.isLoading = true;
    //   const params = `projectId=${this.projectId}&milestoneName=&milestoneDesc=&statusId=&projectName=&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&totalRecords=0`;
    //   await DataService.MilestoneListing(params).then((response) => {
    //     const data = response.data.result.data;
    //     if (data.length > 0) {
    //       this.MilestoneListingData = response.data.result.data.slice(0, 5);
    //     } else {
    //       this.MilestoneListingData = [];
    //     }
    //   });
    // },
    getInitials(name) {
      if (!name) return '';
      return name
        .split(' ')
        .map((n) => n[0])
        .join('')
        .toUpperCase();
    },
    teamWorkloadPct(item) {
      const p = item && item.coun_task_progress && item.coun_task_progress[0];
      if (!p || p.completed_percentage == null || p.completed_percentage === '') return 0;
      const n = Number(p.completed_percentage);
      if (!Number.isFinite(n)) return 0;
      return Math.min(100, Math.max(0, Math.round(n)));
    },
    teamWorkloadCount(item) {
      const p = item && item.coun_task_progress && item.coun_task_progress[0];
      if (!p || p.count_assign_task == null || p.count_assign_task === '') return '0';
      return String(p.count_assign_task);
    },
    teamWorkloadBarColor(index) {
      const colors = ['#1a73e8', '#34a853', '#0d9488', '#f9ab00', '#9aa0a6'];
      return colors[(index || 0) % colors.length];
    },
    UpdateOverView: async function () {
      var vm = this;
      var params = `projectId=${this.projectId}&subModuleCode=PROJECT_DETAIL`;
      await vm.GetProjectDetails();
      await DataService.GetActivityDatalisting(params).then(function (response) {
        if (response.data.status == 'Success') {
            vm.ActivityData = response.data.result.DATA;
            vm.ActivityData.forEach((item) => {        
                if (item.CREATED_TIME != null || item.CREATED_TIME != '') {                  
                    item.CREATED_TIME = vm.addTimeWithOffset(item.CREATED_TIME, vm.TimeZone);   
                }
            })
        } else {
          vm.ActivityData = [];
        }
      });
    },
     addTimeWithOffset(time, offset) {      
        if (!time || !offset) return time;
        let [hours, minutes] = time.split(":").map(Number);
        let [sign, offH, offM] = offset.match(/([+-])(\d{2}):(\d{2})/).slice(1);
        let totalMinutes = hours * 60 + minutes;
        let offsetMinutes = parseInt(offH) * 60 + parseInt(offM);
        if (sign === "-") offsetMinutes *= -1;
        totalMinutes += offsetMinutes;
        totalMinutes = ((totalMinutes % (12 * 60)) + 12 * 60) % (12 * 60);
        let hh = String(Math.floor(totalMinutes / 60)).padStart(2, "0");
        let mm = String(totalMinutes % 60).padStart(2, "0");
        return `${hh}:${mm}`;
    },
    GetProjectDetails: async function () {
      var vm = this;
      var params = `projectId=${vm.projectId}`;
      await DataService.GetProjectDetails(params).then(function (response) {
        if (response.data.result != null && response.data.result != '') {          
          vm.ProjectDetailData=[]; 
          vm.ProjectDetailData.push(response.data.result.PROJECTOVERVIEW[0]);
          vm.ProjectDetailData.forEach((item) => {            
            if (item.PLANNED_END_DATE != null || item.PLANNED_END_DATE != '') {
                item.PLANNED_END_DATE = new Date(item.PLANNED_END_DATE)    
            }
            if (item.PLANNED_START_DATE != null || item.PLANNED_START_DATE != '') {
                item.PLANNED_START_DATE = new Date(item.PLANNED_START_DATE)    
            }
            if (item.CREATED_AT != null || item.CREATED_AT != '') {
                item.CREATED_AT = new Date(item.CREATED_AT)    
            } 
            if (item.FIRST_BUILD_ON != null || item.FIRST_BUILD_ON != '') {
                item.FIRST_BUILD_ON = new Date(item.FIRST_BUILD_ON)    
            }
             if (item.estimated_cost != null || item.estimated_cost != '') {                            
                  vm.GlobalBudget = item.estimated_cost;
              }
                  
            const pa = item.project_analysis;
            if (pa != null && String(pa).trim() !== '') {
              vm.AIAnalysis = String(pa).trim();
            } else {
              vm.AIAnalysis = null;
              if (pa == null || pa === '') {
                item.project_analysis = 'No Analysis';
              }
            }
            vm.TemplateId=item.Template_id;
            vm.IndustryTypeId=item.IndustryType_id;
            vm.ProjectStatusId = item.STATUS_ID;
            vm.IsAIAnalysis=true;
          });                 
        }
      });
    },
    convertSecondsToHHMMSS: function (intSecondsToConvert) {
    var hours = this.convertHours(intSecondsToConvert);
    var minutes = this.getRemainingMinutes(intSecondsToConvert);
    var seconds = this.getRemainingSeconds(intSecondsToConvert);

    var formattedHours = this.formatIndianNumber(hours);

    if (hours < 10) formattedHours = '0' + hours;
    if (minutes < 10) minutes = '0' + minutes;
    if (seconds < 10) seconds = '0' + seconds;

    return formattedHours + '.' + minutes + ' Hrs';
},
formatIndianNumber: function (num) {
    var str = num.toString();

    if (str.length <= 3) return str;

    var lastThree = str.slice(-3);
    var remaining = str.slice(0, -3);

    remaining = remaining.replace(/\B(?=(\d{2})+(?!\d))/g, ',');

    return remaining + ',' + lastThree;
},
    convertHours: function (intSeconds) {
      var minutes = this.convertMinutes(intSeconds);
      var hours = Math.floor(minutes / this.minutesPerHour);
      return hours;
    },
    convertHoursTwoDecimal: function (intSeconds) {
      var minutes = this.convertMinutes(intSeconds);
      var hours = (minutes / this.minutesPerHour).toFixed(2);
      return hours;
    },
    convertMinutes: function (intSeconds) {
      return Math.floor(intSeconds / this.secondsPerMinute);
    },
    getRemainingMinutes: function (intSeconds) {
      var intTotalMinutes = this.convertMinutes(intSeconds);
      return intTotalMinutes % this.minutesPerHour;
    },
    getRemainingSeconds: function (intTotalSeconds) {
      return intTotalSeconds % this.secondsPerMinute;
    },
    AddView() {
         var Obj = {
             TemplateId: this.TemplateId,
             IndustryTypeId: this.IndustryTypeId
         }
         this.$emit('AddView', Obj);
      setTimeout(function () {
          $("#modalAddView").modal("show");
      }, 1000);
     
     },
    getFormattedTime() {
      const completeTime = '2025-04-25T14:58:40.5';
      const formattedTime = moment(completeTime).format('hh:mm A');
      return formattedTime;
    },
    DashboardWidgetsClick: function (type) {
      this.$emit('DashboardWidgetsClick', type);
    },
    openviewallactivity(){
      this.isViewAllActivity=true;
    },
    openviewallmilestones(){
        this.isViewAllMilStone=true;
    },
    openviewallteammembers(){
        this.isViewAllTeam=true;
    },  
    GetInitalbgColor(item, index) {
      const color = this.COLORS[index % this.COLORS.length];
      return { background: color, color: "#ffffff" };
    },
    BackToList: function () { 
        this.$router.push({ name: 'ProjectList' });
    },
    UpdateAIAnalysis() {
      const ths = this;
      ths.IsAIAnalysis = false;
      ths.AIAnalysis = null;
      ths.Key++;
      ths.$nextTick(() => {
        ths.IsAIAnalysis = true;
      });
    },
    onAiAnalysisSaved(html) {
      if (html != null && String(html).trim() !== '') {
        this.AIAnalysis = String(html).trim();
      }
    },
    activityLinePreview(childItem, isSelf) {
  const msg = (childItem && childItem.MESSAGE) || '';
  const by = isSelf ? 'You' : ((childItem && childItem.CREATED_BY_NAME) || '');

  const line = `${msg} by ${by}`;
  const max = isSelf ? 40 : 72;

  if (line.length <= max) return line;
  return `${line.slice(0, max)}…`;
},
  },
};
