<template>
  <section>
    <loader :is-visible="isLoading"></loader>
    <div class="ticketsmallfix theme-primary partition p-actions-expand mt-2" style="overflow: visible;">
      <span class="p-name text-white">{{ $t("Issue") }}</span>
      <span class="p-actions float-right">
        <a title="Import To Issue" href="javascript:;" class="p-action-btn text-white " @click="BulkAction">
          <em class="fa fa-plus pr-2"></em> <br>
          <span>{{ $t('Bulk Action') }}</span>
        </a>
        <a title="Import To Issue" href="javascript:;" class="p-action-btn text-white d-none" @click="AddNewTask">
          <em class="fa fa-plus pr-2"></em> <br>
          <span>{{ $t('Add') }}</span>
        </a>
        <a title="Import To Issue" href="javascript:;" class="p-action-btn text-white " @click="EportTask">
          <em class="fa fa-file-excel-o pr-2"></em> <br>
          <span>{{ $t('ImportToIssue') }}</span>
        </a>
        <a title="Export To Excel" href="javascript:;" class="p-action-btn text-white " @click="ExportBug">
          <em class="fa fa-upload pr-2"></em> <br>
          <span>{{ $t('ExportToExcel') }}</span>
        </a>
        <a title="Back to list" href="javascript:;" class="p-action-btn text-white " @click="BackToList">
          <em class="fa fa fa-angle-double-left pr-2"></em> <br>
          <span>{{ $t('BacktoList') }}</span>
        </a>
      </span>
    </div>
    <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left p-0 top-menu-tab border p-3">
      <div class="row p-0 pt-2 colcontrol">
        <div class="col float-left">
          <div class="form-group mb-2">
            <input class="form-control" :placeholder="dynamicPlaceholderr"  @keyup.enter="FetchBugListing(IsTaskName,'TASK_BY_NAME')"
              v-model="IsTaskName">
          </div>
        </div>
        <div class="col float-left">
          <div class="form-group mb-2">      
            <Treeselect 
              v-model="selectedStatus" :options="StatusData" placeholder="Status" :multiple="true"
              :limit="1" :limitText="getFilterLimitText"
               v-on:input="FetchBugListing(selectedStatus, 'TASK_BY_STATUS')">
            </Treeselect>
                            
          </div>
        </div>
        <div class="col float-left">
          <div class="form-group mb-2">    
            <Treeselect v-model="selectedAssignee" :options="Users" placeholder="Issue Assignee"
                            :multiple="true" :limit="1" :limitText="getFilterLimitText"
                            v-on:input="FetchBugListing(selectedAssignee, 'TASK_BY_ASSIGN_USER')"></Treeselect>

          </div>
        </div>
        <div class="col float-left">
            <div class="form-group mb-2">
                <Treeselect v-model="PriorityFilter" :options="FilterPriorityData" placeholder="Priority"
                    :multiple="true" :limit="1" :limitText="getFilterLimitText"
                    v-on:input="FetchBugListing(PriorityFilter, 'TASK_BY_PRIORITY')"></Treeselect>
            </div>
        </div>
        <div class="col float-left">
          <div class="background-0 text-left form-check-inline">
            <!-- <a title="" id="Go" href="javascript:;" data-toggle-tooltip="tooltip" data-original-title="Search"
              class="btn btn-success mr-1 px-4" @click="SearchFilter">
              <em class="fa fa-search"></em>{{ $t('Search') }}
            </a> -->
            <a href="javascript:void(0);" title="" data-toggle-tooltip="tooltip" data-original-title="Clear all "
              class="btn btn-danger clearsearchtext px-4" @click="Clearsearch">
              <em class="fa fa-refresh"></em>{{ $t('Clear') }}
            </a>
          </div>
        </div>
      </div>
    </div>
    <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="true" ModuleName="PROJECT"
      SubModuleCode="Task" IdentityColumn="task_id" :HeaderText="$t('BackLog')" :LegendArray="[]"
      :ListData="ListingData" :HeaderData="Headers" :widgets="widgets" :TotalRecords="TotalRecords"
       :RenderRowActionMethod="renderActions" :SearchFields="false"
      :ListDataCallBackFunction="FetchBugListing" :SortExp="SortExp" :SortBy="SortBy"
      :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod"
      v-on:ActionButtonClick="actionButtonClick" v-on:HeaderButtonClick="commonHeaderButtonClick"
      v-on:SortdataButtonClick="sortdata">
      <template v-slot:slotdata="{ data }">
        <template v-if="data.column.COLUMN_NAME == 'task_number'">
          <span
            style="color: dodgerblue;cursor: pointer;white-space: nowrap;  word-wrap: break-word;  overflow: hidden; display: block;  text-overflow: ellipsis;"
            title="Issue" @click="ParentTask(data.row, 'Bug')" :class="{ 'disabled-link': !CheckDisabled() }"><em
              class="fa fa-stop-circle epic-bug"></em>

            {{ data.row.task_number }} {{ data.row.task_name }}

          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'Resolution'">
          <span class="text-center d-block">N/A</span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'status_id'">
          <listing-status :isfor="'ACTIVITYLISTINGTASK'" ref="updatestatus" v-bind:dataid="data.row.task_id"
            v-bind:statuslist="StatusList" v-bind:item="data" v-bind:parentid="data.row.task_id"
            v-bind:dataselected="data.row.status_name" v-bind:callbackfunction="FetchBugListing"
            dataController="Project" dataAction="IssueStatusUpdate" v-bind:isselectedvaluestring="true">
          </listing-status>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'task_description'">
          <span :title="stripHtmlTags(data.row.task_description)"
            style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;    text-overflow: ellipsis;"
            v-html="TruncateStr(data.row.task_description, 50)">
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'priority_id'">
          <div class="cstm-drop-btn" v-if="data.row.priority_name != null">
            <select id="crmlistingStatus_span" v-model="data.row.priority_id" class="w-100"
              :style="{ backgroundColor: data.row.color_code, color: '#ffffff' }"
              @change="CommonPriortyUpdate(data.row, $event)">
              <option v-for="(item, index) in PriorityData" :key="index" :value="item.value">{{ item.name }}</option>
            </select>
          </div>
          <span class="d-block" v-else>
            {{ $t('NA') }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'planned_start_date'">
          <span
            :title="data.row.planned_start_date == null ? 'N/A' : $options.filters.formatDate(data.row.planned_start_date)">
            {{ data.row.planned_start_date == null ? 'N/A' : $options.filters.formatDate(data.row.planned_start_date) }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'planned_end_date'">
          <span
            :title="data.row.planned_end_date == null ? 'N/A' : $options.filters.formatDate(data.row.planned_end_date)">
            {{ data.row.planned_end_date == null ? 'N/A' : $options.filters.formatDate(data.row.planned_end_date) }}
          </span>
        </template>
        <template v-if="data.column.COLUMN_NAME == 'Assign'">
          <span v-if="data.row.Assign == null">
            <a @click="AssignedUser(data.row.task_id, data.row.User_id)" :class="['text-dark', 'single-action']"
              data-placement="left">
              <em class="fa fa-user-plus"></em>
            </a>
          </span>
          <span v-else>
            <a @click="AssignedUser(data.row.task_id, data.row.User_id)" :class="['text-dark']">
              <em class="fa fa-user"></em>
              <span class="noti-circle noti-green" @mouseover="showAssignUser(data.row)"
                @mouseleave="hideAssignUser(data.row)">{{ data.row.Number }}</span>
            </a>
          </span>
          <div class="viewmoretagsbase_ptl showTags" v-if="data.row.ispopover">
            <div class="popover-arrowss_ptl"></div>
            <div class="viewmoretags_ptl">
              <span class="head" title="Prashant shukla QA">Users</span>
              <div class="outerbase">
                <span v-for="(item, index) in data.row.AssignUser" :key="index" title="test">
                  {{ index + 1 }}. {{ TruncateStr(item, 15) }}
                </span>
              </div>

            </div>
          </div>
        </template>
      </template>
    </tg-list>
    <div class="add-backlog-btn border bg-light float-left w-100 " v-if="IsCreatePermission">
      <a v-if="!IsAddBug" class="w-100 text-dark p-3 float-left" @click="AddBug" type="button"><em
          class="fa fa-plus pr-2"></em>{{
            $t('Create') }} {{ $t('Issue') }}</a>
      <div class="input-group w-100 p-3" v-if="IsAddBug">
        <div class="input-group-prepend border-right-0">
          <span class="input-group-text bg-white px-2" id="basic-addon1"><em
              class="fa fa-stop-circle epic-bug"></em></span>
        </div>
        <input type="text" @keydown.enter="SaveBug" v-model="txtBugTitle"
          class="form-control px-1 bg-white border-left-0" placeholder="What needs to be done..?" aria-label=""
          aria-describedby="basic-addon1">
        <div class="col-sm-1 pt-1">
          <a class="actions-onclick" title="Save" @click="SaveBug"><em
              class="fa fa-save action-icon text-success"></em></a>
          <a @click="IsHideAddBug" title="Close" class="actions-onclick"><em
              class="fa fa-close action-icon text-danger"></em></a>
        </div>
      </div>
    </div>
    <AssignedUser v-if="IsAssignedUser" :BacklogId="BacklogId" :AssigenedUser="AssigenedUser"
      @CallbackFunction="FetchBugListing"></AssignedUser>
    <EditTask v-if="IsEditTask" :projectdata="projectdata" @callbackfunction="UpdateTask" :NewTabName="NewTabName"
      :TabsArray="TabsArray" :modeType="modeType"></EditTask>
    <TaskBulkAction v-if="IsBulkAction" @CloseBulkAction="CloseBulkAction" :BulkActionTaskIds="BulkActionTaskIds"
      @RefreshTaskList="FetchBugListing" Type="Bug"></TaskBulkAction>
  </section>
</template>
<script>
import Schema from './BugTrackingListSchema'
import DataService from '../../../../services/DataService';
import AssignedUser from '../../../../components/Modal/AssignedUserModal.vue';
import EditTask from '../../../../components/Modal/EditTask.vue'
import TaskBulkAction from '../../../../components/Modal/TaskBulkAction.vue';
import Treeselect from '@riophae/vue-treeselect'
import '@riophae/vue-treeselect/dist/vue-treeselect.css'
export default {
  components: { AssignedUser, EditTask, TaskBulkAction,Treeselect },
  props: {
    checkPmUser: {
      type: Boolean,
      required: true
    },
    NewTabName: {
      type: String,
      require: true
    },
    TabsArray: {
      type: Array
    }
  },
  data() {
    return {
      IsBulkAction: false,
      IsCreatePermission: false,
      isLoading: false,
      LegendArray: [
        {
          class: 'fa fa-stop-circle epic-bug mr-1',
          text: (this.$t('Issue'))
        }],
      IsEditTask: false,
      ListingData: [],
      modeType: '',
      Headers: Schema.TableHeader,
      Buttons: Schema.buttons,
      listActions: Schema.listActions,
      isActionButton: true,
      widgets: [],
      StatusList: [],
      TotalRecords: 0,
      noRecord: false,
      PageSize: 10,
      PageNumber: 1,
      isPaged: 1,
      TotalPages: 0,
      SortBy: '',
      SortExp: '',
      ProjectId: 0,
      IsAssignedUser: false,
      IsAddBug: false,
      txtBugTitle: '',
      IsPriority: null,
      PriorityData: [],
      AssigenedUser: '',
      Users: [],
      selectedType: '',
      selectedStatus: null,
      selectedAssignee: null,
      projectdata: '',
      UserType: '',
      ProjectName: '',
      projectHours: '',
      BulkActionTaskIds: '',
      IsTaskName: '',
      StatusData:[],
      FilterPriorityData:[],
      PriorityFilter:null,
      _searchDebounceTimer: null
    }
  },
  computed: {
    dynamicPlaceholderr() {
      return `${this.$t(this.NewTabName)} Name...`;
    }
  },
  created: async function () {
    var ths = this;
    ths.containerName = ths.GetUserInfo.ContainerName;
    ths.CompanyId = ths.GetUserInfo.CompanyId;
    ths.UserType = ths.GetUserInfo.UserType;
    ths.ProjectId = ths.$route.params.projectId;
    ths.GetCreatePrivilage();
    ths.ProjectOverview();
    ths.StatusDropdown();
    ths.GetProjectPriority();
    ths.FetchBugListing();  
    ths.FetchMemberListing()
  },
  methods: {
    getFilterLimitText(count) {
      return `+${count}`;
    },
    normalizeSelectIds(value) {
      if (value == null) return [];
      var arr = Array.isArray(value) ? value : [value];
      return arr
        .map(function (v) {
          if (v == null) return null;
          if (typeof v === 'object') {
            return v.value != null ? v.value : (v.id != null ? v.id : null);
          }
          return v;
        })
        .filter(function (v) { return v !== null && v !== ''; });
    },
    csv(val) {     
      var ids = this.normalizeSelectIds(val);
      return ids.length ? ids.join(',') : '';
    },
    FetchMemberListing: async function () {
            var ths = this;
            var url = `id=${ths.ProjectId}&moduleName=PROJECT&type=PROJECT_USERS&search=&refId=`;
            DataService.GetDDLData(url).then((response) => {
                if (response.status == 200) {
                    if (response.data.DATA != undefined || response.data.DATA != null) {
                        if (response.data.DATA.length > 0) {
                            response.data.DATA.forEach(element => {
                                var obj = {
                                    id: element.value,
                                    label: element.name
                                }
                                ths.Users.push(obj);
                            })
                        }
                        else {
                            ths.Users = [];
                        }
                    }
                }
            });
        },
    BulkAction() {
      var val = '';
      $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
        if (val.length > 0)
          val += ',';
        val += $(this).val();
      });
      if (val.length > 0) {
        this.BulkActionTaskIds = val;
        this.IsBulkAction = true;
      } else {
        this.ShowAlert(this.$t('Selectanyrecordtodelete'), "failure", true, "Alert");
      }

    },
    CloseBulkAction() {
      this.IsBulkAction = false;
    },
    ProjectOverview: async function () {
      var vm = this;
      var params = `projectId=${vm.ProjectId}`;
      await DataService.ProjectOverview(params).then(function (response) {
        if (response.data != null > 0) {
          vm.ProjectName = response.data.projecT_NAME;
          vm.projectHours = response.data.estimateD_HOURS
        }
      });
    },
    stripHtmlTags(text) {
      if (!text) return '';
      return text.replace(/<\/?[^>]+(>|$)/g, "");
    },
    CheckDisabled() {
      if (this.UserType == 'CA' || this.UserType == 'CL' || this.UserType == 'PM' || this.UserType == 'NU' && this.checkPmUser) {
        return true;
      } else {
        if (this.UserType == 'CA' || this.UserType == 'PM') {
          this.Headers.forEach((element) => {
            if (element.COLUMN_NAME == 'Associate/DeAssociate') {
              element = element.VISIBLE = false;
            }

          });
        }
        return false;
      }
    },    
    EportTask: async function () {
      var ths = this;
      var url = 'controller=Task&action=ImportTasks'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          ths.$router.push({
            name: "UploadExcelData", params: { projectId: ths.ProjectId, projectHours: ths.projectHours }
          });
        } else {
          ths.ShowAlert(ths.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    ExportBug() {
      var vueObj = this;
      const TaskName = vueObj.IsTaskName ? vueObj.IsTaskName.trim() : '';
      const BugType = vueObj.csv(vueObj.PriorityFilter);
      const StatusId = vueObj.csv(vueObj.selectedStatus);
      const Assignee = vueObj.csv(vueObj.selectedAssignee);

      var url =
        `ProjectId=${vueObj.ProjectId}&SprintId=&Type=Bug&BugType=${BugType}&StatusId=${StatusId}` +
        `&Assignee=${Assignee}&TaskName=${encodeURIComponent(TaskName)}`;
      DataService.GetChildSprint(url).then((response) => {
        if (response.data.result.Data.length > 0) {
          vueObj.TaskJSONToCSVConvertor(response.data.result, "Bug", true);
        }
      });
    },
    TaskJSONToCSVConvertor: function (JSONData, fileName, ShowLabel) {
      var vm = this;
      var arrData = typeof JSONData != 'object' ? JSON.parse(JSONData) : JSONData;
      var CSV = '<table border="1" cellpadding="10" cellspacing="10"  aria-describedby="vuecommon">><tr>';
      if (ShowLabel) {
        var row = "";
        for (var index in vm.Headers) {
          if (vm.Headers[index].VISIBLE) {
            var displayName = vm.Headers[index].DISPLAY_NAME;
            var fieldName = vm.Headers[index].COLUMN_NAME;
            if (!(displayName || /^\s*$/.test(displayName))) {
              var chk = vm.$t(String(fieldName).toUpperCase());
              if (chk || /^\s*$/.test(chk)) {
                displayName = chk;
              }
              else {

                chk = vm.$t(String(fieldName));
                if (chk || /^\s*$/.test(chk)) {
                  displayName = chk;
                } else {
                  displayName = fieldName;
                }
              }
            }
            else {
              var chk = vm.$t(String(displayName).toUpperCase());
              if (chk || /^\s*$/.test(chk)) {
                displayName = chk;
              } else {

                chk = vm.$t(String(displayName));
                if (chk || /^\s*$/.test(chk)) {
                  displayName = chk;
                }
              }
            }
            row += ' <th scope="col">' + displayName + '</th>';
            if (fieldName == "planned_start_date" && $("#ControllerName").val() == "project") {
              displayName = "PlanEndDate";
              var chk = vm.$t(String(displayName).toUpperCase());
              if (chk || /^\s*$/.test(chk)) {
                displayName = chk;
              } else {

                chk = vm.$t(String(displayName));
                if (chk || /^\s*$/.test(chk)) {
                  displayName = chk;
                }
              }
              row += ' <th scope="col">' + displayName + '</th>';
            }
          }
        }
        if (fileName == "Lead-Detail") {
          row = row + ' <th scope="col">' + vm.$t(String("LastNote")) + '</th>';
        }
        CSV += row + '</tr>';
      }
      for (var i = 0; i < arrData.Data.length; i++) {
        var row = "<tr>";
        var j = 0;
        for (var j = 0; j < vm.Headers.length; j++) {
          if (vm.Headers[j].VISIBLE) {
            var arrValue = ''
            if (vm.Headers[j].DATA_TYPE == 'date') {
              arrValue = arrData.Data[i][vm.Headers[j].COLUMN_NAME] == null ? "" : moment(String(arrData.Data[i][vm.Headers[j].COLUMN_NAME]), "YYYY-MM-DD").format("DD/MM/YYYY");

            } else {
              arrValue = arrData.Data[i][vm.Headers[j].COLUMN_NAME] == null ? "" : arrData.Data[i][vm.Headers[j].COLUMN_NAME];
            }
            row += '<td type="' + vm.Headers[j].DATA_TYPE + '">' + arrValue + '</td>';
            if (vm.Headers[j].DATA_TYPE == 'date' && vm.Headers[j].COLUMN_NAME == "planned_start_date" && $("#ControllerName").val() == "project") {
              arrValue = arrData.Data[i]['planned_end_date'] == null ? "" : moment(String(arrData.Data[i]['planned_end_date']), "YYYY-MM-DD").format("DD/MM/YYYY");
              row += '<td type="' + vm.Headers[j].DATA_TYPE + '">' + arrValue + '</td>';
            }
          }
        }
        if (fileName == "Lead-Detail") {
          var noteHtmlData = (arrData.Data[i]["lead_note"] == null) ? "" : arrData.Data[i]["lead_note"];
          noteHtmlData = noteHtmlData.replace(/<div>/ig, "");
          noteHtmlData = noteHtmlData.replace(/<\/div>/ig, '<br style="mso-data-placement:same-cell;" />');
          var el = document.implementation.createHTMLDocument().createElement('div');
          el.innerHTML = noteHtmlData;
          noteHtmlData = el.innerHTML;
          row = row + '<td type="html" data-cell-type="html" markup="html">' + noteHtmlData + '</td>';
        }
        CSV += row + '</tr>';
      }
      CSV += "</table>";
      if (CSV == '') {
        growl.error("Invalid data");
        return;
      }
      var fileName = fileName;
      console.log(CSV)
      var uri = 'data:application/xls;charset=utf-8,' + escape(CSV);
      var link = document.createElement("a");
      link.href = uri;
      link.style = "visibility:hidden";
      link.download = fileName + ".xls";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
    },
    async GetCreatePrivilage() {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateIssue'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.IsCreatePermission = true;
        }
        else {
          vm.IsCreatePermission = false;
        }
      });
    },
    async ParentTask(ths, type) {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateIssue'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.$emit('EditTask', ths);
          vm.projectdata = ths;
          vm.modeType = type;
          vm.IsEditTask = true;
          setTimeout(function () {
            $("#modalEditTask").modal("show");
          }, 1000);
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    UpdateTask() {
      var vm = this;
      setTimeout(function () {
        $("#modalEditTask").modal("hide");
        $("body").removeClass("modal-open");
        $(".modal-backdrop").remove();
      }, 1000);
      vm.FetchBugListing();
    },
    BackToList: function () {
      var ths = this;
      ths.$router.push({ name: 'ProjectList' });
    },
    renderActions: function () {
      var self = this;
      let rtnActionArray = [];
      self.listActions.forEach(actionItem => {
        let action = { ...actionItem };
        switch (action.title) {
          case 'Edit':
            action.isVisible = true;
            break;
          case 'Delete':
            action.isVisible = true;
            break;
          default: {
            action.isVisible = true;
          }
        }
        rtnActionArray.push(action);
      });
      return rtnActionArray;
    },
    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {
        case 'DeleteData':
          this.DeleteTaskData(item.task_id);
          break;
        case 'EditBug':
          this.ParentTask(item, null);
          break;

      }
    },
    CommonPriortyUpdate(data, evt) {
      var vm = this;
      var postJSON = {
        ID: data.task_id,
        StatusId: evt.target.value,
        IsFor: 'UPDATE_PROJECT_PRIORTY'
      };
      var objectPostString = JSON.stringify(postJSON);
      DataService.CommonUpdateStatus(objectPostString).then(function (response) {
        if (response.data != null) {
          if (response.data.status === 'Success') {
            vm.FetchBugListing();
            vm.ShowAlert(vm.$t("RecordUpdatedSuccessfully"), "success", vm.$t('Alert'));
          } else {
            vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
          }
        } else {
          vm.ShowAlert(vm.$t("UnknownErrorOccur"), "failure", true, vm.$t('Alert'));
        }

      }, function () {

      });
    },
    DeleteTaskData: async function (id) {
      var vm = this;
      var val = "";
      var url = 'controller=Project&action=DeleteIssue'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.isLoading = true;
          if (id == null) {
            $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
              if (val.length > 0)
                val += ',';
              val += $(this).val();
            });
          }
          else {
            val = id;
          }
          if (val != null) {
            vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
              var postJSON = {
                ids: val,
                moduleName: "PROJECT",
                refCode: "TALYGEN_GLOBAL_TASK"
              };
              var objectPostString = JSON.stringify(postJSON);
              DataService.CommonCommonDelete(objectPostString).then(function (response) {
                vm.isLoading = false;
                if (response.data.length > 0) {
                  if (response.data[0].Status == 'Success') {
                    if (response.data[0].Code == 'TASK_ASSIGN') {
                      vm.ShowAlert(vm.$t('proceedingwithdeletion', [vm.$t('Issue')]), "failure", true, vm.$t("Alert"));
                    } else {
                      vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Issue')]), "success", true, vm.$t("Alert"));
                    }
                    vm.FetchBugListing();
                  }
                  else {
                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Issue')]), "failure", true, vm.$t("Alert"));
                  }
                }
                else {
                  vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Issue')]), "failure", true, vm.$t("Alert"));
                }
              });
            });
          }
          else {
            vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
          }
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
      vm.isLoading = false;
    },
     pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchBugListing();
        },
    commonHeaderButtonClick: function () { },
    AddNewTask() {
      var vm = this;
      vm.$emit('EditTask', null);
      vm.projectdata = null;
      vm.IsEditTask = true;
      setTimeout(function () {
        $("#modalEditTask").modal("show");
      }, 1000);
    },
    sortdata: function (s) {
      var SortDir = "sort tb_headerSortDown";
      this.SortBy = s;
      if (s === this.SortBy) {
          if (this.SortExp == "") {
              this.SortExp = "ASC";
              SortDir = "sort tb_headerSortDown";
          }
          else if (this.SortExp == "ASC") {
              this.SortExp = "DESC";
              SortDir = "sort tb_headerSortUp";
          }
          else {
              this.SortExp = "ASC";
              SortDir = "sort tb_headerSortDown";
          }
      }
      this.FetchBugListing();
      $("#" + s + '  span:first-child').attr("class", SortDir);
     },
    Clearsearch() {
      this.IsTaskName = '';
      this.PriorityFilter = null;
      this.selectedAssignee = null;
      this.selectedStatus = null;
      this.selectedType = null;
      this.PageNumber = 1;
      this.FetchBugListing();
    },
    async FetchBugListing(SearchValue = null, SerachType = null) {
      var vueObj = this;
      vueObj.ListingData = [];
      vueObj.isLoading = true;

      let priorityIds = vueObj.PriorityFilter;
      let statusIds = vueObj.selectedStatus;
      let assigneeIds = vueObj.selectedAssignee;
      let searchByName=vueObj.IsTaskName
      // When called from a specific treeselect input.
      if (SerachType === 'TASK_BY_NAME') searchByName = SearchValue;
      if (SerachType === 'TASK_BY_ASSIGN_USER') assigneeIds = SearchValue;
      if (SerachType === 'TASK_BY_PRIORITY') priorityIds = SearchValue;
      if (SerachType === 'TASK_BY_STATUS') statusIds = SearchValue;     

      var url = 'controller=Project&action=ProjectIssue'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (!response.data) {
          vueObj.isLoading = false;
          vueObj.ShowAlert(vueObj.$t('NotAuthorizedSection'), "failure", true, "Alert");
          return;
        }

      const PriorityId = vueObj.csv(priorityIds);
      const StatusId = vueObj.csv(statusIds);
      const Assignee = vueObj.csv(assigneeIds);
        const params =
          `ProjectId=${vueObj.ProjectId}&SprintId=&Type=Bug&BugType=${''}&priority=${PriorityId}&name=${encodeURIComponent(searchByName)}&StatusId=${StatusId}` +
          `&Assignee=${Assignee}`+
          `&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}` +
          `&pageSize=${vueObj.PageSize}&pageNumber=${vueObj.PageNumber}&userType=${vueObj.UserType}`;
        DataService.GetChildSprint(params).then((response) => {
          const data = response?.data?.result?.Data || [];
          if (data.length > 0) {
            vueObj.ListingData = data;
            vueObj.ListingData.forEach((x) => {
              x.ispopover = false;
              x.AssignUser = x.Assign != null ? x.Assign.split(',') : '';
             
            });
            vueObj.TotalRecords = data[0]?.TOTAL_RECORDS || 0;
            vueObj.TotalPages = Math.max(1, Math.ceil(vueObj.TotalRecords / vueObj.PageSize));
          } else {
            vueObj.ListingData = [];
            vueObj.TotalRecords = 0;
            vueObj.TotalPages = 1;
          }
          vueObj.isLoading = false;
        }).catch(() => {
          vueObj.ListingData = [];
          vueObj.TotalRecords = 0;
          vueObj.TotalPages = 1;
          vueObj.isLoading = false;
        });
      });
    },
    onFilterChange(type) {
      if (type == 'S') {
        this.selectedStatus = this.selectedStatus == '' ? 0 : this.selectedStatus;
      }
      else if (type == 'A') {
        this.selectedAssignee = this.selectedAssignee == '' ? 0 : this.selectedAssignee;
      }
      else {
        this.selectedType = this.selectedType == '' ? '' : this.selectedType;
      }
      this.FetchBugListing();
    },
    showAssignUser(row) {
      row.ispopover = true;
      this.updateRowData(row);
    },
    hideAssignUser(row) {
      row.ispopover = false;
      this.updateRowData(row);
    },
    updateRowData(updatedRow) {
      const index = this.ListingData.findIndex(row => row.task_id === updatedRow.task_id);
      if (index !== -1) {
        this.$set(this.ListingData, index, updatedRow);
      }
    },
    AssignedUser: async function (val, users) {
      var vm = this;
      var url = 'controller=Project&action=OpenAssignedUser'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.BacklogId = val;
          vm.AssigenedUser = users;
          vm.IsAssignedUser = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    AddBug() {
      this.IsAddBug = true;
    },
    StatusDropdown: function () {
      var vm = this;
      var url = `langCode=en&companyId=${vm.CompanyId}&statusType=Project&hasGlobal=true`
      DataService.StatusListing(url).then((response) => {
        if (response.data != null && response.data != "") {
          vm.StatusList = response.data.result.data;
          vm.StatusList.forEach(function (item) {
                        var obj = {
                            id: item.STATUS_ID,
                            label: item.STATUS
                        }
                        vm.StatusData.push(obj);
                    });
        }
      });
    },
    GetProjectPriority() {
      var ths=this;
      var url = `id=&moduleName=PROJECT&type=PRIORITY&search=&refId=`;
      DataService.GetDDLData(url).then((response) => {
        if (response.status == 200) {
          if (response.data.DATA != undefined || response.data.DATA != null) {
            if (response.data.DATA.length > 0) {
              ths.PriorityData = response.data.DATA;
              ths.PriorityData.forEach(function (item) {
                                var obj = {
                                    id: item.value,
                                    label: item.name
                                }
                                ths.FilterPriorityData.push(obj);
                            });
              var Pdata = this.PriorityData.filter(item => item.name === 'Low');
              if (Pdata.length > 0) {
                ths.IsPriority = Pdata[0].value;
              }
            }
          }
        }
      })
    },
    SaveBug() {
      var ths = this;
      if (ths.txtBugTitle == '' || ths.txtBugTitle == null) {
        return;
      }
      ths.isLoading = true;
      var obj = {
        BackLogId: 0,
        Project_id: ths.ProjectId,
        Subject: ths.txtBugTitle,
        IssueTypeId: 'B',
        SprintId: null,
        PriorityId: ths.IsPriority,
        StatusId: 1001,
        UserId: null,
        BackLogDescription: '',
        IsBacklog: false,
        EpicId: null,
        ParentId: null,
        Type: ''
      }
      DataService.SaveBackLog(JSON.stringify(obj)).then(function (response) {
        ths.isLoading = false;
        if (response.data.result.DATA.length > 0) {
          ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Issue')]), "success", true, ths.$t("Alert"));
          ths.FetchBugListing();
          ths.IsShowTypeCheck = false;
          ths.txtBugTitle = '';
        } else {
          ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
        }
      })
    },
    IsHideAddBug() {
      this.IsAddBug = false;
    },
    SearchFilter() {
      this.PageNumber = 1;
      this.FetchBugListing();
    },
    SearchByTaskName() {
      if (this._searchDebounceTimer) {
        clearTimeout(this._searchDebounceTimer);
      }
      this._searchDebounceTimer = setTimeout(() => {
        this.SearchFilter();
      }, 400);
    },
  }
}
</script>

