<template>
    <section>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="false" ModuleName="Event"
            SubModuleCode="Discount" IdentityColumn="discount_id" :HeaderText="$t('DiscountPromotion')"
            :ListData="ListingData" :HeaderData="Headers" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
            :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchDiscountList" :SortExp="SortExp"
            :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" v-on:ActionButtonClick="actionButtonClick"
            v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'discount_code'">
                    <a @click="AddDiscount(data.row)" class="task-dec" :title="data.row.discount_code"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.discount_code }}
                    </a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'discount_type'">
                    <span :title="data.row.discount_type == 1 ? $t('Flat') : $t('Percentage')">
                        {{ data.row.discount_type == 1 ? $t('Flat') : $t('Percentage') }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'discount_usage_type'">
                    <a :title="data.row.discount_usage_type == 1 ? $t('Unlimited') : $t('Limited')">
                        {{ data.row.discount_usage_type == 1 ? $t('Unlimited') : $t('Limited') }}
                    </a>
                </template>
            </template>
        </tg-list>
        <AddDiscountPromotion v-if="IsDiscount" :discountListData="discountListData"
            @CloseDiscountPromotion="CloseDiscountPromotion" />
    </section>
</template>
<script>
import Schema from './DiscountPromotionPortionSchema';
import DataService from '../../../../services/DataService';
import AddDiscountPromotion from '../../Event/Modals/AddDiscountPromotion.vue';
export default {
    components: { AddDiscountPromotion },
    props: {
        eventid: {
            type: Number,
            required: true
        },
    },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            MilestoneID: null,
            milestoneName: '',
            milestoneDesc: '',
            statusId: '',
            PageNumber: 1,
            StatusList: [],
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            ProjectName: '',
            taskId: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: Schema.buttons,
            IsDiscount: false,
            discountListData: [],
            Currency: '',
            Key: 0
        };
    },
    created: async function () {
        await this.FetchDiscountList();
    },
    methods: {
        renderActions: function () {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {

                    case 'AddDiscount':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchDiscountList();
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {
                case 'EditDiscount':
                    this.AddDiscount(item);
                    break;
                case 'DeleteDiscount':
                    this.DeleteDiscount(item);
                    break;

            }
        },
        commonHeaderButtonClick: async function (event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "AddDiscount":
                    vm.AddDiscount();
                    break;
                case "BackToList":
                    vm.BackToList();
                    break;
            }
        },
        AddDiscount: async function (data) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateDiscountsPromotion'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.discountListData = data;
                    vm.IsDiscount = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");                    
                }
            });
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchDiscountList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        DeleteDiscount: async function (item) {
            var vm = this;
            var url = 'controller=Project&action=DeleteDiscountsPromotion'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.isLoading = true;
                    if (item != null) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                            var postJSON = {
                                userId: vm.GetUserInfo.ID,
                                companyId: vm.GetUserInfo.CompanyId,
                                eventid: vm.projectId,
                                DiscountCode: item.discount_code,
                                DiscountType: item.discount_type,
                                DiscountValue: item.discount_currency,
                                Usages: item.discount_usage_type,
                                Starts: item.discount_start_type,
                                Ends: item.discount_end_type,
                                StartDateTime: item.discount_start_date,
                                EndDateTime: item.discount_end_date,
                                DiscountAppliedType: item.discount_applied_type,
                                ticketName: item.discount_specific_ticket_type,
                                ticketType: item.discount_specific_ticket,
                                EventType: '',
                                ActionType: 'Delete',
                                DiscountId: item.discount_id
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                vm.isLoading = false;
                                if (response.status == 200) {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('DiscountPromotion')]), "success", true, vm.$t("Alert"));
                                    vm.FetchDiscountList();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('DiscountPromotion')]), "warning", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t('Selectanyrecordtodelete'), "warning", true, vm.$t("Alert"));
                    }
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        BackToList: function () {
            this.$router.push({ name: 'ProjectList' });
        },
        CloseDiscountPromotion() {
            var ths = this;
            ths.IsDiscount = false;
            ths.FetchDiscountList();
        },
        FetchDiscountList: async function () {
            this.isLoading = true;
            const params = `id=${this.eventid}`;
            await DataService.GetDiscountPromotionListing(params).then(response => {

                const data = response.data.data;
                if (data.length > 0) {
                    this.ListingData = response.data.data;
                    this.TotalRecords = response.data.data[0].TOTALRECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);
                    this.$emit('callbackWidgets');
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
            });
        },
        OpenLinkUrl: function (item) {
            window.open('//' + item);
        },
    }
};
</script>
