          if (!res) return;
          if (res.STATUSDATA != null && res.STATUSDATA.length > 0) {
            this.IsTaskType = true;
            this.bindComponentChartDataa(res.STATUSDATA);
          } else this.IsTaskType = false;
          if (res.SPRINTDATA != null && res.SPRINTDATA.length > 0) {
            this.IsSprintType = true;
            this.bindComponentSprintChartDataa(res.SPRINTDATA);
          } else {
            this.IsSprintType = false;
            this.sprintSeries = [];
          }
