<template>
  <section class="project-kanban-overview">
     <div class="projectoverviewbase">
    <CommonDashboard 
    ref="commonDashboard" 
    :project-id="projectId" 
    :check-pm-user="checkPmUser"
      :new-tab-name="NewTabName" 
      :tabs-array="TabsArray" 
      :Template_Name="Template_Name"
      @AddView="$emit('AddView', $event)" />
    <div class="card col-md-12 p-0 mb-3 mc-top-card">
      <div class="card-body col-12 pt-3 pb-4 px-3 common-dashboard-shell">
        <!-- <div class="kb-wip-row">
          <div v-for="(col, idx) in columnCards" :key="'wip-' + idx" class="kb-wip-col">
            <div class="kb-wip-card" :style="{
              borderTopColor: col.tint,
              background: `linear-gradient(180deg, ${lightColor(col.tint)} 0%, #ffffff 55%)`
            }">
              <div class="kb-wip-title">{{ col.title }}</div>
              <div class="kb-wip-count">{{ col.count }}</div>
              <div class="kb-wip-sub">{{ col.subtitle }} {{ col.limit }}</div>
              <div v-if="col.stateText" class="kb-wip-foot" :class="'kb-wip-foot--' + col.state">
                <em class="fa kb-wip-foot-icon" :class="col.iconClass" aria-hidden="true"></em>
                <span>{{ col.stateText }}</span>
              </div>
            </div>
          </div>
        </div> -->


        <div class="row mx-0 mcc-chart-row align-items-stretch">
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Cycle time trend (days)</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts v-if="hasCycleChart" type="area" height="280" :options="cycleChartOptions"
                  :series="cycleChartSeries" :key="'kb-cy-' + chartKey" />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Lead time distribution</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts v-if="hasLeadChart" type="bar" height="280" :options="leadChartOptions"
                  :series="leadChartSeries" :key="'kb-ld-' + chartKey" />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Weekly throughput</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts v-if="hasThroughputChart" type="bar" height="280" :options="throughputChartOptions"
                  :series="throughputChartSeries" :key="'kb-th-' + chartKey" />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
        </div>

        <div class="row mx-0">
          <div class="col-12 px-2 section_pp">
            <div class="section mcc-overdue-section">
              <div class="section-header reddy cd-panel-head mcc-od-head">
                <span class="cd-panel-title mcc-od-title-wrap">
                  <em class="fa fa-bolt mcc-od-bolt" aria-hidden="true"></em>
                  <span>
                    <span class="mcc-od-title-main">Bottleneck tasks</span>
                    <span class="mcc-od-title-sub"> — Stuck &gt; 4 days in a column</span>
                  </span>
                </span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="kb-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
              </div>
              <div class="section-body border p-0">
                <div class="table-responsive mcc-od-wrap">
                  <table class="table mb-0 mcc-od-table">
                    <thead>
                      <tr>
                        <th>{{ $t('Key') }}</th>
                        <th>{{ $t('TaskName') }}</th>
                        <th>{{ $t('Created By') }}</th>
                        <th>{{ $t('Days') }} stuck</th>
                        <th>{{ $t('Asignee') }}</th>
                        <th>{{ $t('Environment') }}</th>
                        <th>{{ $t('Component') }}</th>
                        <th>{{ $t('Status') }}</th>
                        <th>{{ $t('Pirority') }}</th>
                      </tr>
                    </thead>
                    <tbody>
                      <tr v-for="(row, idx) in bottleneckTasks" :key="'bn-' + idx" :class="bottleneckRowClass(row)">
                        <td class="kb-bn-key-cell">
                          <span v-if="row.task_type === 'T'" class="kb-bn-type-ico" title="Task">
                            <em class="fa fa-check-square text-primary"></em>
                          </span>
                          <span v-else-if="row.task_type === 'S'" class="kb-bn-type-ico" title="Story">
                            <em class="fa fa-film text-success"></em>
                          </span>
                          <span v-else-if="row.task_type === 'B'" class="kb-bn-type-ico" title="Issue">
                            <em class="fa fa-warning text-danger"></em>
                          </span>
                          <span class="kb-bn-key-tag">{{ row.task_number || '—' }}</span>
                        </td>
                        <td :title="row.task_name" class="kb-bn-task">{{ truncate(row.task_name, 48) }}</td>
                        <td  :title="row.Created_by" class="kb-bn-meta">{{ row.Created_by || '—' }}</td>
                        <td :title="row.daysStuck" class="kb-bn-days-stuck">{{ formatDaysStuck(row.daysStuck != null ? row.daysStuck :
                          row.days_in_column) }}</td>
                        <td class="kb-bn-assignee-cell">
                          <div class="kb-bn-assignee-line">
                            <div v-if="row.AssignUser && row.AssignUser.length"
                              class="user-count-wrapper d-inline-block ml-1" @mouseover="showAssignUser(row)"
                              @mouseleave="hideAssignUser(row)">
                              <a href="javascript:;" class="kb-bn-assignee-more" @click.prevent>
                                <em class="fa fa-user"></em>
                                <span class="noti-circle noti-green">{{ row.TotalUserCount != null ? row.TotalUserCount
                                  : row.AssignUser.length }}</span>
                              </a>
                              <div class="viewmoretagsbase_ptl showTags" v-if="row.ispopover">
                                <div class="popover-arrowss_ptl"></div>
                                <div class="viewmoretags_ptl">
                                  <span class="head">{{ teamTabLabel }}</span>
                                  <div class="outerbase">
                                    <span v-for="(item, index) in row.AssignUser" :key="index">{{ index + 1 }}. {{
                                      truncate(item, 15) }}</span>
                                  </div>
                                </div>
                              </div>
                            </div>
                            <div v-else>
                              <span>--</span>
                            </div>
                          </div>
                        </td>
                        <td :title="row.environment_name" class="kb-bn-meta">{{ row.environment_name || row.Environment || '—' }}</td>
                        <td :title="row.component_name" class="kb-bn-meta">{{ row.component_name || row.Component || '—' }}</td>
                        <td :title="currentColumnLabel(row)">
                          <span class="kb-col-pill" :class="pillClassForColumn(currentColumnLabel(row))">{{
                            currentColumnLabel(row) }}</span>
                        </td>
                        <td class="kb-action-cell" :title="row.priority_name">
                          <span class="kb-col-pill" :class="priorityPillClass(row.priority_name)">{{ row.priority_name
                            || '—' }}</span>
                        </td>
                      </tr>
                      <tr v-if="!bottleneckTasks.length">
                        <td colspan="9" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <CriticalandBlockerDetail v-if="isCriticalandBlockerDetail" :Type="Template_Name" :HeaderText="'Bottleneck tasks — Stuck > 4 days in a column'"/>
      </div>
  </section> 
</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';
function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}
export default {
  name: 'ProjectKanbanOverView',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail },
  props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
  },
  data() {
    return {
      isCriticalandBlockerDetail:false,
      chartKey: 0,
      columnCards: [],
      hasCycleChart: false,
      hasLeadChart: false,
      hasThroughputChart: false,
      cycleChartSeries: [],
      cycleChartOptions: {
        chart: { type: 'area', toolbar: { show: false }, fontFamily: 'inherit', zoom: { enabled: false } },
        colors: ['#2563eb'],
        fill: {
          type: 'gradient',
          gradient: { shadeIntensity: 0.45, opacityFrom: 0.45, opacityTo: 0.05, stops: [0, 90, 100] },
        },
        stroke: { curve: 'smooth', width: 2 },
        dataLabels: { enabled: false },
        xaxis: { categories: ['Week 1', 'Week 2', 'Week 3', 'Week 4'], labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
        tooltip: { y: { formatter: (val) => `${val} d` } },
      },
      leadChartSeries: [],
      leadChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: { bar: { borderRadius: 6, columnWidth: '62%', distributed: true, horizontal: false } },
        colors: ['#22c55e', '#14b8a6', '#eab308', '#fb923c', '#ef4444'],
        dataLabels: { enabled: false },
        xaxis: { categories: ['1-2d', '3-5d', '6-10d', '11-14d', '>14d'], labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
      },
      throughputChartSeries: [],
      throughputChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: { bar: { borderRadius: 6, columnWidth: '52%', colors: { ranges: [] } } },
        colors: ['#2563eb'],
        dataLabels: { enabled: false },
        xaxis: { categories: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'], labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
      },
      bottleneckTasks: [],
    };
  },
  computed: {
    templateTag() {
      const t = (this.Template_Name || 'KANBAN').toString();
      return t.toUpperCase();
    },
    teamTabLabel() {
      const row = (this.TabsArray || []).find((t) => t.displayCode === 'PROJECT_TEAM');
      return row && row.displayName ? this.$t(row.displayName) : this.$t('Team');
    },
  },
  watch: {
    projectId() {
      this.loadChartData();
    },
  },
  mounted() {
    this.loadChartData();
  },
  methods: {
    openDashboardAddView() {
     this.isCriticalandBlockerDetail=true;
    },
    truncate(str, len) {
      if (str == null || str === '') return '—';
      const s = String(str);
      return s.length > len ? s.slice(0, len - 1) + '…' : s;
    },
    currentColumnLabel(row) {
      if (!row) return '—';
      const v =
        row.current_column ||
        row.board_column_name ||
        row.column_name ||
        row.BOARD_COLUMN_NAME ||
        row.KANBAN_COLUMN ||
        row.kanban_column;
      if (v != null && String(v).trim() !== '') return String(v).trim();
      return row.status_name && String(row.status_name).trim() !== '' ? String(row.status_name).trim() : '—';
    },
    assigneePrimary(row) {
      if (!row) return this.$t('Unassigned');
      if (row.AssignUser && row.AssignUser.length) {
        const first = row.AssignUser[0];
        if (first != null && String(first).trim() !== '') return String(first).trim();
      }
      if (row.Assign && String(row.Assign).trim() !== '') {
        return String(row.Assign)
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean)[0];
      }
      if (row.assignee && String(row.assignee).trim()) return String(row.assignee).trim();
      if (row.assignee_name && String(row.assignee_name).trim()) return String(row.assignee_name).trim();
      return this.$t('Unassigned');
    },
    bottleneckRowClass(row) {
      const dRaw = row.daysStuck != null ? row.daysStuck : row.days_in_column;
      const d = Number(dRaw);
      if (Number.isFinite(d)) {
        if (d >= 7) return 'kb-row--rose';
        if (d >= 5) return 'kb-row--amber';
        return '';
      }
      return this.rowTintForColumn(this.currentColumnLabel(row));
    },
    formatDaysStuck(v) {
      if (v == null || v === '' || v === '—') return '—';
      const num = Number(v);
      if (Number.isFinite(num)) {
        return `${num} ${num === 1 ? 'day' : 'days'}`;
      }
      return String(v);
    },
    loadChartData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          if (!res) {
            //this.columnCards = [];
            this.bottleneckTasks = [];
            return;
          }
          //this.columnCards = Array.isArray(res.WIDGETDATA) ? res.WIDGETDATA : [];
          this.bottleneckTasks = (res.CRITICALBLOCKERBUGS || []).map((x) => {
            const assignList = x.Assign
              ? String(x.Assign)
                .split(',')
                .map((s) => s.trim())
                .filter(Boolean)
              : [];
            return {
              ...x,
              ispopover: false,
              AssignUser: assignList,
              environment_name: x.environment_name || x.Environment,
              component_name: x.component_name || x.Component,
            };
          });
          this.applyPayload(res);
          this.$nextTick(() => {
            this.chartKey++;
          });
        })
        .catch((e) => console.error('Kanban template overview load:', e));
    },
    applyPayload(res) {
      const kt = res.KANBAN_TEMPLATE || res.kanban_template || {};
      const kb = res.KANBAN_DASHBOARD || res.KANBAN_OVERVIEW || res.kanban_dashboard || {};
      const merged = { ...kb, ...kt };

      if (Array.isArray(res.TASKCYCLE) && res.TASKCYCLE.length) {
        this.bindCycleChart(res.TASKCYCLE);
      } else if (merged.cycleTimeSeries) {
        this.bindCycleChartFromSeries(merged.cycleTimeCategories, merged.cycleTimeSeries);
      } else if (Array.isArray(res.WIDGETDATA) && res.WIDGETDATA.length) {
        this.buildSyntheticCycleChart(res);
      } else {
       // this.buildSyntheticCycleChart(res);
      }

      if (Array.isArray(res.LEADTIME) && res.LEADTIME.length) {
        this.bindLeadChart(res.LEADTIME);
      } else {
        this.buildSyntheticLeadChart(res.PRIORITYDATA, res.STATUSDATA);
      }

      if (Array.isArray(res.THOUGHTPUT) && res.THOUGHTPUT.length) {
        this.bindThroughputChart(res.THOUGHTPUT);
      } else {
       // this.buildSyntheticThroughput(res);
      }
    },
    showAssignUser(itm) {
      if (itm.AssignUser && itm.AssignUser.length) {
        this.$set(itm, 'ispopover', true);
      }
    },
    hideAssignUser(itm) {
      this.$set(itm, 'ispopover', false);
    },

    bindCycleChart(rows) {
      const categories = rows.map((r) => r.label || r.week_label || r.name || '');
      const data = rows.map((r) => n(r.avg_cycle_time ?? r.value, 0));
      this.hasCycleChart = categories.length > 0;
      this.cycleChartSeries = [{ name: 'Days', data }];
      this.cycleChartOptions = {
        ...this.cycleChartOptions,
        xaxis: { ...this.cycleChartOptions.xaxis, categories },
      };
    },
    bindCycleChartFromSeries(categories, series) {
      const cats = Array.isArray(categories) ? categories : ['W1', 'W2', 'W3', 'W4'];
      const data = Array.isArray(series) ? series.map((x) => n(x, 0)) : [];
      this.hasCycleChart = data.length > 0;
      this.cycleChartSeries = [{ name: 'Days', data }];
      this.cycleChartOptions = { ...this.cycleChartOptions, xaxis: { ...this.cycleChartOptions.xaxis, categories: cats } };
    },
    buildSyntheticCycleChart(res) {
      if(res.STATUSDATA.length==0) return;
      const total = (res.STATUSDATA || []).reduce((a, x) => a + n(x.total_count, 0), 0);
      const base = Math.max(3.2, Math.min(5.2, 3.5 + Math.min(total, 20) * 0.04));
      const data = [0, 1, 2, 3].map((i) => Number((base + Math.sin(i) * 0.35).toFixed(1)));
      this.hasCycleChart = true;
      this.cycleChartSeries = [{ name: 'Days', data }];
    },
    bindLeadChart(rows) {
      const categories = rows.map((r) => r.label || r.bucket || '');
      const data = rows.map((r) => n(r.task_count ?? r.value, 0));
      this.hasLeadChart = categories.length > 0;
      this.leadChartSeries = [{ name: 'Tasks', data }];
      this.leadChartOptions = {
        ...this.leadChartOptions,
        xaxis: { ...this.leadChartOptions.xaxis, categories },
      };
    },
    buildSyntheticLeadChart(priorityData, statusData) {
      const rows = Array.isArray(statusData) ? statusData : [];
      const pri = Array.isArray(priorityData) ? priorityData : [];
      const src = rows.length >= 5 ? rows : pri.length ? pri : rows;
      const categories = ['1-2d', '3-4d', '5-7d', '8-14d', '>14d'];
      let raw = src.slice(0, 5).map((x) => n(x.total_count, 0));
      while (raw.length < 5) raw.push(0);
      const sum = raw.reduce((a, b) => a + b, 0);
      if (!sum) {
        this.hasLeadChart = false;
        this.leadChartSeries = [];
        this.leadChartOptions = {
          ...this.leadChartOptions,
          xaxis: { ...this.leadChartOptions.xaxis, categories },
        };
        return;
      }
      const scale = Math.min(24, 8 + sum * 2);
      const data = raw.map((c) => Math.max(0, Math.round((c / sum) * scale)));
      this.hasLeadChart = data.some((v) => v > 0);
      this.leadChartSeries = [{ name: 'Tasks', data }];
      this.leadChartOptions = {
        ...this.leadChartOptions,
        xaxis: { ...this.leadChartOptions.xaxis, categories },
      };
    },
    bindThroughputChart(rows) {
      const categories = rows.map((r) => r.label || r.day_name || '');
      const data = rows.map((r) => n(r.tasks_completed ?? r.value, 0));
      this.hasThroughputChart = categories.length > 0;
      this.throughputChartSeries = [{ name: 'Items', data }];
      this.throughputChartOptions = {
        ...this.throughputChartOptions,
        xaxis: { ...this.throughputChartOptions.xaxis, categories },
      };
    },
    buildSyntheticThroughput(res) {
      const total = (res.STATUSDATA || []).reduce((a, x) => a + n(x.total_count, 0), 0);
      const base = Math.max(1, Math.round(total / 5) || 2);
      const data = [0, 1, 2, 3, 4].map((i) => Math.max(0, Math.round(base * (0.6 + (i % 3) * 0.2))));
      this.hasThroughputChart = data.some((v) => v > 0);
      this.throughputChartSeries = [{ name: 'Items', data }];
    },
    normalizeBottleneck(b) {
      const col = b.column || b.current_column || b.status_name || '—';
      const full =
        b.assignee_full ||
        b.assigneeFull ||
        (b.Assign && String(b.Assign).trim()) ||
        b.assignee ||
        b.assignee_name ||
        '';
      const primary =
        b.assignee ||
        b.assignee_name ||
        (full
          ? String(full)
            .split(',')
            .map((x) => x.trim())
            .filter(Boolean)[0]
          : '') ||
        this.$t('Unassigned');
      return {
        key: b.key || b.task_number || '—',
        task: b.task || b.task_name || '—',
        column: col,
        columnPillClass: this.pillClassForColumn(col),
        daysStuck: b.days_stuck != null ? b.days_stuck : b.daysStuck != null ? b.daysStuck : '—',
        assignee: primary,
        assigneeFull: full || primary,
        rowTint: b.rowTint || this.rowTintForColumn(col),
      };
    },
    buildBottlenecksFromCritical(list) {
      if (!Array.isArray(list) || !list.length) return [];
      return list.slice(0, 8).map((item) => {
        const col = item.status_name || '—';
        const full =
          item.Assign && String(item.Assign).trim()
            ? String(item.Assign)
              .split(',')
              .map((x) => x.trim())
              .filter(Boolean)
              .join(', ')
            : '';
        const assignee = full ? full.split(',')[0].trim() : this.$t('Unassigned');
        return {
          key: item.task_number || '—',
          task: item.task_name || '—',
          column: col,
          columnPillClass: this.pillClassForColumn(col),
          daysStuck: item.days_in_column != null ? item.days_in_column : '—',
          assignee,
          assigneeFull: full || assignee,
          rowTint: this.rowTintForColumn(col),
        };
      });
    },
    pillClassForColumn(name) {
      const s = String(name).toLowerCase();
      if (!s || s === '—') return 'kb-pill--muted';
      if (s.includes('prospect')) return 'kb-pill--purple';
      if (s.includes('qualif')) return 'kb-pill--blue';
      if (s.includes('proposal')) return 'kb-pill--indigo';
      if (s.includes('negot')) return 'kb-pill--amber';
      if (s.includes('progress') || s.includes('active')) return 'kb-pill--rose';
      if (s.includes('review')) return 'kb-pill--amber';
      if (s.includes('complete') || s.includes('done') || s.includes('won')) return 'kb-pill--green';
      if (s.includes('ready')) return 'kb-pill--blue';
      return 'kb-pill--muted';
    },
    /** Soft pills (light bg + dark text) — same visual language as Status / Current column */
    priorityPillClass(name) {
      const s = String(name || '').toLowerCase();
      if (!s || s === '—') return 'kb-pill--muted';
      if (s.includes('critical') || s.includes('blocker')) return 'kb-pill-soft--critical';
      if (s.includes('high')) return 'kb-pill-soft--high';
      if (s.includes('medium')) return 'kb-pill-soft--medium';
      if (s.includes('low')) return 'kb-pill-soft--low';
      return 'kb-pill--muted';
    },
    rowTintForColumn(name) {
      const s = String(name).toLowerCase();
      if (s.includes('progress') || s.includes('active')) return 'kb-row--rose';
      if (s.includes('review')) return 'kb-row--amber';
      return 'kb-row--warm';
    },
    lightColor(color) {
      // simple lighten logic
      return color + '20'; // adds opacity (works for hex like #f9ab00)
    }
