<template>
  <div class="my-popups">
    <div class="modal d-block">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header theme-primary partition-full d-flex">
            <h4 class="modal-title">{{ $t('Add') }} {{ $t('Envirement') }}</h4>
            <button type="button" class="close" @click="Close">
              <em class="fa fa-times" aria-hidden="true"></em>
            </button>
          </div>
          <div class="modal-body">
            <dynamic-form
              ref="environmentForm"
              lang="en"
              :schema="FormSchema"
              :buttons="buttons"
              :mandatorytext="MandatoryString"
              @OnSubmit="OnSubmit"
            />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { Array } from 'core-js';
import DataService from '../../services/DataService';
export default {
  props:{
    EnvireomentData:{
      type:Array || Object,
      require:false
    }
  },
  data() {
    return {
      MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
      FormSchema: [
        {
          layoutType: 'single',
          Data: [
            {
              astype: 'TextField',
              label: this.$t('Environment Name'),
              name: 'EnvironmentName',
              value: '',
              placeholder: this.$t('Enter Environment Name'),
              validationRules: { required: true, max: 200 }
            },
            {
              astype: 'TextAreaField',
              label: this.$t('Environment Description'),
              name: 'EnvironmentDescription',
              value: '',
              placeholder: this.$t('Enter Environment Description'),
              validationRules: { required: true, max: 4000 },
              config: { rows: 4 }
            }
          ]
        }
      ],
      buttons: [
        {
          type: 'submit',
          class: 'btn btn-success',
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: true
        },
        {
          type: 'button',
          class: 'btn btn-danger',
          text: "<i class='fa fa-close pr-2'></i>Cancel",
          onClick: this.Close
        }
      ],
      EnviromentId:0,
    }
  },
  created(){
    if(this.EnvireomentData){this.EditDetail(this.EnvireomentData)}
  },
  methods: {
    EditDetail(data){
      this.EnviromentId=data.environment_id;
      this.FormSchema[0].Data[0].value=data.environment_name;
      this.FormSchema[0].Data[1].value=data.environment_desc
    },
     OnSubmit:async function(){
              var ths = this;
              ths.isLoading=true;                                  
              var obj = {
                Id: this.EnviromentId ?? 0,
                Project_id:ths.$route.params.projectId,
                Subject:ths.FormSchema[0].Data[0].value,
                StatusId:1001,
                Description:ths.FormSchema[0].Data[1].value,
                Type:'Environment'
            } 
              await DataService.AddComponentAndEnvironment(JSON.stringify(obj)).then(function (response) { 
                  ths.isLoading=false;
                  if(response.data.result.DATA.length>0){ 
                      if(response.data.result.DATA[0].VALUE=='UPDATE') {
                          ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t('Enviroment')]),"success", true, ths.$t("Alert"));
                      }
                      else if(response.data.result.DATA[0].VALUE=='EXISTS') {
                          ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Enviroment')]),"failure", true, ths.$t("Alert"));
                      }
                      else{
                          ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Enviroment')]), "success", true,  ths.$t("Alert"));
                      } 
                      ths.Close();
                      ths.$parent.FetchData();
                  }else{
                      ths.ShowAlert(ths.$t("UnknownErrorOccur"), "failure", true, ths.$t('Alert'));
                  }
              })
          },
    Close() {
      this.FormSchema[0].Data[0].value='';
      this.FormSchema[0].Data[1].value='';
      this.$refs.environmentForm.UpdateKeyValue();
      this.$emit('close')
    }
  }
}
</script>
