<template>
  <section class="project-content-calendar-overview">
     <div class="projectoverviewbase">
    <CommonDashboard
      ref="commonDashboard"
      :project-id="projectId"
      :check-pm-user="checkPmUser"
      :new-tab-name="NewTabName"
      :tabs-array="TabsArray"
      :Template_Name="Template_Name"
      @AddView="$emit('AddView', $event)"
    />
    <div class="card col-md-12 p-0 mb-3 mcc-top-card">
      <div class="card-body col-12 pt-3 pb-4 px-3 common-dashboard-shell">
        <!-- <div class="mcc-intel-head d-flex flex-wrap align-items-center justify-content-between gap-3 mb-4">
          <div class="mcc-intel-brand d-flex flex-wrap align-items-center">
            <em class="fa fa-star mcc-intel-star" aria-hidden="true"></em>
            <span class="mcc-intel-title">Template Intelligence</span>
            <span class="mcc-template-badge">{{ templateTag }}</span>
          </div>
          <small class="mcc-intel-note text-muted mb-0">Widgets automatically adapt to your project template.</small>
        </div> -->

        <!-- <div class="mcc-kpi-row">
          <div v-for="(k, idx) in kpiCards" :key="'kpi-' + idx" class="mcc-kpi-col">
            <div class="mcc-kpi-card" :class="'mcc-kpi-card--' + k.tint">
              <div class="mcc-kpi-value">{{ k.value }}</div>
              <div class="mcc-kpi-label">{{ k.label }}</div>
            </div>
          </div>
        </div> -->

        <div class="row mx-0 mcc-chart-row align-items-stretch">
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Content Pipeline By Stage</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasPipelineChart"
                  type="bar"
                  height="300"
                  :options="pipelineChartOptions"
                  :series="pipelineChartSeries"
                  :key="'mcc-pl-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Content By Type</span>
              </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasTypeDonut"
                  type="donut"
                  height="300"
                  :options="typeDonutOptions"
                  :series="typeDonutSeries"
                  :key="'mcc-ty-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">
                  <!-- <span class="mcc-cal-emoji" aria-hidden="true">&#128197;</span> -->
                    <em class="fa fa-calendar"></em>
                  Publish This Week
                </span>
              </div>
              <div class="section-body border py-2 mcc-chart-body mcc-publish-list-body">
                <ul v-if="publishWeekItems.length" class="mcc-publish-list list-unstyled mb-0">
                  <li v-for="(it, idx) in publishWeekItems" :key="'pw-' + idx" class="mcc-publish-item">
                    <div class="mcc-publish-title" :title="it.title">{{ truncate(it.title, 44) }}</div>
                    <div class="mcc-publish-date" :class="'mcc-publish-date--' + it.urgency">{{ it.dateLabel }}</div>
                  </li>
                </ul>
                <div v-else class="mcc-no-chart mcc-no-chart--compact">{{ $t('NoRecordfound') }}</div>
              </div>
            </div>
          </div>
        </div>

        <div class="row mx-0">
          <div class="col-12 px-2 section_pp">
            <div class="section mcc-overdue-section">
              <div class="section-header reddy cd-panel-head mcc-od-head">
                <span class="cd-panel-title mcc-od-title-wrap">
                  <em class="fa fa-exclamation-triangle mcc-od-icon" aria-hidden="true"></em>
                  <span class="mcc-od-title-main">Overdue &amp; Unpublished Content</span>
                </span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="mcc-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
              </div>
              <div class="section-body border p-0">
                <div class="table-responsive mcc-od-wrap">
                  <table class="table mb-0 mcc-od-table">
                    <thead>
                      <tr>
                        <th># {{ $t('Key') }} / {{ $t('TaskName') }}</th>
                        <th>{{ $t('Type') }}</th>
                        <th>{{ $t('created_by_name') }}</th>
                        <th>{{ $t('SACreatedAt') }}</th>
                        <th>{{ $t('TillDate') }}</th>
                        <th>{{ $t('Assign') }}</th>
                        <th>{{ $t('SAStatus') }}</th>
                        <th>{{ $t('Priority') }}</th>
                       
                      </tr>
                    </thead>
                    <tbody>
                      
                      <tr  v-for="(row, idx) in overdueRows"    :key="'od-' + idx"  :class="row.rowClass">
                        <td class="mcc-od-title" :title="row.title">{{ truncate(row.title, 52) }}</td>
                        <td>{{ $t(row.stage == 'T' ? 'Task' : row.stage == 'S' ? 'Story' : row.stage == 'B' ? 'Issue' : '—') }}</td>
                        <td :title="row.author">{{ row.author || '—' }}</td>
                        <td :title="formatCellDate(row.plannedLabel)">{{ formatCellDate(row.plannedLabel) }}</td>
                        <td :title="formatCellDate(row.daysOverdueLabel)">{{ formatCellDate(row.daysOverdueLabel) }}</td>
                        <td class="text-center">
                          {{ row.AssignUser }}
                          <div class="d-block ">                            
                            <div
                              v-if="row.AssignUser && row.AssignUser.length"
                              class="user-count-wrapper d-inline-block ml-1"
                              @mouseover="showAssignUser(row)"
                              @mouseleave="hideAssignUser(row)"
                            >
                              <a href="javascript:;" class="kb-bn-assignee-more disabled" @click.prevent>
                                <em class="fa fa-user"></em>
                                <span class="noti-circle noti-green">{{ row.TotalUserCount != null ? row.TotalUserCount : row.AssignUser.length }}</span>
                              </a>
                              <div class="viewmoretagsbase_ptl showTags" v-if="row.ispopover">
                                <div class="popover-arrowss_ptl"></div>
                                <div class="viewmoretags_ptl">
                                  <span class="head">Users</span>
                                  <div class="outerbase">
                                    <span v-for="(row, index) in row.AssignUser" :key="index">{{ index + 1 }}. {{ truncate(item, 15) }}</span>
                                  </div>
                                </div>
                              </div>
                            </div>
                            <div v-else>
                              <span>--</span>
                            </div>
                          </div>
                        </td>
                        <td :title="row.status">
                          <span class="mcc-stage-pill text-white" :style="{ backgroundColor: row.statusrowClass }">{{ row.status || '—' }}</span>
                        </td>
                        <td :title="row.pirorit">
                          <span class="mcc-stage-pill text-white" :style="{ backgroundColor: row.priorityrowClass }">{{ row.pirority || '—' }}</span>
                        </td>
                      </tr>
                      <tr v-if="!overdueRows.length">
                        <td colspan="8" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
                      </tr>
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    <CriticalandBlockerDetail v-if="isCriticalandBlockerDetail" :Type="Template_Name"  :HeaderText="'Overdue &amp; Unpublished Content'"/>
    </div>
  </section>
</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';
function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}

/** Optional API: CONTENT_CALENDAR_DASHBOARD = { kpis, pipeline_stages[], content_by_type[], publish_this_week[], overdue_content[] } */

const PIPELINE_DEFAULT = [];
const PIPELINE_COLORS = ['#9333ea', '#1a73e8', '#f9ab00', '#34a853', '#0d9488'];
const TYPE_COLORS = ['#1a73e8', '#ec4899', '#f9ab00', '#ea4335'];

const DEFAULT_PUBLISH_WEEK = [
];

const DEFAULT_OVERDUE = [

];

export default {
  name: 'ProjectMarketingContentOverView',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail },
  props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
  },
  data() {
    return {
      isCriticalandBlockerDetail:false,
      chartKey: 0,
      kpiCards: [],
      hasPipelineChart: false,
      pipelineChartSeries: [],
      pipelineChartOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
        plotOptions: {
          bar: {
            horizontal: true,
            barHeight: '72%',
            borderRadius: 4,
            distributed: true,
            dataLabels: { position: 'end' },
          },
        },
        dataLabels: {
          enabled: true,
          formatter: (val) => String(n(val, 0)),
          style: { fontSize: '11px', fontWeight: 700, colors: ['#202124'] },
          offsetX: 8,
          dropShadow: { enabled: false },
        },
        colors: [...PIPELINE_COLORS],
        xaxis: { labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
      },
      hasTypeDonut: false,
      typeDonutSeries: [],
      typeDonutOptions: {
        chart: { type: 'donut', toolbar: { show: false }, fontFamily: 'inherit' },
        labels: [],
        colors: [...TYPE_COLORS],
        dataLabels: { enabled: false },
        legend: { position: 'bottom', fontSize: '12px', fontWeight: 600 },
        plotOptions: {
          pie: {
            donut: { size: '68%', labels: { show: false } },
          },
        },
      },
      publishWeekItems: [],
      overdueRows: [],
      BacklogId: null,
      AssigenedUser: null,
      IsAssignedUser: false,
    };
  },
  computed: {
    templateTag() {
      const raw = (this.Template_Name || 'CONTENT CALENDAR').toString();
      return raw.replace(/_/g, ' ').toUpperCase();
    },
  },
  watch: {
    projectId() {
      this.loadChartData();
    },
  },
  mounted() {
    this.loadChartData();
  },
  methods: {
    openDashboardAddView() {
     this.isCriticalandBlockerDetail=true;
    },
    truncate(str, len) {
      if (str == null || str === '') return '—';
      const s = String(str);
      return s.length > len ? `${s.slice(0, len - 1)}…` : s;
    },
    loadChartData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          this.applyContentPayload(res || {});
          this.$nextTick(() => {
            this.chartKey += 1;
          });
        })
        .catch((e) => {
          console.error('Marketing content calendar overview load:', e);
          this.applyContentPayload({});
        });
    },
    applyContentPayload(res) {
      const cd = res.CONTENT_CALENDAR_DASHBOARD || res.content_calendar_dashboard || {};
      //this.bindKpis(cd, res);
      this.bindPipelineChart(cd, res);
      this.bindTypeDonut(cd, res);
      this.bindPublishWeek(cd, res);
      this.bindOverdueTable(cd, res);
    },
    // bindKpis(cd, res) {
    //   const k = cd.kpis || cd.kpi || {};
    //   let published = k.published_this_month ?? cd.published_this_month;
    //   let inReview = k.in_review_draft ?? cd.in_review_draft;
    //   let overdue = k.overdue_missed ?? cd.overdue_missed;
    //   let scheduled = k.scheduled_next_7_days ?? cd.scheduled_next_7_days;

    //   const statusRows = Array.isArray(res.STATUSDATA) ? res.STATUSDATA : [];
    //   const doneLike = statusRows.filter((x) => {
    //     const s = String(x.status_name || '').toLowerCase();
    //     return s.includes('done') || s.includes('complete') || s.includes('publish');
    //   });
    //   const reviewLike = statusRows.filter((x) => {
    //     const s = String(x.status_name || '').toLowerCase();
    //     return s.includes('review') || s.includes('draft') || s.includes('progress');
    //   });

    //   if (published == null) {
    //     published = doneLike.reduce((a, x) => a + n(x.total_count, 0), 0) || 12;
    //   }
    //   if (inReview == null) {
    //     inReview = reviewLike.reduce((a, x) => a + n(x.total_count, 0), 0) || 8;
    //   }
    //   if (overdue == null) {
    //     overdue = n(cd.overdue_count, 0) || (Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS.length : 0) || 5;
    //   }
    //   if (scheduled == null) {
    //     scheduled = 6;
    //   }

    //   this.kpiCards = [
    //     { label: 'Published this month', value: n(published, 12), tint: 'blue' },
    //     { label: 'In review / draft', value: n(inReview, 8), tint: 'amber' },
    //     { label: 'Overdue / missed', value: n(overdue, 5), tint: 'rose' },
    //     { label: 'Scheduled next 7 days', value: n(scheduled, 6), tint: 'green' },
    //   ];
    // },
    bindPipelineChart(cd, res) {
      let rows = cd.pipeline_stages || cd.content_pipeline;
      if (!Array.isArray(rows) || !rows.length) {
        const staged = Array.isArray(res.STAGEDATA) ? res.STAGEDATA : [];
        if (staged.length) {
          rows = staged.map((x) => ({
            label: x.stage_name || x.name || 'Stage',
            count: n(x.stage_progress ?? x.total_count ?? x.count, 0),
          }));
        }
      }
      if (!Array.isArray(rows) || !rows.length) {
        rows = PIPELINE_DEFAULT.map((p) => ({ ...p }));
      }
      const categories = rows.map((r) => r.label || r.name || r.stage || 'Stage');
      const data = rows.map((r) => n(r.count ?? r.value ?? r.total, 0));
      const colors = rows.map((_, i) => PIPELINE_COLORS[i % PIPELINE_COLORS.length]);
      const maxVal = Math.max(8, ...data, 1) * 1.15;
      this.hasPipelineChart = categories.length > 0 && data.some((v) => v > 0);
      this.pipelineChartSeries = [{ name: 'Count', data }];
      this.pipelineChartOptions = {
        ...this.pipelineChartOptions,
        colors,
        xaxis: { ...this.pipelineChartOptions.xaxis, max: maxVal, categories },
      };
    },
    bindTypeDonut(cd, res) {      
      let breakdown = cd.content_by_type || cd.type_breakdown;
      let labels = [];
      let series = [];

      if (Array.isArray(breakdown) && breakdown.length) {
        labels = breakdown.map((x) => x.label || x.phase_name || x.type || 'Type');
        series = breakdown.map((x) => n(x.value ?? x.value, 0));
      } else if (Array.isArray(res.PROJECTPHASEDATA) && res.PROJECTPHASEDATA.length) {
        labels = res.PROJECTPHASEDATA.map((x) => x.phase_name || 'Item');
        series = res.PROJECTPHASEDATA.map((x) => n(x.value, 0));
      }

      if (!series.length || series.every((v) => v === 0)) {
        labels = [];
        series = [];
      }

      const colors = labels.map((_, i) => TYPE_COLORS[i % TYPE_COLORS.length]);
      this.hasTypeDonut = labels.length > 0;
      this.typeDonutSeries = series;
      this.typeDonutOptions = {
        ...this.typeDonutOptions,
        labels,
        colors,
      };
    },
    bindPublishWeek(cd, res) {
      let items = cd.publish_this_week || cd.upcoming_publishes;
      if (Array.isArray(items) && items.length) {
        this.publishWeekItems = items.map((x) => this.normalizePublishItem(x));
        return;
      }
      const tasks = Array.isArray(res.TASKDATA) ? res.TASKDATA : [];
      if (tasks.length) {
        this.publishWeekItems = tasks.slice(0, 6).map((t) => {
          const end = t.planned_end_date || t.due_date;
          const d = end ? new Date(end) : null;
          const now = new Date();
          let urgency = 'warn';
          if (d && !Number.isNaN(d.getTime())) {
            const diff = Math.ceil((d - now) / (86400000));
            if (diff <= 1) urgency = 'ok';
            else if (diff <= 4) urgency = 'warn';
            else urgency = 'urgent';
          }
          return {
            title: t.task_name || t.title || '—',
            dateLabel: this.formatShortMonthDay(d),
            urgency,
          };
        });
        return;
      }
      const now = new Date();
      this.publishWeekItems = DEFAULT_PUBLISH_WEEK.map((d) => {
        const dt = new Date(now);
        dt.setDate(dt.getDate() + d.daysFromNow);
        return {
          title: d.title,
          dateLabel: this.formatShortMonthDay(dt),
          urgency: d.urgency,
        };
      });
    },
    showAssignUser(itm) {
      if (itm.AssignUser && itm.AssignUser.length) {
        this.$set(itm, 'ispopover', true);
      }
    },
        hideAssignUser(itm) {
            this.$set(itm, 'ispopover', false);
        },
    normalizePublishItem(x) {
      const title = x.title || x.name || x.content_title || '—';
      const raw = x.publish_date || x.due_date || x.planned_end_date;
      let d = raw ? new Date(raw) : null;
      if (!d || Number.isNaN(d.getTime())) d = new Date();
      const urgency = x.urgency || this.urgencyFromDate(d);
      return {
        title,
        dateLabel: this.formatShortMonthDay(d),
        urgency,
      };
    },
    urgencyFromDate(d) {
      const now = new Date();
      const diff = Math.ceil((d - now) / 86400000);
      if (diff <= 1) return 'ok';
      if (diff <= 4) return 'warn';
      return 'urgent';
    },
    formatShortMonthDay(d) {
      if (!d || Number.isNaN(d.getTime())) return '—';
      return d.toLocaleDateString('en-US', { month: 'short', day: '2-digit' });
    },
    bindOverdueTable(cd, res) {
      let rows = cd.overdue_content || cd.overdue_unpublished;
      if (Array.isArray(rows) && rows.length) {
        this.overdueRows =[];
        return;
      }
      var bugs = Array.isArray(res.CRITICALBLOCKERBUGS) ? res.CRITICALBLOCKERBUGS : [];
      if (bugs.length) {
        bugs =bugs.map((x) => ({
          ...x,
          ispopover: false,
          AssignUser: x.Assign != null ? String(x.Assign).split(',') : [],
        }));
        this.overdueRows = bugs.slice(0, 20).map((b) => this.overdueFromBug(b));
        return;
      } 
        
      
      // this.overdueRows = DEFAULT_OVERDUE.map((r) => ({
      //   title: r.title,
      //   type: r.type,
      //   author: r.author,
      //   plannedLabel: this.formatShortMonthDay(new Date(r.planned)),
      //   daysOverdueLabel: this.formatDaysOverdue(r.daysOverdue),
      //   stage: r.stage,
      //   rowClass: r.rowClass,
      // }));
    },
    normalizeOverdueApiRow(r) {
      const planned = r.planned_date || r.plannedDate || r.due_date;
      const d = planned ? new Date(planned) : null;
      const days = r.days_overdue != null ? n(r.days_overdue, 0) : this.computeDaysOverdue(d);
      return {
        title: r.title || r.content_title || r.task_name || '—',
        type: r.type || r.content_type || '—',
        author: r.author || r.author_name || '—',
        plannedLabel: this.formatShortMonthDay(d),
        daysOverdueLabel: this.formatDaysOverdue(days),
        stage: r.stage || r.status_name || '—',
        rowClass: this.overdueRowClass(days),
      };
    },
    overdueFromBug(b) {
      const d = b.planned_end_date;
      const v = b.planned_start_date ;
      const days = this.computeDaysOverdue(d);
      const type = b.Component || (b.task_type === 'S' ? 'Story' : b.task_type === 'T' ? 'Task' : 'Content');
      return {
        title: [b.task_number, b.task_name].filter(Boolean).join(' ') || '—',
        type,
        author: b.Created_by || '—',
        plannedLabel: this.formatCellDate(v),
        daysOverdueLabel: this.formatCellDate(d),
        stage: b.task_type || '—',
        status:b.status_name,
        pirority:b.priority_name,
        statusrowClass: b.status_bg_color,
        priorityrowClass: b.color_code,
      };
    },
    formatCellDate(val) {
      if (!val) return '—';
      const f = this.$options.filters && this.$options.filters.formatDate;
      if (typeof f === 'function') return f(val);
      try {
        const d = val instanceof Date ? val : new Date(val);
        if (Number.isNaN(d.getTime())) return '—';
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const yy = d.getFullYear();
        return `${mm}/${dd}/${yy}`;
      } catch (e) {
        return '—';
      }
    },
    computeDaysOverdue(d) {
      if (!d || Number.isNaN(d.getTime())) return 1;
      const now = new Date();
      now.setHours(0, 0, 0, 0);
      const t = new Date(d);
      t.setHours(0, 0, 0, 0);
      const diff = Math.ceil((now - t) / 86400000);
      return Math.max(0, diff);
    },
    formatDaysOverdue(days) {
      const nDays = n(days, 0);
      if (nDays <= 0) return '—';
      return `${nDays} ${nDays === 1 ? 'day' : 'days'}`;
    },
    overdueRowClass(days) {
      const nDays = n(days, 0);
      if (nDays >= 3) return 'mcc-od-row--amber';
      return 'mcc-od-row--pink';
    },
    AssignedUser(val, users) {
      this.BacklogId = val;
      this.AssigenedUser = users;
      this.IsAssignedUser = true;
    },
  },
};
</script>

<style scoped>
/* .project-content-calendar-overview {
  width: 100%;
  min-width: 0;
}
.projectoverviewbase .card{background: none!important; border:none;}
.mcc-top-card {
  border: 1px solid #e8eaed;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 1px 3px rgba(60, 64, 67, 0.08);
  background: transparent;
}
.mcc-intel-brand {
  gap: 10px;
}
.mcc-intel-star {
  color: #f4b400;
  font-size: 1.05rem;
  line-height: 1;
}
.mcc-intel-title {
  font-size: 1.25rem;
  font-weight: 700;
  color: #202124;
  letter-spacing: -0.02em;
}
.mcc-template-badge {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.65rem;
