<template>
  <section>
    <loader :is-visible="isLoading"></loader>
    <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="true" ModuleName="Event"
      SubModuleCode="Client" IdentityColumn="wish_list_id" :HeaderText="$t('Manage Attendees')" :ListData="ListingData"
      :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
      :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="fetch" :SortExp="SortExp" :SortBy="SortBy"
      :NorecordfoundText="$t('NoRecordfound')" v-on:ActionButtonClick="actionButtonClick"
      v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
      v-on:SortdataButtonClick="sortdata">

    </tg-list>
    <AddAttendee v-if="showAddModal" @close="showAddModal = false" @saved="fetch"></AddAttendee>
    <ViewAttendeeTicket v-if="showTicketModal"></ViewAttendeeTicket>
  </section>
</template>

<script>
import DataService from '@/services/DataService';
import AddAttendee from '../Modals/AddAttendee.vue';
import ViewAttendeeTicket from '../Modals/ViewAttendeeTicket.vue';
import Schema from './AttendeeListPortionSchema'

export default {
  name: 'AttendeeListPortion',
  components: { AddAttendee, ViewAttendeeTicket },

  data() {
    return {
      ListingData: [],
      PageNumber: 1,
      isLoading: false,
      isPaged: 1,
      TotalPages: 0,
      widgets: [],
      SortBy: '',
      SortExp: '',
      showAddModal: false,
      showTicketModal: false,
      selectedAttendeeId: null,
      listActions: Schema.listActions,
      Headers: Schema.TableHeader,
      Buttons: Schema.buttons,

    };
  },
  created() {
    this.fetch();
  },
  methods: {
    async fetch() {
      this.isLoading = true
      try {
        const res = await DataService.GetAttendeeListing(`eventId=${this.eventId}&pageSize=${this.PageSize}&pageNumber=${this.PageNumber}`);
        this.ListingData = (res.data && res.data.result && res.data.result.data) ? res.data.result.data : [];
        this.TotalRecords = (res.data && res.data.result) ? (res.data.result.totalRecords || 0) : 0;
      }
      catch (_) {
        this.list = [];
        this.TotalRecords = 0;
      } finally {
        this.isLoading = false
      }
    },
    sortdata: function (s) {
      var SortDir = "sort tb_headerSortDown";
      this.SortBy = s;
      if (s === this.SortBy) {
        if (this.SortExp == "") {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
        else if (this.SortExp == "ASC") {
          this.SortExp = "DESC";
          SortDir = "sort tb_headerSortUp";
        }
        else {
          this.SortExp = "ASC";
          SortDir = "sort tb_headerSortDown";
        }
      }
      this.FetchWishList();
      $("#" + s + '  span:first-child').attr("class", SortDir);
    },
    commonHeaderButtonClick: async function (event) {
      var vm = this;
      switch (event.callbackfunction) {
        case "Reject":
          // vm.OpenReject();
          break;
        case "Approve":
          // vm.OpenApprove();
          break;
        case "SendEmail":
          // vm.OpenSendEmail();
          break;
        case "AddAttendee":
          vm.OpenAddAttendee();
          break;
        case "Delete":
          //vm.OpenDelete();
          break;
        case "BackToList":
          // vm.BackToList();
          break;
      }
    },
    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {
        case 'DeleteAttendee':
          this.DeleteAttendee();
          break;
        case 'EditAttendee':
          this.OpenAddAttendee();
          break;

      }
    },
    renderActions: function () {
      var self = this;
      let rtnActionArray = [];
      self.listActions.forEach(actionItem => {
        let action = { ...actionItem };
        switch (action.title) {
          case 'Edit':
            action.isVisible = true;
            break;
          case 'Delete':
            action.isVisible = true;
            break;

          default: {
            action.isVisible = true;
          }
        }
        rtnActionArray.push(action);
      });
      return rtnActionArray;
    },
    pagerMethod(p) {
      if (p) {
        this.PageNumber = p.PageNumber;
        this.PageSize = p.PageSize;
      }
      this.fetch();
    },
    async OpenAddAttendee() {
      var vm = this;
      var url = 'controller=Project&action=AddUpdateWishList';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.showAddModal = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      })
    },
     async DeleteAttendee() {
      var vm = this;
      var url = 'controller=Project&action=DeleteManageAttendee';
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          //vm.showAddModal = true;
        }
        else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      })
    },
    openTicket(item) {
      this.selectedAttendeeId = item.id || item.ATTENDEE_ID;
      this.showTicketModal = true;
    }
  }
};
</script>
