<template>
  <section class="project-bug-overview">
     <div class="projectoverviewbase">
    <CommonDashboard
      ref="commonDashboard"
      :project-id="projectId"
      :check-pm-user="checkPmUser"
      :new-tab-name="NewTabName"
      :tabs-array="TabsArray"
      :Template_Name="Template_Name"
      @AddView="$emit('AddView', $event)"
    />
    <div class="card col-md-12 p-0 mb-3 mc-top-card bug-top-card">
      <div class="card-body col-12 pt-3 pb-4 px-3 common-dashboard-shell">
        <!-- <div class="bug-intel-head d-flex flex-wrap align-items-center justify-content-between gap-3 mb-4">
          <div class="bug-intel-brand d-flex flex-wrap align-items-center">
            <em class="fa fa-star bug-intel-star" aria-hidden="true"></em>
            <span class="bug-intel-title">Template Intelligence</span>
            <span class="bug-template-badge">{{ templateTag }}</span>
                                    </div>
                                </div> -->
<!-- 
        <div class="bug-kpi-row">
          <div v-for="(kpi, idx) in kpiCards" :key="'kpi-' + idx" class="bug-kpi-col">
            <div class="bug-kpi-card" :class="'bug-kpi-card--' + kpi.tint">
              <div class="bug-kpi-value">{{ kpi.value }}</div>
              <div class="bug-kpi-label">{{ kpi.label }}</div>
                                    </div>
                                    </div>
                                </div> -->

        <div class="row mx-0 align-items-stretch">
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Bug Severity Breakdown</span>
                            </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasSeverityDonut"
                  type="donut"
                  height="300"
                  :options="severityDonutOptions"
                  :series="severityDonutSeries"
                  :key="'bug-sev-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
                                </div>
                                </div>
                            </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Resolution Rate (Weekly)</span>
                                </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasResolutionChart"
                  type="line"
                  height="300"
                  :options="resolutionLineOptions"
                  :series="resolutionLineSeries"
                  :key="'bug-res-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
                            </div>
                        </div>
                    </div>
          <div class="col-lg-4 mb-3 px-2 section_pp d-flex">
            <div class="section h-100 w-100 mcc-chart-section">
              <div class="section-header reddy cd-panel-head mcc-chart-panel-head">
                <span class="cd-panel-title mcc-chart-title">Bug Status Overview</span>
                            </div>
              <div class="section-body border py-2 mcc-chart-body">
                <VueApexCharts
                  v-if="hasStatusBar"
                  type="bar"
                  height="300"
                  :options="statusBarOptions"
                  :series="statusBarSeries"
                  :key="'bug-st-' + chartKey"
                />
                <div v-else class="mcc-no-chart">{{ $t('NoRecordfound') }}</div>
                        </div>
                        </div>
                    </div>
                                    </div>

        <div class="row mx-0">
          <div class="col-12 px-2 section_pp">
            <div class="section mcc-overdue-section">
              <div class="section-header reddy cd-panel-head mcc-od-head">
                <span class="cd-panel-title mcc-od-title-wrap">
                  <em class="fa fa-bug mcc-od-bolt" aria-hidden="true"></em>
                  <span class="mcc-od-title-main ">{{ $t('CriticalandBlockerBugs') }}</span>
                                    </span>
                <small class="cd-panel-actions">
                  <a href="javascript:;" class="kb-view-all-link font-13" @click="openDashboardAddView">
                    <em class="fa fa-eye mr-1"></em>{{ $t('View All') }}
                  </a>
                </small>
                                </div>
              <div class="section-body border p-0">
                <div class="table-responsive mcc-od-wrap">
                  <table class="table mb-0 mcc-od-table">
                    <thead>
                       <tr>
                           <th># {{ $t('Key') }} / {{ $t('TaskName') }}</th>
                           <th>{{ $t('created_by_name') }}</th>
                           <th>{{ $t('SACreatedAt') }}</th>
                           <th>{{ $t('TillDate') }}</th>
                           <th class="text-center">{{ $t('Asignee') }}</th>
                           <th class="text-center">{{ $t('environment') }}</th>
                           <th class="text-center">{{ $t('Component') }}</th>
                           <th>{{ $t('Priority') }}</th>
                           <th>{{ $t('SAStatus') }}</th>
                       </tr>
                   </thead>
                   <tbody>
                      <tr v-for="(item, index) in criticalBugs" :key="'cb-' + index">
                        <td>
                          <span
                            class="bug-type-badge text-white"
                            :style="{ backgroundColor: typeBadgeColor(item) }"
                          >{{ taskTypeLabel(item) }}</span>
                          <span class="bug-key-name" :title="item.task_number + ' ' + item.task_name">
                            {{ item.task_number }} {{ truncate(item.task_name, 46) }}
                          </span>
                                    </td>
                                    <td><span class="d-block" :title="item.Created_by">{{ item.Created_by || '—' }}</span></td>
                        <td>
                          <span class="d-block" :title="formatCellDate(item.created_at || item.CREATED_AT || item.planned_start_date)">
                            {{ formatCellDate(item.created_at || item.CREATED_AT || item.planned_start_date) }}
                          </span>
                                    </td>
                        <td>
                          <span class="d-block" :title="formatCellDate(item.planned_end_date)">
                            {{ formatCellDate(item.planned_end_date) }}
                          </span>
                                    </td>
                            <td class="text-center">
                          <div class="d-block ">                            
                            <div
                              v-if="item.AssignUser && item.AssignUser.length"
                              class="user-count-wrapper d-inline-block ml-1"
                              @mouseover="showAssignUser(item)"
                              @mouseleave="hideAssignUser(item)"
                            >
                              <a href="javascript:;" class="kb-bn-assignee-more disabled" @click.prevent>
                                <em class="fa fa-user"></em>
                                <span class="noti-circle noti-green">{{ item.TotalUserCount != null ? item.TotalUserCount : item.AssignUser.length }}</span>
                              </a>
                              <div class="viewmoretagsbase_ptl showTags" v-if="item.ispopover">
                                <div class="popover-arrowss_ptl"></div>
                                <div class="viewmoretags_ptl">
                                  <span class="head">Users</span>
                                  <div class="outerbase">
                                    <span v-for="(item, index) in item.AssignUser" :key="index">{{ index + 1 }}. {{ truncate(item, 15) }}</span>
                                  </div>
                                </div>
                              </div>
                            </div>
                            <div v-else>
                              <span>--</span>
                            </div>
                          </div>
                        </td>
                        <td class="text-center"><span :title="item.Environment" class="d-block">{{ item.Environment || '—' }}</span></td>
                        <td class="d-block text-center">{{ item.component_name || item.Component || '—' }}</td>
                        <td>
                          <span
                            class="bug-pill bug-pill--priority text-white"
                            :style="{ backgroundColor: item.color_code || '#f4511e' }"
                          >{{ item.priority_name || '—' }}</span>
                                    
                        </td>
                        <td>
                          <span
                            class="bug-pill bug-pill--status"
                            :style="{ backgroundColor: item.status_bg_color || '#e8eaed', color: '#fff' }"
                          >{{ item.status_name || '—' }}</span>
                                    </td>
                                </tr>
                      <tr v-if="!criticalBugs.length">
                        <td colspan="8" class="text-center text-danger py-4">{{ $t('NoRecordfound') }}</td>
                                        </tr>
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    </div>
     <CriticalandBlockerDetail v-if="isCriticalandBlockerDetail" :Type="Template_Name"  :HeaderText="'CriticalandBlockerBugs'"/>
</div>
    </section>
</template>

<script>
import CommonDashboard from '../CommonDashboard.vue';
import VueApexCharts from 'vue-apexcharts';
import DataService from '../../../../../../services/DataService';
 import CriticalandBlockerDetail from '../../../../../../components/Modal/CriticalandBlockerDetail.vue';

function n(v, fallback = 0) {
  const x = Number(v);
  return Number.isFinite(x) ? x : fallback;
}
export default {
    name: 'BugTrackingOverView',
  components: { CommonDashboard, VueApexCharts,CriticalandBlockerDetail},
    props: {
    projectId: { type: Number, required: true },
    checkPmUser: { type: Boolean, required: true },
    NewTabName: { type: String, required: true },
    TabsArray: { type: Array, default: () => [] },
    Template_Name: { type: String, required: true },
    },
    data() {
        return {
       isCriticalandBlockerDetail:false,
       chartKey: 0,
      kpiCards: [],
      hasSeverityDonut: false,
      severityDonutSeries: [],
      severityDonutOptions: {
        chart: { type: 'donut', fontFamily: 'inherit', toolbar: { show: false } },
        labels: ['Critical', 'High', 'Medium', 'Low'],
        colors: ['#ea4335', '#f4511e', '#fbbc04', '#34a853'],
                plotOptions: {
                    pie: {
                        donut: {
              size: '68%',
                            labels: {
                                show: true,
                total: { show: true, label: 'Total', fontWeight: 600 },
                        },
                    },
                },
        },
        legend: { position: 'bottom', fontSize: '12px' },
        dataLabels: { enabled: false },
      },
      hasResolutionChart: false,
      resolutionLineSeries: [],
      resolutionLineOptions: {
        chart: { type: 'line', toolbar: { show: false }, fontFamily: 'inherit', zoom: { enabled: false } },
        stroke: { width: 3, curve: 'smooth' },
        colors: ['#ea4335', '#34a853'],
        markers: { size: 4 },
        xaxis: { categories: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'], labels: { style: { fontSize: '11px' } } },
        yaxis: { min: 0, labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: true, position: 'top', horizontalAlign: 'right', fontSize: '12px' },
      },
      hasStatusBar: false,
      statusBarSeries: [],
      statusBarOptions: {
        chart: { type: 'bar', toolbar: { show: false }, fontFamily: 'inherit' },
                plotOptions: {
          bar: {
            horizontal: true,
            barHeight: '55%',
            borderRadius: 4,
            dataLabels: { position: 'center' },
          },
        },
        colors: ['#1a73e8'],
        dataLabels: {
          enabled: true,
          style: { colors: ['#fff'], fontSize: '11px', fontWeight: 600 },
        },
        xaxis: { categories: [], labels: { style: { fontSize: '11px' } } },
        yaxis: { labels: { style: { fontSize: '11px' } } },
        grid: { strokeDashArray: 4, borderColor: '#e8eaed' },
        legend: { show: false },
      },
      criticalBugs: [],
      BacklogId: null,
      AssigenedUser: null,
      IsAssignedUser: false,
    };
  },
  computed: {
    templateTag() {
      return (this.Template_Name || 'BUG TRACKING').toString().toUpperCase();
    },
  },
  watch: {
    projectId() {
      this.loadData();
    },
    },   
    mounted() {
    this.loadData();
  },
  methods: {
    showAssignUser(itm) {
      if (itm.AssignUser && itm.AssignUser.length) {
        this.$set(itm, 'ispopover', true);
      }
    },
        hideAssignUser(itm) {
            this.$set(itm, 'ispopover', false);
        },
    openDashboardAddView() {
     this.isCriticalandBlockerDetail=true;
    },
    truncate(str, len) {
      if (str == null || str === '') return '';
      const s = String(str);
      return s.length > len ? s.slice(0, len - 1) + '…' : s;
    },
    formatCellDate(val) {
      if (!val) return '—';
      const f = this.$options.filters && this.$options.filters.formatDate;
      if (typeof f === 'function') return f(val);
      try {
        const d = val instanceof Date ? val : new Date(val);
        if (Number.isNaN(d.getTime())) return '—';
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const dd = String(d.getDate()).padStart(2, '0');
        const yy = d.getFullYear();
        return `${mm}/${dd}/${yy}`;
      } catch (e) {
        return '—';
      }
    },
    taskTypeLabel(item) {
      const t = item.task_type;
      if (t === 'T') return 'Task';
      if (t === 'S') return 'Story';
      return 'Issue';
    },
    typeBadgeColor(item) {
      const c = item.color_code && String(item.color_code).trim();
      if (c) return c;
      if (item.task_type === 'S') return '#5c9ded';
      if (item.task_type === 'T') return '#80868b';
      return '#9334e6';
    },
    loadData() {
      const params = `ProjectId=${this.projectId}`;
      DataService.GetChartBugProject(params)
        .then((response) => {
          const res = response.data && response.data.result;
          if (!res) return;
          
          this.applyPayload(res);
          this.$nextTick(() => {
            this.chartKey++;
          });
        })
        .catch((e) => console.error('Bug tracking overview load:', e));
    },
    applyPayload(res) {
      const bt = res.BUG_TRACKING_DASHBOARD || res.bug_tracking_dashboard || {};
      this.bindKpis(bt, res);
      this.bindSeverityDonut(bt, res);
      this.bindResolutionChart(bt, res);
      this.bindStatusBar(bt, res);
      this.bindCriticalTable(res);
    },
    bindKpis(bt, res) {
      let critV = n(bt.critical_open ?? bt.critical, NaN);
      let highV = n(bt.high_open ?? bt.high, NaN);
      let cSum = 0;
      let hSum = 0;
      const pri = Array.isArray(res.PRIORITYDATA) ? res.PRIORITYDATA : [];
      pri.forEach((p) => {
        const name = String(p.priority_name  || '').toLowerCase();
        const c = n(p.total_count, 0);
      });
      if (!Number.isFinite(critV)) critV = cSum || 4;
      if (!Number.isFinite(highV)) highV = hSum || 11;
      const avgRes = bt.avg_resolution_days != null ? `${n(bt.avg_resolution_days, 0)}d` : '2.4d';
      const reopen = bt.reopen_rate_pct != null ? `${n(bt.reopen_rate_pct, 0)}%` : '18%';
      this.kpiCards = [
        { label: 'Critical open', value: critV, tint: 'critical' },
        { label: 'High open', value: highV, tint: 'high' },
        { label: 'Avg resolution time', value: avgRes, tint: 'avg' },
        { label: 'Reopen rate', value: reopen, tint: 'reopen' },
      ];
    },
    
    bindSeverityDonut(bt, res) {
  const pri = Array.isArray(res.PRIORITYDATA) ? res.PRIORITYDATA : [];
  if(!pri.length) return;
  if (pri.length) {
    const labels = [];
    const series = [];
    const colors = [];
    pri.forEach(p => {
      const name = String(p.priority_name || '').trim();
      const count = n(p.total_count, 0);
      const color = p.color_code;
      if (!name) return;
      labels.push(name.charAt(0).toUpperCase() + name.slice(1));
      series.push(count);
      if (color) colors.push(color);
    });
    this.hasSeverityDonut = series.some(v => v > 0);
    if (!this.hasSeverityDonut) {
      const fallbackSeries = [];
      const fallbackLabels = [];
      const fallbackColors = [];
      this.hasSeverityDonut = true;
      this.severityDonutSeries = fallbackSeries;
      this.severityDonutOptions = {
        ...this.severityDonutOptions,
        labels: fallbackLabels,
        colors: fallbackColors,
        legend: {
          show: true,
          position: 'bottom',
          formatter: (seriesName, opts) => {
            const value = opts.w.globals.series[opts.seriesIndex] || 0;
            return `${seriesName} (${value})`;
          }
        }
      };
      return;
    }
    this.severityDonutSeries = series;
    this.severityDonutOptions = {
      ...this.severityDonutOptions,
      labels,
      colors: colors,
      legend: {
        show: true,
        position: 'bottom',
        formatter: (seriesName, opts) => {
          const value = opts.w.globals.series[opts.seriesIndex] || 0;
          return `${seriesName} (${value})`;
        }
      }
    };
    return;
  }
  const fallbackSeries = [];
  const fallbackLabels = [];
  this.hasSeverityDonut = true;
  this.severityDonutSeries = fallbackSeries;
  this.severityDonutOptions = {
    ...this.severityDonutOptions,
    labels: fallbackLabels,
    legend: {
      show: true,
      position: 'bottom',
      formatter: (seriesName, opts) => {
        const value = opts.w.globals.series[opts.seriesIndex] || 0;
        return `${seriesName} (${value})`;
      }
    }
  };
},
    // bindResolutionChart(bt, res) {
    //   const opened = bt.opened_weekly || bt.resolution_opened;
    //   const resolved = bt.resolved_weekly || bt.resolution_resolved;
    //   if (Array.isArray(opened) && Array.isArray(resolved) && opened.length) {
    //     this.hasResolutionChart = true;
    //     this.resolutionLineSeries = [
    //       { name: 'Opened', data: opened.map((v) => n(v.value ?? v, 0)) },
    //       { name: 'Resolved', data: resolved.map((v) => n(v.value ?? v, 0)) },
    //     ];
    //     return;
    //   }
    //   this.hasResolutionChart = true;
    //   this.resolutionLineSeries = [
    //     { name: 'Opened', data: [5, 3.5, 7, 4, 2.5] },
    //     { name: 'Resolved', data: [4, 5, 6, 7, 4] },
    //   ];
    // },
    bindResolutionChart(bt, res) {
  const data = res.DATAA || [];
  if(data.length==0) return;
  const labels = data.map(item => item.day_name);
  const opened = data.map(item => item.opened_count ?? 0);
  const resolved = data.map(item => item.resolved_count ?? 0);

  this.hasResolutionChart = true;

  this.resolutionLineSeries = [
    { name: 'Opened', data: opened },
    { name: 'Resolved', data: resolved }
  ];

  this.resolutionLineOptions = {
    ...this.resolutionLineOptions,
    xaxis: {
      ...this.resolutionLineOptions.xaxis,
      categories: labels
    }
  };
},
bindStatusBar(bt, res) {
  const status = res.DATA[0] || {};
  if (!Object.keys(status).length) return;
  const keys = Object.keys(status).filter(
    k => !k.endsWith('_color') && !k.endsWith('_label')
  );
  const labels = keys.map(key => status[`${key}_label`] || key);
  const data = keys.map(key => status[key] ?? 0);
  const colors = keys.map(key => status[`${key}_color`] || '#888');
  this.hasStatusBar = true;
  this.statusBarSeries = [{
    name: 'Count',
    data: data
  }];

  this.statusBarOptions = {
    ...this.statusBarOptions,
    plotOptions: {
      ...this.statusBarOptions.plotOptions,
      bar: {
        ...this.statusBarOptions.plotOptions?.bar,
        distributed: true
      }
    },
    colors: colors,
    xaxis: {
      ...this.statusBarOptions.xaxis,
      categories: labels
    }
  };
},
    bindCriticalTable(res) {
      const crit = res.CRITICALBLOCKERBUGS;
      if (crit && crit.length) {
        this.criticalBugs = crit.map((x) => ({
          ...x,
          ispopover: false,
          AssignUser: x.Assign != null ? String(x.Assign).split(',') : [],
        }));
      } else {
        this.criticalBugs = [];
      }
    },
    showAssignUser(row) {
      this.$set(row, 'ispopover', true);
    },
    hideAssignUser(row) {
      this.$set(row, 'ispopover', false);
    },
    AssignedUser(taskId, userIds) {
      this.BacklogId = taskId;
      this.AssigenedUser = userIds;
      this.IsAssignedUser = true;
    },
  },
};
</script>

