  <template>
  <div class="my-popups">
    <loader :is-visible="isLoading"></loader>
    <div class="modal d-block">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header theme-primary partition-full  d-flex">
            <h4 class="modal-title">{{ $t('Manage') }} {{ $t(NewTabName) }}</h4>
            <button type="button" class="close" v-on:click="CloseStage">
              <em class="fa fa-times" aria-hidden="true"></em>
            </button>
          </div>
          <div class="modal-body" v-if="!IsAddIsShow">
            <dynamic-form lang="en" :buttons="buttons" :schema="FormSchema" ref="AssignTagForm"
              :mandatorytext='MandatoryString' v-on:OnSubmit="OnSubmit"></dynamic-form>
          </div>
          <div class="modal-body" v-if="IsAddIsShow">
            <div class="heading-border mb-3">
              <h5 class="h5">
                <span> {{ $t('Stage') }}</span>
                <div class="float-right ml-4">
                </div>
              </h5>
            </div>
            <Form ref="form" v-slot="{ values, meta }">
              <div class="d-flex flex-wrap">
                <div class="col-md-12 p-0">
                  <div class="row">
                    <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 float-left">
                      <div class="listing">

                        <div class="table-responsive overflow-visible"> <!-- table-fix-header -->
                          <table id="tblStage" class="table table-bordered dt-responsive nowrap mt-0 mb-0">
                            <thead class="thead-bg">
                              <tr>
                                <th style="width:50px !important;" id="nonresize">
                                  <div class="custom-control custom-checkbox">
                                    <input class="chkItems setcheckall custom-control-input" type="checkbox" id="chkAll"
                                      name="checkbox" data-parent="no" style="display: none;" v-model="selectAll"
                                      v-on:change="checkAllSelected($event)">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                      for="chkAll"></label>
                                  </div>
                                </th>
                                <th><span href="javascript:;">{{ $t(NewTabName) }} {{ $t('Name') }}</span>
                                </th>
                                
                                <th v-if="ProjectIndusrtyType !== 'Construction'" style="width:340px;"><span href="javascript:;">{{
                                  $t('TaskName') }}</span></th>
                                <th v-if="ProjectIndusrtyType !== 'Construction'" style="width:340px;"><span href="javascript:;">{{
                                  $t('Stage') }} {{ $t('Hour') }}</span></th>{{ }}
                                <th style="width:340px;"><span href="javascript:;"> {{ $t('ProjectStartDate') }} ( {{
                                  ProjectStartDate }})</span></th>
                                <th style="width:340px;"><span href="javascript:;">{{ $t('ProjectEndDate') }} ( {{
                                  ProjectEndDate }})</span></th>
                              </tr>
                            </thead>
                            <tbody>
                              <tr v-for="(item, index) in AddEditStageListing" v-if="!noRecordForTab" :key="index">

                                <td>
                                  <div class="custom-control custom-checkbox">
                                    <input class="chkItems setcheckall custom-control-input" :value="item.STAGE_ID"
                                      :disabled="item.START_DATE_SELECTED != null" type="checkbox"
                                      :id="'chkAll_' + index" name="checkbox" data-parent="no" style="display: none;"
                                      v-model="item.selected" v-on:change="PhaseChange(item)">
                                    <label class="custom-control-label universal-custom-control-label pt-1"
                                      :for="'chkAll_' + index"></label>
                                  </div>
                                </td>
                                <td><span class="nochk" :title="item.STAGE_NAME">{{ TruncateStr(item.STAGE_NAME, 60)
                                }}</span>
                                </td>
                                <td v-if="ProjectIndusrtyType !== 'Construction'">
                                  <multiselect :key="'task-select-' + item.STAGE_ID + '-' + index"
                                    placeholder="Select Task" :max-height="150" v-model="item.TASK_ID" label="name"
                                    track-by="value" :limit="2" :options="TaskList" :multiple="true" mode="tag"
                                    :close-on-select="false" :clear-on-select="false" :preserve-search="true"
                                    :taggable="false" :allow-empty="true" :show-labels="false">
                                  </multiselect>
                                </td>
                                <td v-if="ProjectIndusrtyType !== 'Construction'">
                                  <span class="startspan text-center"
                                    v-if="item.STAGE_HOURS != '' && item.STAGE_HOURS != null">{{ item.STAGE_HOURS
                                    }}</span>
                                  <span class="startspan text-center" v-else>0</span>
                                </td>
                                <td>
                                  <div class="input-group table_datepickerfix">
                                    <Field :name="'startdate' + index"
                                      :rules="{ required: item.selected == true ? true : false }"
                                      v-slot="{ errors, changed }">
                                      <v-date-picker :minute-increment="5" class="input-group" v-model="item.START_DATE"
                                        @update:modelValue="changed" :min-date="HideprojectStartDate"
                                        :max-date="HideprojectEndDate">
                                        <template v-slot="{ inputValue, togglePopover }">
                                          <input :placeholder="'MM/DD/YYYY'"
                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                            :value="inputValue" />
                                          <div @click="togglePopover()" class="input-group-append"><span
                                              class="input-group-text"><em class="fa fa-calendar"></em></span>
                                          </div>
                                        </template>
                                      </v-date-picker>
                                      <span v-if="errors[0]" :name="'startdate' + index"
                                        class="invalid-feedback d-block">
                                        {{ $t('StartDateReq') }}</span>
                                    </Field>
                                  </div>
                                </td>
                                <td>
                                  <div class="input-group table_datepickerfix">
                                    <Field :name="'enddate' + index"
                                      :rules="{ required: item.selected == true ? true : false }"
                                      v-slot="{ errors, changed }">
                                      <v-date-picker :minute-increment="5" class="input-group" v-model="item.END_DATE"
                                        @update:modelValue="changed" :min-date="item.START_DATE || HideprojectStartDate"
                                        :max-date="HideprojectEndDate">
                                        <template v-slot="{ inputValue, togglePopover }">
                                          <input :placeholder="'MM/DD/YYYY'"
                                            v-bind:class="{ 'form-control': true, 'is-invalid': errors[0] }"
                                            :value="inputValue" />
                                          <div @click="togglePopover()" class="input-group-append"><span
                                              class="input-group-text"><em class="fa fa-calendar"></em></span>
                                          </div>
                                        </template>
                                      </v-date-picker>
                                      <span v-if="errors[0]" :name="'enddate' + index" class="invalid-feedback d-block">
                                        {{ $t('EndDateReq') }}</span>
                                    </Field>
                                  </div>
                                </td>
                              </tr>
                              <tr v-if="noRecordForTab">
                                <td colspan="4">
                                  <div class="text-center text-danger">{{
                                    $t('NoRecordfound') }}</div>
                                </td>
                              </tr>
                            </tbody>
                          </table>
                        </div>

                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </Form>
            <div class="modal-footer">
              <a href="javascript:;" v-on:click="SaveStage($event)" class="btn btn-success formbtn">
                <i class="fa fa-save"></i> {{ $t('Save') }}
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
<script>
import DataService from '../../services/DataService'
export default {
  components: {},
  props: {
    stageList: {
      type: Array,
      required: true
    },
    NewTabName: {
      type: Number,
      required: true
    },
    TabsArray: {
      type: Array
    },
    ProjectIndusrtyType: {
      type: String,
      required: true
    },
  },
  watch: {
    // Watch for NewTabName changes and update Buttons
    NewTabName: {
      handler(newTabName) {
        debugger
        this.NewTabName=this.TabsArray.filter(t=>t.displayCode=='PROJECT_STAGE')?.displayName || 'Project Stage';
        if (newTabName) {
          this.UpdateFieldsText(newTabName);
        }
      },
      immediate: true
    }
  },
  data() {
    return {
      isLoading: false,
      options: [],
      selectedStage: '',
      selectAll: false,
      IsAddIsShow: false,
      ProjectId: null,
      ProjectEndDate: '',
      ProjectStartDate: '',
      TreeValue: null,
      noRecordForTab: false,
      ProjectName: '',
      AddEditStageListing: [],
      HideprojectStartDate: '',
      HideprojectEndDate: '',
      MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
      FormSchema: [
        {
          layoutType: "double",
          Data: [
            {
              astype: "TextField",
              label: this.$t(''),
              name: "StageName",
              value: "",
              placeholder: this.$t(''),
              validationRules: { "required": true, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t('Project Phase'),
              value: "",
              config: {
                options: []
              },
              placeholder: this.$t('Select Phase Name'),
              validationRules: { "required": true, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t('Type'),
              value: "",
              disabled: true,
              config: {
                options: []
              },
              placeholder: this.$t('Select Type'),
              validationRules: { "required": false, max: 100 },
            },
            {
              astype: "SelectField",
              label: this.$t('Status'),
              name: "Tag",
              value: "",
              config: {
                options: []
              },
              placeholder: this.$t('Select Status'),
              validationRules: { "required": true, max: 100 },
            },
            {
              astype: "ColorField",
              label: this.$t('Color Code'),
              name: "Color Code",
              value: "",
              placeholder: "",
              validationRules: {
                "required": true
              },
              disabled: false,
            }
          ]
        },
        {
          layoutType: "single",
          Data: [
            {
              astype: "TextAreaField",
              label: this.$t('Description'),
              name: "Description",
              value: "",
              validationRules: { "required": false, max: 4000 },
              config: {
                rows: 5
              }
            }
          ]
        }
      ],
      buttons: [
        {
          type: "submit",
          class: "btn btn-success",
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: true,
        },
        {
          type: "button",
          class: "btn btn-danger",
          text: "<i class='fa fa-close pr-2'></i>Cancel",
          onClick: this.CloseStage,
        },
      ],
      TaskList: [],
      FindalTaskArray: []
    }
  },
  created: function () {
    var ths = this;
    //   if(ths.NewTabName=='NewTabName')
    //   {
    //   ths.FormSchema[0].Data[1].label=ths.$t('Project Phase');
    // }
    // else{
    //   // ths.FormSchema[0].Data[1].label
    // }
    ths.ProjectId = ths.$route.params.projectId; 
    ths.FormSchema[0].Data[0].label=ths.TabsArray.filter(t=>t.displayCode=='PROJECT_STAGE')?.displayName +' Name' || 'Stage Name';
    ths.FormSchema[0].Data[0].placeholder='Enter' + ths.TabsArray.filter(t=>t.displayCode=='PROJECT_STAGE')?.displayName +' Name' || 'Enter Stage Name';
    ths.FormSchema[0].Data[1].label=ths.TabsArray.filter(t=>t.displayCode=='PROJECT_PHASE')?.displayName +' Name' || 'Phase Name';
    ths.FormSchema[0].Data[0].placeholder='Enter' + ths.TabsArray.filter(t=>t.displayCode=='PROJECT_PHASE')?.displayName +' Name' || 'Enter Phase Name';
    ths.NewTabName=ths.TabsArray.filter(t=>t.displayCode=='PROJECT_STAGE')?.displayName || 'Project Stage';
    ths.BindPhaseDropdown();
    ths.GetStageType();
    ths.GetStatusList();
    ths.ProjectOverview();
    ths.FetchTaskListByProjectId();
  },
  methods: {
    UpdateFieldsText(newTabName) {
      debugger
      var vm = this;
      // Loop through FormSchema to find and update MilestoneNumber label
      vm.FormSchema.forEach((section) => {
        if (section.Data && Array.isArray(section.Data)) {
          section.Data.forEach((field) => {
            if (field.name === 'StageName') {
              // Update the label based on newTabName

              field.label = `${this.$t(this.NewTabName)}` + ' ' + 'Name';
            }

          });
        }
      });
    },
    FetchTaskListByProjectId: function () {

      var vm = this;
      var url = `id=${this.ProjectId}&refId=`;
      DataService.GetTaskDDLData(url).then(function (response) {

        vm.FindalTaskArray = [];
        vm.TaskList = [];
        if (response.data != '' && response.data.DATA.length > 0) {
          debugger
          // Format TaskList for multiselect - ensure value and name properties
          response.data.DATA.forEach((item) => {
            var Obj = {
              value: item.value || item.id,
              name: item.label || item.name || item.text
            };
            vm.TaskList.push(Obj);
          });
        }
        // Always call FetchAddEditStage after TaskList is set (even if empty)
        vm.FetchAddEditStage();
      });
    },
    formatDate(dateValue) {
      if (!dateValue) return '';

      // If it's already a Date object
      if (dateValue instanceof Date) {
        return dateValue.toLocaleDateString("en-US");
      }

      // If it's a string, try to parse it
      if (typeof dateValue === 'string') {
        // Remove time portion if it exists
        const dateOnly = dateValue.split('T')[0];
        return new Date(dateOnly).toLocaleDateString("en-US");
      }

      // For timestamps or other formats
      return new Date(dateValue).toLocaleDateString("en-US");
    },
    ProjectOverview: async function () {
      var vm = this;
      var params = `projectId=${this.ProjectId}`;
      await DataService.ProjectOverview(params).then(function (response) {
        if (response.data != null > 0) {
          vm.ProjectStartDate = vm.formatDate(response.data.planneD_START_DATE);
          vm.ProjectEndDate = vm.formatDate(response.data.planneD_END_DATE);
          vm.ProjectName = response.data.projecT_NAME;
          let startDate = new Date(vm.ProjectStartDate);
          startDate.setDate(startDate.getDate() + 1);
          vm.HideprojectStartDate = startDate.toISOString().split('T')[0];

          let endDate = new Date(vm.ProjectEndDate);
          endDate.setDate(endDate.getDate() + 1);
          vm.HideprojectEndDate = endDate.toISOString().split('T')[0];
          //vm.HideprojectStartDate = new Date(vm.ProjectStartDate).toISOString().split('T')[0];
          //vm.HideprojectEndDate = new Date(vm.ProjectEndDate).toISOString().split('T')[0];
        }
      });
    },
    BindPhaseDropdown: function () {
      debugger
      var ths = this;
      var url = `id=&moduleName=&type=PHASE_NAME&search=&refId=${this.ProjectId}`;
      DataService.GetDDLData(url).then((response) => {
        if (response.data.DATA.length > 0) {
          response.data.DATA.forEach((item) => {
            let obj = {
              name: item.name,
              value: item.value
            }
            ths.FormSchema[0].Data[1].config.options.push(obj);
            ths.$refs.AssignTagForm.UpdateKeyValue();
          })
        }
      })
    },
    GetStageType: function () {
      var ths = this;
      DataService.GetStageType().then((response) => {
        if (response.data.result.DATA.length > 0) {
          response.data.result.DATA.forEach((item) => {
            let obj = {
              name: item.MODULE_NAME,
              value: item.MODULE_NAME
            }
            ths.FormSchema[0].Data[2].config.options.push(obj);
            const statusField = this.FormSchema[0].Data[2];
            const activeOption = statusField.config.options.find(o => o.name.toLowerCase() === "project");
            if (activeOption) {
              statusField.value = activeOption.value;
            } else if (statusField.config.options.length > 0) {
              // fallback: set first option as default
              statusField.value = statusField.config.options[0].value;
            }
            ths.$refs.AssignTagForm.UpdateKeyValue();
          })
        }
      })
    },
    GetStatusList: async function () {
      var vm = this;
      var params = `statusType=${"Project"}&hasglobal=${false}`;
      DataService.GetStatusList(params).then(async (response) => {
        if (response.data.length > 0) {
          var statusList = [];
          statusList = response.data;
          statusList.forEach((item) => {
            var obj = {
              name: item.STATUS,
              value: item.STATUS_ID
            }
            vm.FormSchema[0].Data[3].config.options.push(obj);


            const statusField = this.FormSchema[0].Data[3];
            const activeOption = statusField.config.options.find(o => o.name.toLowerCase() === "active");
            if (activeOption) {
              statusField.value = activeOption.value;
            } else if (statusField.config.options.length > 0) {
              // fallback: set first option as default
              statusField.value = statusField.config.options[0].value;
            }
            vm.$refs.AssignTagForm.UpdateKeyValue();
          })
        }
      });
    },
    CloseStage: function () {
      this.$parent.IsAddStage = false;
      this.$parent.isShowStageModel = false;
    },
    OnSubmit: function () {

      var vm = this;
      var postString = {
        StageId: 0,
        StageName: vm.FormSchema[0].Data[0].value,
        PhaseId: vm.FormSchema[0].Data[1].value,
        StatusId: vm.FormSchema[0].Data[3].value,
        StageDescription: vm.FormSchema[1].Data[0].value,
        TypeCode: vm.FormSchema[0].Data[2].value,
        ColorCode: vm.FormSchema[0].Data[4].value
      };

      var objectPostString = JSON.stringify(postString);
      DataService.AddSaveStage(objectPostString).then(async (response) => {

        vm.isLoading = false;
        if (response.data.result.DATA[0].VALUE == 'INSERT') {
          vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
          vm.IsAddIsShow = true;
          vm.FetchAddEditStage();
        } else if (response.data.result.DATA[0].VALUE == 'UPDATE') {
          vm.ShowAlert(vm.$t('UpdatedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));
        } else {
          vm.ShowAlert(vm.$t('AlreadyExists', [vm.$t(vm.NewTabName)]), "warning", true, vm.$t("Alert"));
        }
      })
    },
    isDisabled(id) {
      this.selectedStage = this.stageList.some(p => p.STAGE_ID === id);
      return this.stageList.some(p => p.STAGE_ID === id);
    },
    checkAllSelected(evt) {
      debugger
      const isChecked = evt.target.checked;
      this.AddEditStageListing.forEach(item => {
        if (item.START_DATE_SELECTED == null) {
          item.selected = isChecked;
        }

      });
      this.selectAll = isChecked;
      // Trigger form validation to show required field messages
      this.$nextTick(() => {
        this.$refs.form.validate();
      });

    },
    PhaseChange(item) {
      const allSelected = this.AddEditStageListing.filter(it => it.START_DATE_SELECTED == null).every(it => it.selected);
      this.selectAll = allSelected;
    },
    FetchAddEditStage: function () {
      var ths = this;
      var url = `projectId=${ths.ProjectId}`;
      DataService.FetchAddEditStage(url).then((response) => {
        if (response.data.result.DATA.length > 0) {

          ths.AddEditStageListing = response.data.result.DATA.map(item => ({
            ...item,
            selected: false,
          }));

          ths.AddEditStageListing.forEach(item => {
            item.CheckedValue = false;

            if (item.START_DATE != null) {
              item.CheckedValue = false;
              item.selected = false;
              item.START_DATE_SELECTED = 'selected'
            }

            // Store original TASK_ID before we modify it
            var originalTaskId = item.TASK_ID;

            // Handle task IDs - check multiple sources
            var taskIds = [];

            // First, try to get from TASK_JSON if available
            if (item.TASK_JSON != null && item.TASK_JSON !== '') {
              try {
                var parsedTaskJson = ths.MakeNormalArray(item.TASK_JSON);
                if (ths.MakeTaskArray && typeof ths.MakeTaskArray === 'function') {
                  var arrayData = ths.MakeTaskArray(parsedTaskJson);
                  if (arrayData != null && Array.isArray(arrayData) && arrayData.length > 0) {
                    // Get task IDs from arrayData
                    taskIds = arrayData.map(function (ite) {
                      return String(ite.id || ite.value || ite);
                    });
                    item.TaskModelData = String(taskIds);
                  }
                } else if (Array.isArray(parsedTaskJson)) {
                  // If TASK_JSON is already an array after parsing
                  taskIds = parsedTaskJson.map(function (ite) {
                    return String(ite.id || ite.value || ite);
                  });
                }
              } catch (e) {
                console.error('Error processing TASK_JSON:', e);
              }
            }

            // Also check if there's a direct TASK_ID field (could be string, array, or comma-separated)
            // Only use this if we didn't get task IDs from TASK_JSON
            if (taskIds.length === 0 && originalTaskId != null && originalTaskId !== '') {
              if (Array.isArray(originalTaskId)) {
                taskIds = originalTaskId.map(id => String(id));
              } else if (typeof originalTaskId === 'string') {
                if (originalTaskId.includes(',')) {
                  taskIds = originalTaskId.split(',').map(id => id.trim()).filter(id => id !== '');
                } else {
                  taskIds = [String(originalTaskId)];
                }
              } else {
                taskIds = [String(originalTaskId)];
              }
            }

            // Map task IDs to task objects from TaskList for multiselect
            if (taskIds.length > 0 && ths.TaskList.length > 0) {
              // Create a map for faster lookup to get exact object references
              var taskMap = {};
              ths.TaskList.forEach(task => {
                taskMap[String(task.value)] = task;
              });

              // Get exact objects from TaskList to ensure vue-multiselect can track them correctly
              item.TASK_ID = taskIds
                .map(id => taskMap[String(id)])
                .filter(task => task != null && task !== undefined);
            } else {
              // New case or no tasks - ensure it's an empty array
              item.TASK_ID = [];
            }
          })
          ths.noRecordForTab = false;
        } else {
          ths.noRecordForTab = true;
        }
      })
    },
    SaveStage: function () {
      debugger
      var vm = this;
      var postString = [];
      vm.$refs.form.validate().then((result) => {
        debugger
        if (result) {
          const selecteddata = vm.AddEditStageListing.filter(
            it => it.selected
          );
          debugger
          var filteredArray = vm.AddEditStageListing.filter(item => item.selected || item.START_DATE_SELECTED == 'selected');
          if (selecteddata.length === 0 && filteredArray.length === 0) {
            vm.isLoading = false;
            vm.ShowAlert("Please check at least one checkbox", "warning", true, vm.$t("Alert"));
            return false;
          }
          // Validate that all selected stages have at least one task selected
          var missingTasks = [];
          $.each(filteredArray, function (idx, item) {
            var hasTasks = item.TASK_ID && Array.isArray(item.TASK_ID) && item.TASK_ID.length > 0;
            if (!hasTasks) {
              missingTasks.push(item.STAGE_NAME || ('Stage ' + (idx + 1)));
            }
          });

          if (missingTasks.length > 0) {
            vm.ShowAlert("Please select at least one task for: " + missingTasks.join(', '), "warning", true, vm.$t("Alert"));
            return;
          }

          $.each(filteredArray, function (idx, item) {
            // Extract task IDs from multiselect array
            var taskIds = [];
            if (item.TASK_ID && Array.isArray(item.TASK_ID) && item.TASK_ID.length > 0) {
              // Extract value property from selected task objects
              taskIds = item.TASK_ID.map(task => {
                // Handle both object format {value, name} and direct value
                return (task && typeof task === 'object' && task.value !== undefined) ? task.value : task;
              }).filter(id => id != null && id !== '');
            } else if (item.TASK_ID && !Array.isArray(item.TASK_ID)) {
              // Fallback for single value
              taskIds = [item.TASK_ID].filter(id => id != null && id !== '');
            }

            var obj = {
              StageId: item.STAGE_ID,
              ProjectId: vm.ProjectId,
              SD: item.START_DATE,
              ED: item.END_DATE,
              TaskId: taskIds.length > 0 ? taskIds.join(',') : null
            }

            if (!obj.TaskId) {
              vm.ShowAlert(vm.$t('Required') + " " + vm.$t('Task'), "failure", true, vm.$t("Alert"));
              return false;

            }
            else {
              postString.push(obj);
            }
          });

          // Close stage only after all validations pass
          if (postString.length > 0 && postString.length === filteredArray.length) {
            vm.CloseStage();
          }
          let clashDates = false;
          if (postString.length > 0) {
            $.each(postString, function (idx, item) {
              if (idx > 0) {
                var chkData = $.grep(postString, function (element) {
                  return (
                    (new Date(element.SD).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                      new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                    (new Date(element.SD).setHours(0, 0, 0, 0) <= new Date(item.SD).setHours(0, 0, 0, 0) &&
                      new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.ED).setHours(0, 0, 0, 0)) ||
                    (new Date(element.ED).setHours(0, 0, 0, 0) >= new Date(item.SD).setHours(0, 0, 0, 0) &&
                      new Date(element.ED).setHours(0, 0, 0, 0) <= new Date(item.ED).setHours(0, 0, 0, 0))
                  );
                });
                if (chkData.length > 1) {
                  clashDates = true;
                }
              }
            });
          }
          if (!clashDates) {
            var objectPostString = JSON.stringify(postString);
            DataService.SaveStage(objectPostString).then((response) => {
              vm.isLoading = false;
              if (response.data.status == 'Success') {
                vm.ShowAlert(vm.$t('AddedSuccess', [vm.$t(vm.NewTabName)]), "success", true, vm.$t("Alert"));

                vm.$parent.FetchProjectStageListing();

              } else {
                vm.ShowAlert(vm.$t('AddedError', [vm.$t(vm.NewTabName)]), "failure", true, vm.$t("Alert"));
              }
            });
          } else {
            vm.isLoading = false;
            vm.ShowAlert(vm.$t('DateValidationOnStage'), "warning", true, vm.$t("Alert"));
          }
        }

      });
      //  }

    }
  }
}
</script>