<template>
    <section>

        <loader :is-visible="isLoading"></loader>
        <div class="ticketsmallfix theme-primary partition p-actions-expand " style="overflow: visible;">
            <span class="p-name text-white">{{ $t("ProjectNotes") }}</span>
            <span class="p-actions float-right">
                <a v-if="IsListCardView" @click="ChangeView('List')" title="List View" href="javascript:;"
                    class="p-action-btn text-white "><em class="fa fa-list pr-2 "></em>
                    <br><span>{{ $t('ListView') }}</span></a>
                <a v-if="!IsListCardView" @click="ChangeView('Card')" href="javascript:;" title="Card View"
                    class="p-action-btn text-white"><em class="fa fa-th-large"></em><br>{{ $t('CardView') }}</a>
                <a title="Add Note" @click="AddNotes" href="javascript:;" class="p-action-btn text-white "
                    v-if="CheckDisabled"><em class="fa fa-plus pr-2 "></em>
                    <br><span>{{ $t('AddNote') }}</span>
                </a>
                <a title="Back To List" @click="BackToList" href="javascript:;" class="p-action-btn text-white "><em
                        class="fa fa-angle-double-left pr-2"></em> <br><span>{{ $t('Back To List') }}</span></a>
            </span>
        </div>
        <div style="clear:both;"></div>
        <div class="pb-2 pt-1 d-inline-block">
            <span class="legend-Progress colorboxsquare"></span>{{ $t('Private') }} {{ $t('NOTE') }}
            <span class="legend-upcoming colorboxsquare ml-3"></span>{{ $t('Public') }} {{ $t('NOTE') }}
        </div>
        <div style="clear:both;"></div>
        <div v-if="NoRecordForTab" class="text-center text-danger p-2 border">{{ $t('NoRecordfound') }}</div>
        <div class="conversation-main" v-if="!IsListCardView">
            <template v-for="item in ListingData" v-if="!NoRecordForTab">
                <div class="conversation-time"><span>{{ $options.filters.formatTime(item.NEWTIME) }}</span></div>
                <div class="conversation-box-con">
                    <div
                        v-bind:class="{ 'conversation-box': true, 'public-note': item.IS_PUBLIC, 'private-note': !item.IS_PUBLIC }">
                        <div class="name-circle" style="background: rgb(195 207 213 / 84%);">
                            <span class="initials">
                                {{ getFirstTwoInitials(item.POSTED_BY) }}
                            </span>
                        </div>
                        <div class="conversation-header">
                            <span>
                                <span class="sender-name">{{ item.POSTED_BY }}</span>
                                <span class="sender-department">(<small class="text-danger font-14"
                                        v-bind:title="$options.filters.formatDateTime(item.CREATED_AT)">{{
                                            $options.filters.formatDateTime(item.CREATED_AT) }}</small>)</span>
                            </span>
                            <span class="">
                                <a v-if="userId == item.CREATED_BY" href="javascript:;"
                                    class="round-icon-small btn-danger-light float-right" v-on:click="DeleteNote(item)">
                                    <em class="fa fa-trash" aria-hidden="true"></em>
                                </a>
                                <a v-if="userId == item.CREATED_BY" href="javascript:;"
                                    class="round-icon-small btn-success-light float-right"
                                    v-on:click="OpenEditNote(item)">
                                    <em class="fa fa-pencil" aria-hidden="true"></em>
                                </a>
                            </span>
                        </div>
                        <div class="conversation-content">
                            <p v-html="item.NOTE_CONTENT"></p>
                        </div>
                    </div>
                </div>
            </template>
        </div>
        <div v-if="IsListCardView" class="row p-0 newcardviewdes">

            <div v-if="!NoRecordForTab" v-for="(item, index) in ListingData" :key="index"
                class="col-md-12 col-lg-6 col-xl-3 mb-4">

                <div :class="['note-card', item.IS_PUBLIC ? 'public-border' : 'private-border']">

                    <!-- Header -->
                    <div class="d-flex justify-content-between align-items-start">

                        <div class="d-flex align-items-center">
                            <div class="avatar-circle mr-2">
                                {{ getFirstTwoInitials(item.POSTED_BY) }}
                            </div>

                            <div>
                                <div class="user-name">
                                    {{ item.POSTED_BY }}
                                </div>

                                <div class="visibility-text">
                                    <i class="fa fa-users mr-1"></i>
                                    {{ item.IS_PUBLIC ? 'Public' : 'Private' }}
                                </div>
                            </div>
                        </div>

                        <!-- Actions -->
                        <div v-if="userId == item.CREATED_BY" class="action-icons">
                            <em class="fa fa-pencil text-success cursor-pointer" @click="OpenEditNote(item)"></em>
                            <em class="fa fa-trash-o text-danger cursor-pointer" @click="DeleteNote(item)"></em>
                        </div>

                    </div>

                    <!-- Content -->
                    <div class="card-body">
                        <p v-html="item.NOTE_CONTENT"></p>
                    </div>

                    <!-- Footer Date -->
                    <div class="card-footer">
                        <em class="fa fa-calendar mr-1"></em>
                        {{ item.CREATED_AT | formatDateTime }}
                    </div>

                </div>

            </div>

        </div>


        <AddNotes v-if="isAddNotes" :NoteId="NoteId" :noteText="noteText" :modalNoteItem="modalNoteItem"></AddNotes>
    </section>
</template>
<script>
import AddNotes from '../../../../components/Modal/AddNotes.vue';
import DataService from '../../../../services/DataService';

export default {
    components: { AddNotes },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        checkPmUser: {
            type: Boolean,
            required: true
        }
    },
    data() {
        return {
            NoteId: 0,
            TotalRecords: 0,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            statusId: '',
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            SortBy: '',
            SortExp: '',
            taskId: '',
            ListingData: [],
            searchCondition: '',
            IsEditTeamShow: false,
            IsListCardView: false,
            NoRecordForTab: false,
            isAddNotes: false,
            noteText: '',
            UserType: null,
            modalNoteItem: null,
            userId: null,
            TimeZone: null,
        };
    },
    created: async function () {
        var vm = this;
        vm.CompanyId = this.GetUserInfo.CompanyId;
        vm.userId = this.GetUserInfo.ID;
        vm.UserType = vm.GetUserInfo.UserType;
        vm.TimeZone = vm.GetUserInfo.TimeZone;
        await vm.FetchNoteListing();
    },
    computed: {
        sortedActivityData() {
            return [...this.ActivityData].sort((a, b) => {
                const dateA = new Date(`${a.CREATED_DATE} ${a.CREATED_TIME}`);
                const dateB = new Date(`${b.CREATED_DATE} ${b.CREATED_TIME}`);
                return dateB - dateA;
            }).slice(0, 5);
        },
    },
    methods: {
        CheckDisabled() {
            if ((this.UserType == 'CL' || this.UserType == 'NU') && this.checkPmUser) {
                return true;
            }
            else {
                if (this.UserType == 'CA' || this.UserType == 'PM') {
                    return true;
                }
                else {
                    return false;
                }

            }
        },
        ChangeView(view) {
            if (view == 'List') {
                this.IsListCardView = false;
            } else {
                this.IsListCardView = true;
            }
        },

        async FetchNoteListing() {
            var ths = this;
            var url = `projectId=${ths.projectId}&isPublic=true&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}`
            await DataService.NoteListing(url).then((response) => {
                if (response.data.result.data.length > 0) {
                    ths.ListingData = response.data.result.data;
                    ths.ListingData.forEach((item) => {
                        if (item.CREATED_AT !== null && item.CREATED_AT !== '') {
                            const originalDateObj = new Date(item.CREATED_AT);
                            const year = originalDateObj.getFullYear();
                            const month = String(originalDateObj.getMonth() + 1).padStart(2, '0');
                            const day = String(originalDateObj.getDate()).padStart(2, '0');
                            const datePart = `${year}-${month}-${day}`;
                            const hours = String(originalDateObj.getHours()).padStart(2, '0');
                            const minutes = String(originalDateObj.getMinutes()).padStart(2, '0');
                            const baseTime = `${hours}:${minutes}`;
                            const adjustedTime = ths.addTimeWithOffset(baseTime, ths.TimeZone);
                            item.CREATED_AT = `${datePart}T${adjustedTime}:00`;
                            item.NEWTIME = adjustedTime;
                        }
                    });

                    ths.TotalRecords = response.data.result.data[0].TOTALRECORDS;
                    ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
                    ths.NoRecordForTab = false;
                } else {
                    ths.TotalRecords = 0;
                    ths.TotalPages = 1;
                    ths.ListingData = [];
                    ths.NoRecordForTab = true;
                }
            });
        },
        addTimeWithOffset(time, offset) {
            if (!time || !offset) return time;
            let [hours, minutes] = time.split(":").map(Number);
            let [sign, offH, offM] = offset.match(/([+-])(\d{2}):(\d{2})/).slice(1);
            let totalMinutes = hours * 60 + minutes;
            let offsetMinutes = parseInt(offH) * 60 + parseInt(offM);
            if (sign === "-") offsetMinutes *= -1;
            totalMinutes += offsetMinutes;
            totalMinutes = ((totalMinutes % (24 * 60)) + 24 * 60) % (24 * 60);
            let hh = String(Math.floor(totalMinutes / 60)).padStart(2, "0");
            let mm = String(totalMinutes % 60).padStart(2, "0");
            return `${hh}:${mm}`;
        },
        AddNotes: async function () {
            var vm = this;
            vm.projectId = vm.projectId;
            var url = 'controller=Project&action=AddNoteInProject'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.noteText = 'Add';
                    vm.modalNoteItem = null;
                    vm.isAddNotes = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });

        },
        BackToList: function () {
            this.$router.push({ name: 'ProjectList' });
        },
        EditProject: function () {
            var vm = this;
            vm.$emit('EditProject');
        },
        DeleteNote: function (item) {
            this.modalDeleteItem = item;
            this.DeleteNoteData(this.modalDeleteItem.NOTE_ID);
        },
        DeleteNoteData: async function (id) {
            var vm = this;
            if (id > 0) {
                var url = 'controller=Project&action=DeleteNote'
                await DataService.CheckPrivilege(url).then(async function (response) {
                    if (response.data) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("ConfirmDelete")), function () {
                            var postJSON = {
                                ids: id,
                                companyId: vm.CompanyId,
                                userId: vm.userId,
                                moduleName: 'PROJECT',
                                subModuleCode: "Project_Detail",
                                refCode: 'TALYGEN_NOTES',
                                refId: vm.projectId
                            };
                            var objectPostString = JSON.stringify(postJSON);
                            DataService.CommonCommonDelete(objectPostString).then(function (response) {
                                if (response.data[0].Status == "Success") {
                                    vm.ShowAlert(vm.$t('DeletedSuccessfully'), "Success", true, vm.$t('Alert'));
                                    vm.FetchNoteListing();
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeleteError'), "warning", true, vm.$t('Alert'));
                                }
                                vm.isLoading = false;
                            }, function (response) {
                                vm.isLoading = false;
                            });

                        });
                    } else {
                        vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    }
                })

            }
        },
        OpenEditNote: async function (item) {
            var vm = this;
            vm.noteText = 'Edit';
            vm.projectId = vm.projectId;
            var url = 'controller=Project&action=EditNote'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.modalNoteItem = item;
                    vm.isAddNotes = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        getFirstTwoInitials(fullName) {
            if (!fullName) return "";

            const parts = fullName.trim().split(/\s+/);
            return (parts[0][0] + (parts[1]?.[0] || "")).toUpperCase();
        }
    }
};
</script>

<style>
.initials.user-img-con {line-height: 36px; text-align: center; font-size: 12px; font-weight: 400; background: rgba(195, 207, 213, 0.84);}
.name-circle .initials {line-height: 55px; text-align: center; font-size: 16px; font-weight: 400;}
</style>
