<template>
    <section>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="true" ModuleName="PROJECT"
            SubModuleCode="Client" IdentityColumn="STAGE_ID" :HeaderText="$t(NewTabName)" :ListData="ListingData"
            :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
            :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="FetchProjectStageListing"
            :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')"
            v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:SortdataButtonClick="sortdata" :Key=Key>
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'START_DATE'">
                    <span :title="data.row.START_DATE">
                        {{ data.row.START_DATE }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'END_DATE'">
                    <span :title="data.row.END_DATE">
                        {{ data.row.END_DATE }}
                    </span>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'STAGE_NAME'">
                    <a href="javascript:;" @click="clickEventOfColumn(data.row)" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">{{ data.row.STAGE_NAME }}</a>
                </template>
                 <template v-if="data.column.COLUMN_NAME == 'PHASE_NAME'">
                    <span style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">{{ data.row.PHASE_NAME }}</span>
                </template>
                 <template v-if="data.column.COLUMN_NAME == 'TASK_NAME'">
                    <span style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">{{ data.row.TASK_NAME }}</span>
                </template>
            </template>
        </tg-list>
        <AddStage v-if="IsAddStage" :stage-list="ListingData" :NewTabName="NewTabName" :TabsArray="TabsArray"
            :ProjectIndusrtyType="ProjectIndusrtyType">
        </AddStage>
        <AddAssociateStage v-if="IsAddAssociateStage" :stage-list="ListingData" :NewTabName="NewTabName" :TabsArray="TabsArray"
            :ProjectIndusrtyType="ProjectIndusrtyType" :EditStageId="EditStageId">
        </AddAssociateStage>
    </section>
</template>
<script>
import schema from './ProjectStageListingSchema'
import DataService from '../../../../services/DataService';
import AddStage from '../../../../components/Modal/AddStage.vue'
import AddAssociateStage from '../../../../components/Modal/AddAssociateStage.vue';
export default {
    components: { AddStage, AddAssociateStage },
    props: {
        projectId: {
            type: Number,
            required: true
        },
        checkPmUser: {
            type: Boolean,
            required: true
        },
        NewTabName: {
            type: String,
            require: true
        },
        TabsArray: {
            type: Array
        }
    },
    data() {
        return {
            Key:0,
            TotalRecords: 0,
            ProjectId: null,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            PageSize: 10,
            statusId: '',
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            taskId: '',
            Headers: [],
            ListingData: [],
            searchCondition: '',
            Buttons: [],
            ProjectStageListingSchema: false,
            UserType: null,
            IsAddStage: false,
            IsAddAssociateStage: false,
            ProjectIndusrtyType: '',
            EditStageId: null
        }
    },
    watch: {
        NewTabName: {
            handler(newTabName) {
                if (newTabName) {
                    this.updateButtons(newTabName);
                    this.updateHeaders(newTabName);
                }
            },
            immediate: true
        }
    },
    created: async function () {
        var ths = this;
        ths.ProjectId = ths.$route.params.projectId;
        ths.CompanyId = ths.GetUserInfo.CompanyId;
        ths.UserType = ths.GetUserInfo.UserType;
        ths.userId = ths.GetUserInfo.ID;
        await ths.ProjectOverview();
        if (!this.Buttons || this.Buttons.length === 0) {
            this.Buttons = JSON.parse(JSON.stringify(schema.buttons));
        }
        if (!this.Headers || this.Headers.length === 0) {
            this.Headers = JSON.parse(JSON.stringify(schema.TableHeader));
        }
        if (this.NewTabName) {
            this.updateButtons(this.NewTabName);
            this.updateHeaders(this.NewTabName);
        }
        await ths.FetchProjectStageListing();
        ths.CheckDisabled();


    },
    methods: {
        ProjectOverview: async function () {

            var vm = this;
            var params = `projectId=${vm.ProjectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data != null > 0) {

                    var ProjectDetailData = response.data.result.PROJECTOVERVIEW[0];
                    vm.ProjectIndusrtyType = ProjectDetailData.IndustryType_Name;

                    // vm.$nextTick(() => {
                    //     vm.populateTabsArray();
                    // });
                }
            });
        },
        updateButtons(newTabName) {

            // Create a deep copy of the schema buttons and update titles
            const buttonsCopy = JSON.parse(JSON.stringify(schema.buttons));
            // Update button titles/display names based on NewTabName
            if (newTabName && buttonsCopy && buttonsCopy.length > 0) {
                buttonsCopy.forEach((button, index) => {
                    // Update button titles for Construction industry
                    if (button.callbackfunction === 'StageAssociate') {
                        // Update add button title for WorkCrew
                        buttonsCopy[index].title = `${this.$t('Add')} ${this.$t(this.NewTabName)}` + ` ${this.$t('Associate')}`;
                    }

                });
            }

            // Assign the updated buttons array to trigger reactivity
            this.Buttons = buttonsCopy;
        },
        updateHeaders(newTabName) {
            this.Headers = JSON.parse(JSON.stringify(schema.TableHeader));

            if (!newTabName || !this.Headers?.length) return;

            this.Headers.forEach(header => {

                switch (header.COLUMN_NAME) {

                    case 'STAGE_NAME':
                        header.DISPLAY_NAME = `${this.$t(newTabName)} ${this.$t('Name')}`;
                        break;

                    case 'PHASE_NAME':
                        header.DISPLAY_NAME =
                            this.TabsArray.find(t => t.displayCode === 'PROJECT_PHASE')?.displayName
                            || this.$t('Phase Name');
                        break;

                    case 'TASK_NAME':
                        header.DISPLAY_NAME =
                            this.TabsArray.find(t => t.displayCode === 'PROJECT_TASKS')?.displayName
                            || this.$t('Tasks');

                        header.VISIBLE = this.ProjectIndustryType !== 'Construction';
                        break;
                }

            });
        },
        CheckDisabled() {
            if ((this.UserType == 'CL' || this.UserType == 'NU') && this.checkPmUser) {
                this.Buttons[0].isvisible = true;
                this.Buttons[1].isvisible = true;
                this.Buttons[2].isvisible = true;
            }
            else {
                if (this.UserType == 'CA' || this.UserType == 'PM') {
                    this.Buttons[0].isvisible = true;
                    this.Buttons[1].isvisible = true;
                    this.Buttons[2].isvisible = true;
                }
                else {
                    this.Buttons[0].isvisible = false;
                    this.Buttons[1].isvisible = false;
                    this.Buttons[2].isvisible = false;
                }

            }
        },
        closepopup() {
            this.ProjectStageListingSchema = false;
        },
        renderActions() { },
        pagerMethod() { },
        commonHeaderButtonClick: function (event) {
            switch (event.callbackfunction) {
                case "Deletedata":
                    this.DeleteStage();
                    break;
                case "AddStage":
                    this.AddStage();
                    break;
                case "StageAssociate":
                    this.StageAssociate();
                    break;
                case "EportTask":
                    this.EportTask();
                    break;
                case "OpenAddTaskPopup":
                    this.OpenAddTaskPopup();
                    break;
                case "EditTask":
                    this.EditTask();
                    break;
                case "BackToList":
                    this.BackToList();
                    break;
            }
        },
        sortdata: function () { },
        DeleteStage: async function (event) {
            var vm = this;
            var val = "";
            var url = `controller=Stage&action=Delete`;
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.isLoading = true;
                    $('.chkItems:checkbox:checked').not("[id^='chkAll']").each(function () {
                        if (val.length > 0)
                            val += ',';
                        val += $(this).val();
                    });
                    if (val != null) {
                        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Stage")), function () {
                            var obj = {
                                ProjectId: vm.projectId,
                                StageIds: val
                            };
                            var objectPostString = JSON.stringify(obj)
                            DataService.DeleteStage(objectPostString).then(function (response) {
                                if (response.data.result.DATA[0].VALUE == 'SUCCESS') {
                                    vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Stage')]), "success", true, vm.$t("Alert"));
                                    vm.Buttons[2].isEnabledOnSelectedRow = true;
                                    vm.isLoading = false;
                                    vm.FetchProjectStageListing();
                                    vm.Key++;
                                }
                                else {
                                    vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Stage')]), "failure", true, vm.$t("Alert"));
                                }
                            });
                        });
                    }
                    else {
                        vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
                    }
                    vm.isLoading = false;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        AddStage: async function () {

            var vm = this;
            var url = 'controller=Stage&action=Add'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.IsAddStage = true;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
        },
        StageAssociate: function () {
            this.EditStageId = null;
            this.IsAddAssociateStage = true;
        },
        ExporttoExcel: function () { },
        EportTask: function () { },
        OpenAddTaskPopup: function () {
            this.ProjectStageListingSchema = true;
        },
        EditTask() {
            this.$emit('EditProject');
        },
        BackToList: function () {
            var ths = this;
            ths.$router.push({ name: 'ProjectList' });
        },
        FetchProjectStageListing: async function () {            
            var vueObj = this;
            vueObj.isLoading = true;
            var params = `projectId=${vueObj.projectId}&sortBy=${vueObj.SortBy}&sortExp=${vueObj.SortExp}&pageSize=${vueObj.PageSize}&pageNum=${vueObj.PageNumber}`;
            await DataService.StageListing(params).then(function (response) {
                if (response.data.result.data.length > 0) {
                    vueObj.ListingData = response.data.result.data;
                    vueObj.ListingData.forEach((item) => {
                        item.isCheckBoxDisabled = false;
                        if (item.COMPANY_ID == 0) {                            
                            item.isCheckBoxDisabled = true;
                        }
                        item.START_DATE = vueObj.$d(new Date(item.START_DATE));
                        item.END_DATE = vueObj.$d(new Date(item.END_DATE));
                    });
                    vueObj.TotalRecords = response.data.result.data[0].TOTAL_RECORDS;
                    vueObj.TotalPages = Math.ceil(vueObj.TotalRecords / vueObj.PageSize);
                } else {
                    vueObj.TotalRecords = 0;
                    vueObj.TotalPages = 1;
                    vueObj.ListingData = [];
                }
            });
        },
        async clickEventOfColumn(row) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateStage'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                vm.EditStageId = row.STAGE_ID;
                vm.IsAddAssociateStage = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            }); 
           

        }
    }

}
</script>
<style>
.task-dec {
    color: #007bff !important;
    text-decoration: none;
    background-color: transparent;
}
</style>