            //         "Size":vm.file ? vm.file.size : null,
            //         "Extension":vm.file ? vm.file.name.substring(vm.file.name.lastIndexOf('.')) : null
            //     }
            //         const formData = new FormData();
            //         formData.append("fileId", 0);
            //         formData.append("folderId", 0);
            //         formData.append("moduleName", "PROJECT");
            //         formData.append("subModuleName", "");
            //         formData.append("isGlobal", 0);
            //         formData.append('file', vm.file);
            //         formData.append("contentType",vm.file.type);
            //         await DataService.UploadStreamNew(formData).then(response => {
            //             debugger
            //             const newdata = response && response.data ? response.data : null;
            //             if (!newdata) {
            //                 throw new Error("Empty response from DocStorage upload");
            //             }
            //             if (newdata.UploadStatus !== 1) {
            //                 throw new Error(newdata.ErrorMsg || "DocStorage upload failed");
            //             }
            //             return newdata;
            //         }).catch(err => {
            //             console.log(err);
            //         })
            //     }
            //     catch (ex) {
            //         console.error("Error processing attachments:", ex);
            //     }
            //     vm.isLoading=false;
            //     this.$parent.IsNewVersionUpload = false;
            // },


            UploadNewVersionData: async function () {
                var vm = this;
                if(vm.selectedFile==null)
               {
                   vm.ShowAlert(vm.$t('Selectatleastonefile'), "failure", true, vm.$t("Alert"));
                   return;
               }
                if (vm.IsNewVersionUpload) {
                    return;
                }
                vm.isLoading=true;
                vm.IsNewVersionUpload = true;

                if (vm.selectedFile) {
                    var uploadedInfo =  await vm.uploadToDocStorage(vm.selectedFile)
                    
                    var fileUrl = uploadedInfo.FilePath;
                    var FileName = uploadedInfo.FileName;   
                    var FileThumb = uploadedInfo.FileThumbPath;
                }

                var VarObject = {
                    FileTitle: FileName,
                    FilePath: fileUrl,
                    ProjectId: vm.ProjectId,                    
                    FileId: vm.FileId,
                    FileThumPath:FileThumb,
                    ContentType:vm.contentType
                }
                const formData = new FormData();
                formData.append("postString", JSON.stringify(VarObject));
                DataService.UploadNewVersion(formData).then((response)=>{

                    if (response.data == "File New Version Added Successfully") 
                    {
                        vm.ShowAlert("File Added Successfully!", "success", true, vm.$t("Alert"));
                        this.$parent.IsNewVersionUpload = false;
                        this.$parent.GetFilesListing();


                    }
                    else{

                        vm.ShowAlert("File Not Upload!", "failure", true, vm.$t("Alert"));

                    }

                });
                vm.isLoading=false;

            },

            Close: function () {
                
                var vm = this;
                vm.$parent.IsNewVersionUpload = false;
            },




        }
    }
