<template>
    <section>
        <div>
            <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="true" ModuleName="PROJECT"
                SubModuleCode="Client" IdentityColumn="EXPENSE_LIMIT_ID" :HeaderText="$t('ExpenseLimit')" 
                :ListData="ListingData" :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons"
                :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions"
                :ListDataCallBackFunction="ExpenseListing" :SortExp="SortExp" :SortBy="SortBy"
                :NorecordfoundText="$t('NoRecordfound')" v-on:PagerButtonClick="pagerMethod"
                v-on:HeaderButtonClick="commonHeaderButtonClick" v-on:SortdataButtonClick="sortdata" :Key="Key">
                <template v-slot:slotdata="{ data }">
                    <template v-if="data.column.COLUMN_NAME === 'CATEGORY_NAME'">
                        <span class="text-primary" :title="data.row[data.column.COLUMN_NAME]"
                            @click="AddanExpenseLimit(data.row.EXPENSE_LIMIT_ID)" data-toggle="tooltip"
                            style="cursor: pointer;">
                            {{ data.row[data.column.COLUMN_NAME] }}
                        </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'STATUS_ID'">
                        <listing-status :isfor="'ExpenseLimit'" ref="updatestatus" :dataid="data.row.EXPENSE_LIMIT_ID"
                            data-controller="Project" :statuslist="StatusListForListing" :item="data.STATUS_ID"
                            data-action="index" :dataselected="data.row.STATUS_ID == 1001 ? 'Active' : 'Inactive'"
                            :callbackfunction="ExpenseListing" :isselectedvaluestring="true" :title="data.row.STATUS_ID == 1001 ? 'Active' : 'Inactive'">
                        </listing-status>
                        <a class="inactive-disabled" v-if="!isCRMShowStausDrop(data.row.STATUS_ID, 'Ticketing')">
                            <span v-bind:class="getStatusClass(data.row.STATUS_ID, 'STATUS_ID')">
                                {{ data.row[data.column.COLUMN_NAME] }}
                            </span>
                        </a>
                    </template>
                       <template v-if="data.column.COLUMN_NAME == 'EXPENSE_TRANS_APPROVAL'">
                        <span :title="data.row.EXPENSE_TRANS_APPROVAL == 1 ? $t('Yes') : $t('No')">
                        <span v-if="data.row.EXPENSE_TRANS_APPROVAL == 1">{{$t("Yes")}}</span>
                        <span v-else>{{$t("No")}}</span>
                         </span> 
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'EXPENSE_MAX'">
                      <span :title="$n(data.row.EXPENSE_MAX ? data.row.EXPENSE_MAX: 0,'currency',$getLocaleByCurrency(Currency))"> {{$n(data.row.EXPENSE_MAX ? data.row.EXPENSE_MAX: 0,'currency',$getLocaleByCurrency(Currency))  }}</span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME == 'EXPENSE_PER_DAY'">
                      <span :title="$n(data.row.EXPENSE_PER_DAY ? data.row.EXPENSE_PER_DAY: 0,'currency',$getLocaleByCurrency(Currency))"> {{$n(data.row.EXPENSE_PER_DAY ?data.row.EXPENSE_PER_DAY:0 ,'currency',$getLocaleByCurrency(Currency))  }}</span>
                    </template>
                   <template v-if="data.column.COLUMN_NAME == 'EXPENSE_OVER_LIMIT'">
                    <span :title="data.row.EXPENSE_OVER_LIMIT == 1 ? $t('Yes') : $t('No')">
                        <span v-if="data.row.EXPENSE_OVER_LIMIT == 1"> {{$t("Yes")}}</span>
                        <span v-else>{{$t("No")}}</span>
                    </span>
                    </template>
                    <template v-if="data.column.COLUMN_NAME === 'TimePeriod'">
                        <span class="" :title="$options.filters.formatDate(data.row.EXPENSE_LIMIT_FROM) +'-'+ $options.filters.formatDate(data.row.EXPENSE_LIMIT_TO)" data-toggle="tooltip"
                            style="cursor: pointer;">
                            {{ $options.filters.formatDate(data.row.EXPENSE_LIMIT_FROM) }}-{{
                            $options.filters.formatDate(data.row.EXPENSE_LIMIT_TO) }}
                        </span>
                    </template>
                </template>
            </tg-list>
        </div>
        <AddExpenseLimit v-if="ExpenseLimitSchema" :expenseLimitId="expenseLimitId" :ProjectBudget="ProjectBudget">
        </AddExpenseLimit>
    </section>
</template>
<script>
import Schema from './ExpenseLimitSchema'
import DataService from '../../../../services/DataService';
import AddExpenseLimit from '../../../../components/Modal/AddExpenseLimit.vue';
export default {
  components: { AddExpenseLimit },
  props: {
    projectId: {
      type: Number,
      required: true
    }
  },
  data() {
    return {
      TotalRecords: 0,
      noRecord: false,
      isLoading: false,
      CompanyId: null,
      PageSize: 10,
      categoryId: null,
      expenseLimitId: 0,
      statusId: '',
      PageNumber: 1,
      isPaged: 1,
      TotalPages: 0,
      widgets: [],
      SortBy: '',
      SortExp: '',
      taskId: '',
      Key:0,
      StatusListForListing: [
        {
          STATUS: 'Active',
          STATUS_ID: 1001,
          STATUS_COLOR: "#ffffff",
          STATUS_BG_COLOR: "#28a745",
        },
        {
          STATUS: 'Inactive',
          STATUS_ID: 1002,
          STATUS_COLOR: "#ffffff",
          STATUS_BG_COLOR: "#d72435",
        },
      ],
      Headers: Schema.TableHeader,
      ListingData: [],
      searchCondition: '',
      Buttons: Schema.buttons,
      ExpenseLimitSchema: false,
      ProjectBudget: 0,
      Currency:'',
    };
  },
  created() {
    this.CompanyId = this.GetUserInfo.CompanyId;
    this.userId = this.GetUserInfo.ID;
    this.Currency=this.GetUserInfo.Currency.replace(/[()]/g, '');
    this.ExpenseListing();
  },
  // updated() {
  //       const divElement = document.getElementsByClassName('theme-primary partition p-actions-expand')
  //       if (divElement[0] && divElement[0].lastChild.className != 'p-name text-white') {
  //           const spanElement = document.createElement('span')
  //           spanElement.className = "p-name text-white"
  //           spanElement.textContent = this.$t('');
  //           divElement[0].appendChild(spanElement);
  //       }
  //   },
  methods: {
    closepopup() {
      this.ExpenseLimitSchema = false;
    },
    renderActions() {
      // Render actions logic
    },
    pagerMethod() {
      // Pager method logic
    },
    actionButtonClick: function (callbackfunction, item) {
      switch (callbackfunction) {

        case 'DeleteClientData':
          this.commonDeleteData(item.EXPENSE_LIMIT_ID);
          break;
      }
    },
    commonHeaderButtonClick(event) {
      var vm = this;
      switch (event.callbackfunction) {
        case "ExpenseLimitSchema":
          this.AddanExpenseLimit(0);
          break;
        case "EditProject":
          this.EditProject();
          break;
        case "BackToList":
          this.BackToList();
          break;
        case "DeleteClientData":
          this.commonDeleteData();
          break;
      }
    },
    sortdata() {
      // Sorting logic
    },
    commonDeleteData:async function (id) {
      var vm = this;
      var url = 'controller=ExpenseLimit&action=DeleteExpenseLimits'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                  var val = "";
      vm.isLoading = true;
      if (id == null) {

        $('.chkItems:checkbox:checked').not("[id^='chkAll_0']").each(function () {
          if (val.length > 0)
            val += ',';
          val += $(this).val();
        });
      }
      else {
        val = id;
      }
      if (val != null) {
        vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("ExpenseLimit")), function () {
          var postJSON = {
            ids: val,
            subModuleCode: "PROJECT_EXPENSE_LIMIT",
            refCode: "TALYGEN_EXPENSE_LIMIT"
          };
          var objectPostString = JSON.stringify(postJSON);
          DataService.CommonCommonDelete(objectPostString).then(function (response) {
            vm.isLoading = false;
            if (response.status == 200) {
              vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('Expense')]), "success", true, vm.$t("Alert"));
              vm.ExpenseListing();
              vm.Key++;
            }
            else {
              vm.ShowAlert(vm.$t('DeletedError', [vm.$t('Expense')]), "Success", true, vm.$t("Alert"));
            }
          });
        });
      }
      else {
        vm.ShowAlert(vm.$t("Selectanyrecordtodelete"));
      }
      vm.isLoading = false;
                } else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
    },
    Pin() {
      // Pin logic
    },
    ExporttoExcel() {
      // Export to Excel logic
    },
    EportTask() {
      // Export task logic
    },
    async AddanExpenseLimit(id) {
      var vm = this;
      var url = 'controller=ExpenseLimit&action=Manage'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          vm.expenseLimitId = id;
          vm.ExpenseLimitSchema = true;
        } else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    },
    EditProject() {
      this.$emit('EditProject');
    },
    BackToList() {
      this.$router.push({ name: 'ProjectList' });
    },
    getStatusClass(status) {
      let returnClass = '';
      switch (status) {
        case 'Active':
          returnClass = 'px-2 text-center bg-success text-white d-block';
          break;
        case 'Inactive':
          returnClass = 'px-2 text-center bg-danger text-white d-block';
          break;
        default:
          returnClass = '';
      }
      return returnClass;
    },
    ExpenseListing: async function () {
      var vm=this;
      const params = `projectId=${vm.projectId}&search=&sortBy=${vm.SortBy}&sortExp=${vm.SortExp}&pageSize=${vm.PageSize}&pageNum=${vm.PageNumber}`;
      var url = 'controller=ExpenseLimit&action=Index'
      await DataService.CheckPrivilege(url).then(async function (response) {
        if (response.data) {
          try {
                const res = await DataService.ExpenseLimitListing(params);  
                if(res.data.result.data.length>0){
                  vm.ListingData = res.data.result.data;
                  vm.TotalRecords = vm.ListingData[0].TOTAL_RECORDS;
                  vm.ProjectBudget = vm.ListingData[0].PROJECT_BUDGET;
                  vm.TotalPages = Math.ceil(vm.TotalRecords / vm.PageSize);
                }else{
                  vm.ListingData = [];
                }
                

            } catch (error) {
                console.error("Error fetching expense listing:", error);
            }

        } else {
          vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
        }
      });
    }
  }
};
</script>
