<template>
  <div class="my-popups">
    <div class="modal d-block">
      <div class="modal-dialog modal-dialog-centered">
        <div class="modal-content">
          <div class="modal-header theme-primary partition-full d-flex">
            <h4 class="modal-title">{{ modalTitle }}</h4>
            <button type="button" class="close" @click="Close">
              <em class="fa fa-times" aria-hidden="true"></em>
            </button>
          </div>
          <div class="modal-body">
            <dynamic-form
              ref="componentForm"
              lang="en"
              :schema="FormSchema"
              :buttons="buttons"
              :mandatorytext="MandatoryString"
              @OnSubmit="OnSubmit"
            />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import DataService from '../../services/DataService';
export default {
  props: {
    componentData: {
      type: Object,
      default: null
    }
  },
  computed: {
    modalTitle() {
      var id = this.ComponentId != null && this.ComponentId !== '' ? Number(this.ComponentId) : 0
      return id > 0
        ? `${this.$t('Edit')} ${this.$t('Component')}`
        : `${this.$t('Add')} ${this.$t('Component')}`
    }
  },
  data() {
    return {
      MandatoryString: 'Fields marked with an asterisk (*) are mandatory.',
      ComponentId: 0,
      isLoading: false,
      FormSchema: [
        {
          layoutType: 'single',
          Data: [
            {
              astype: 'TextField',
              label: this.$t('Component Name'),
              name: 'ComponentName',
              value: '',
              placeholder: this.$t('Enter Component Name'),
              validationRules: { required: true, max: 200 }
            },
            {
              astype: 'TextAreaField',
              label: this.$t('Component Description'),
              name: 'ComponentDescription',
              value: '',
              placeholder: this.$t('Enter Component Description'),
              validationRules: { required: true, max: 4000 },
              config: { rows: 4 }
            }
          ]
        }
      ],
      buttons: [
        {
          type: 'submit',
          class: 'btn btn-success',
          text: "<i class='fa fa-save pr-2'></i>Save",
          isVisible: true
        },
        {
          type: 'button',
          class: 'btn btn-danger',
          text: "<i class='fa fa-close pr-2'></i>Cancel",
          onClick: this.Close
        }
      ]
    }
  },
  created() {
    if (this.componentData && this.hasComponentId(this.componentData)) {
      this.EditDetail(this.componentData)
    } else {
      this.resetForm()
    }
  },
  mounted() {
    var form = this.$refs.componentForm
    if (form && typeof form.UpdateKeyValue === 'function') {
      this.$nextTick(function () {
        form.UpdateKeyValue()
      })
    }
  },
  methods: {
    hasComponentId(data) {
      if (!data || typeof data !== 'object') return false
      var id = data.component_id != null ? data.component_id : data.COMPONENT_ID
      return id != null && id !== '' && Number(id) > 0
    },
    resetForm() {
      this.ComponentId = 0
      this.FormSchema[0].Data[0].value = ''
      this.FormSchema[0].Data[1].value = ''
    },
    EditDetail(data) {
      var id = data.component_id != null ? data.component_id : data.COMPONENT_ID
      this.ComponentId = id != null ? Number(id) : 0
      this.FormSchema[0].Data[0].value = data.component_name != null ? data.component_name : (data.COMPONENT_NAME || '')
      this.FormSchema[0].Data[1].value = data.component_desc != null ? data.component_desc : (data.COMPONENT_DESC || '')
    },
    OnSubmit: async function () {
      var ths = this
      ths.isLoading = true
      var obj = {
        Id: ths.ComponentId,
        Project_id: ths.$route.params.projectId,
        Subject: ths.FormSchema[0].Data[0].value,
        StatusId: 1001,
        Description: ths.FormSchema[0].Data[1].value,
        Type: 'Component'
      }

      await DataService.AddComponentAndEnvironment(JSON.stringify(obj)).then(function (response) {
        ths.isLoading = false
        var data = response && response.data && response.data.result && response.data.result.DATA
        if (data && data.length > 0) {
          if (data[0].VALUE === 'UPDATE') {
            ths.ShowAlert(ths.$t('UpdatedSuccess', [ths.$t('Component')]), 'success', true, ths.$t('Alert'))
          } else if (data[0].VALUE === 'DUPLICATE' || data[0].VALUE === 'EXISTS') {
            ths.ShowAlert(ths.$t('AlreadyExists', [ths.$t('Component')]), 'failure', true, ths.$t('Alert'))
          } else {
            ths.ShowAlert(ths.$t('AddedSuccess', [ths.$t('Component')]), 'success', true, ths.$t('Alert'))
          }
          ths.Close()
          if (ths.$parent && typeof ths.$parent.FetchData === 'function') {
            ths.$parent.FetchData()
          }
        } else {
          ths.ShowAlert(ths.$t('UnknownErrorOccur'), 'failure', true, ths.$t('Alert'))
        }
      }).catch(function () {
        ths.isLoading = false
        ths.ShowAlert(ths.$t('UnknownErrorOccur'), 'failure', true, ths.$t('Alert'))
      })
    },
    Close() {
      this.$emit('close')
    }
  }
}
</script>
