<template>
  <div>
    <loader :is-visible="isLoading"></loader>
    <transition name="modal">
      <div class="my-popups">
        <div class="modal d-block" id="myModal">
          <div class="modal-dialog modal-dialog-centered">
            <div class="modal-content">
              <div class="modal-header">
                <h4 class="modal-title">
                  {{ $t(`Add`) }} {{ $t("Manage") }} {{ $t("Attendee") }}
                </h4>
                <button type="button" class="close" @click="CancelAttendee">
                  <i class="fa fa-times" aria-hidden="true"></i>
                </button>
              </div>
              <div class="modal-body p-0">
                <div class="p-3">
                  <!-- <p class="text-muted">{{ $t('AddAttendeeDescription') }}</p> -->

                  <dynamic-form
                    lang="en"
                    :key="formKey"
                    :schema="FormSchema"
                    ref="AddAttendeeForm"
                  >
                  </dynamic-form>

                  <div class="search-btm-btn mb-4">
                    <button
                      title=""
                      class="btn btn-success formbtn float-right widthhalf text-white"
                      data-toggle-tooltip="tooltip"
                      data-original-title="Add Ticket"
                      @click="addTicket"
                    >
                      <i class="fa fa-plus pr-2"   ></i>{{ $t("Add Ticket") }}
                    </button>
                  </div>

                  <div v-if="tickets.length > 0" class="listing mt-2 p-3">
                    <div class="table-responsive">
                      <table
                        class="table table-bordered dt-responsive nowrap mt-0"
                      >
                        <thead class="thead-bg">
                          <tr>
                            <th><span>Ticket</span></th>
                            <th><span>Price</span></th>
                            <th><span>Available Quantity</span></th>
                            <th><span>Quantity</span></th>
                            <th><span>Total Amount</span></th>
                            <th class="text-center">
                              
                              <a href="javascript:;" style="display: none"
                                ><i
                                  class="fa fa-plus-circle text-success"
                                  style="font-size: 20px"
                                ></i
                              ></a>
                            </th>
                          </tr>
                        </thead>
                       
                          <!----><!---->
                         <tbody>
  <tr v-for="(ticket, index) in tickets" :key="index">
    <td>
      <select v-model="ticket.ticketId" class="form-control">
        <option value="">Select Ticket</option>
      </select>
    </td>

    <td>
      <input v-model="ticket.price" disabled class="form-control" />
    </td>

    <td>
      <input v-model="ticket.availableQty" disabled class="form-control" />
    </td>

    <td>
      <input
        v-model.number="ticket.quantity"
        @input="calculateTotal(index)"
        class="form-control"
      />
    </td>

    <td>
      <input v-model="ticket.totalAmount" disabled class="form-control" />
    </td>

    <td class="single-action text-center">
      <a @click="removeTicket(index)">
        <i class="fa fa-trash text-danger action-icon"></i>
      </a>
    </td>
  </tr>

                          <!----><!---->
                        </tbody>
                      </table>
                    </div>
                  </div>
                  <div class="row">
                    <div class="col-6">
                      <div class="py-2">
                        <span class="mandatory"
                          >Fields marked with an asterisk (*) are
                          mandatory.</span
                        >
                      </div>
                    </div>
                    <!---->
                    <div class="text-end text-right col-6">
                      <button
                        @click="OnSubmit"
                        type="submit"
                        class="btn btn-success"
                      >
                        <i class="fa fa-save pr-2"></i>Save</button
                      ><!----><!----><button
                        type="button"
                        @click="CancelAttendee"
                        class="btn btn-danger"
                        style="margin-left: 5px"
                      >
                        <i class="fa fa-close pr-2"></i>Cancel
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </transition>
  </div>
</template>

<script>
import DataService from "@/services/DataService";
export default {
  name: "AddAttendee",

  data() {
    return {
      FormSchema: [],
      isLoading: false,
      formKey: 0,
      tickets: []   
    };
  },

  async created() {
    await this.loadFromSchema();
  },

  methods: {
     addTicket() {
      debugger;
    this.tickets.push({
      ticketId: "",
      price: "",
      availableQty: "",
      quantity: 0,
      totalAmount: 0,
      consumer_id  : 0 ,
    });
  },

  removeTicket(index) {
      this.confirmR(
                this.$t("ConfirmDelete"),
                true,
                `${this.$t("ok")}  ${this.$t("cancel")}`,
                () => {
                    this.tickets.splice(index, 1);
                    // this.$emit('attachment-removed', { item, index });
                }
            );
    
  },

    calculateTotal(index) {
    const ticket = this.tickets[index];
    ticket.totalAmount = ticket.price * ticket.quantity;
  },

    async onChangeEventForFields(x, y, z) {
      if (y.label.toLowerCase() === "country") {
        await this.GetStateDistrictCity(y.value, y.label, "state");
      }

      if (y.label.toLowerCase() === "state") {
        await this.GetStateDistrictCity(y.value, y.label, "STATE_DISTRICT");
      }

      if (y.label.toLowerCase() === "city") {
        await this.GetStateDistrictCity(y.value, y.label, "DISTRICT_ZIPCODE");
      }
    },

    async GetStateDistrictCity(id, label, type) {
      this.isLoading = true;
      try {
        const url = `id=&moduleName=Event&type=${type}&search=&refId=${id}`;

        const response = await DataService.GetDDLData(url);

        if (response.status === 200) {
          const data = response?.data?.DATA;

          if (data && data.length > 0) {
            const options = data.map((el) => ({
              name: el.name,
              value: el.value,
            }));

            if (label.toLowerCase() === "country") {
              this.FormSchema[0].Data.forEach((field, index) => {
                if (field.label.toLowerCase() === "state") {
                  this.FormSchema[0].Data[index].config.options = options;
                  this.FormSchema[0].Data[index].value = "";
                }

                if (field.label.toLowerCase() === "city") {
                  this.FormSchema[0].Data[index].config.options = [];
                  this.FormSchema[0].Data[index].value = "";
                }

                if (field.label.toLowerCase() === "zipcode") {
                  this.FormSchema[0].Data[index].config.options = [];
                  this.FormSchema[0].Data[index].value = "";
                }
              });
            }

            if (label.toLowerCase() === "state") {
              this.FormSchema[0].Data.forEach((field, index) => {
                if (field.label.toLowerCase() === "city") {
                  this.FormSchema[0].Data[index].config.options = options;
                }
                if (field.label.toLowerCase() === "zipcode") {
                  this.FormSchema[0].Data[index].config.options = [];
                  this.FormSchema[0].Data[index].value = "";
                }
              });
            }

            if (label.toLowerCase() === "city") {
              this.FormSchema[0].Data.forEach((field, index) => {
                if (field.label.toLowerCase() === "zipcode") {
                  this.FormSchema[0].Data[index].config.options = options;
                }
              });
            }

            this.formKey++;
            // this.$refs.AddAttendeeForm.UpdateKeyValue();
          }
        }
      } catch (error) {
        console.error("Error fetching project priority:", error);
      } finally {
        this.isLoading = false;
      }
    },

    async loadFromSchema() {
      debugger
      try {
        this.isLoading = true;

        const url = `recordId=${this.$route.params.projectId}&moduleName=Event&subModuleCode=EM_EVENT_REG`;

        const response = await DataService.GetDynamicForm(url);

        if (response && response.data) {
          this.EventData = response.data.data;

          this.FormSchema =
            this.$refs.AddAttendeeForm.ConvertCustomFieldIntoDynamicFormObj(
              this.EventData
            );            
          this.FormSchema.forEach((group) => {
            group.Data.forEach((field) => {
              if (field.name == 'consumer_id') {
                debugger
                  field.value=null;
              }
              if (field.name == 'status_id') {
                  field.value=1001;
              }
              field.config.onChange = this.onChangeEventForFields;
            });
          });

          this.formKey++;
        }
      } catch (error) {
        console.error("Error loading dynamic form:", error);
      } finally {
        this.isLoading = false;
      }
    },

    CancelAttendee() {
      this.$emit("close");
    },

    async OnSubmit() {
      const isValid = await this.$refs.AddAttendeeForm.validateForm.validate();

      if (!isValid) {
        return null;
      }
      debugger
      let emailid = ''
      let password  = ''
  
      let mapData = this.FormSchema[0].Data.map((item)=> {

          if(item.name.toLowerCase() === 'email_id') {
            emailid = item.value
          }
          if(item.name.toLowerCase() === 'password') {
            password = item.value
          }
          return {
         field_name  : item.name,
         field_value : item.value,
         custom_field_id : item.customFieldId
      }
      })

      let body = {
          data : mapData,
          ticketItemList : this.tickets,
          companyId : this.GetUserInfo.CompanyId,
          userId : this.GetUserInfo.ID,
          password,
          emailid

      }

      try {
        this.isLoading = true;
        const response = await DataService.SaveAttendee(JSON.stringify(body));

        console.log(response , "respon")

         if(response.body.status == 'Success') {
             if(response.body.code == 1){
                  if(response.body.consumer_id  > 0) {
                     this.ShowAlert(this.$t("UpdatedSuccess"), "success", true, this.$t("Alert"));
                  
               
                  } else {
                     this.ShowAlert(this.$t("AddedSuccess"), "success", true, this.$t("Alert"));
                  
                  }
                  this.$emit("saved");
                  this.CancelAttendee()
             }else{
                  this.ShowAlert(this.$t("ErrorAddingAttendee"), "error", true, this.$t("Alert"));
               
             }
         } else if (response.body.status == 'AlreadyExixts') {
              this.ShowAlert(this.$t("EmailAlreadyExists"), "error", true, this.$t("Alert"));
         } else if (response.body.status == 'TicketNoAvailable') {
              this.ShowAlert(this.$t("TicketNoAvailable"), "error", true, this.$t("Alert"));
         } else {
              this.ShowAlert(this.$t("ErrorAddingAttendee"), "error", true, this.$t("Alert"));
            
         }
      } catch (error) {
        console.error("Error saving attendee:", error);
        this.ShowAlert(this.$t("ErrorAddingAttendee"), "error", true, this.$t("Alert"));
      } finally {
        this.isLoading = false;
      }
    },
  },
};
</script>
