        vm.logged_usertype = vm.GetUserInfo.UserType;
        vm.TimeZone = vm.GetUserInfo.TimeZone;
        vm.CurrencyCode = vm.GetUserInfo.Currency.replace(/[()]/g, '');
        vm.UpdateOverView();
        vm.CheckDisabled();
        Promise.all([
            vm.FetchTeamListing(),
            vm.GetTeamForAssociateProject()
        ])
            .then(([users, teams]) => {
                var TeamListt = [...users, ...teams];
                vm.TeamList = TeamListt.splice(0, 5);
            })
            .catch(err => {
                console.error("❌ Error loading data:", err);
            });
        this.loadDummyData();
    },
    methods: {
        CheckDisabled() {
            if (this.Template_Name == 'Bug Tracking') {
                const hasBudget = this.TabsArray.includes("Budget");
                if (hasBudget) {
                    return true;
                }
            }
            else {
                if ((this.logged_usertype == 'CL' || this.logged_usertype == 'NU') && this.checkPmUser) {
                    return true;
                }
                else {
                    if (this.logged_usertype == 'CA' || this.logged_usertype == 'PM') {
                        return true;
                    }
                    else {
                        return false;
                    }
                }
            }
        },
        BackToList() {
            this.$router.push({ name: 'ProjectList' })
        },
        EditProject() {
            this.$router.push({ name: 'EditProject', params: { project_id: this.project_id } })
        },
        UpdateOverView: async function () {
            var vm = this;
            var params = `projectId=${this.projectId}&subModuleCode=PROJECT_DETAIL`;
            vm.GetProjectDetails();
            await DataService.GetActivityDatalisting(params).then(function (response) {
                if (response.data.status == 'Success') {
                    vm.ActivityData = response.data.result.DATA;
                    vm.ActivityData.forEach((item) => {
                        if (item.CREATED_TIME != null || item.CREATED_TIME != '') {
                            item.CREATED_TIME = vm.addTimeWithOffset(item.CREATED_TIME, vm.TimeZone);
                        }
                    })
                } else {
                    vm.ActivityData = [];
                }
            });
        },
        GetProjectDetails: async function () {
            var vm = this;
            var params = `projectId=${vm.projectId}`;
            await DataService.GetProjectDetails(params).then(function (response) {
                if (response.data.result != null && response.data.result != '') {
                    vm.ProjectDetailData = [];
                    vm.ProjectDetailData.push(response.data.result.PROJECTOVERVIEW[0]);
                    vm.ProjectDetailData.forEach((item) => {
                        if (item.PLANNED_END_DATE != null || item.PLANNED_END_DATE != '') {
                            item.PLANNED_END_DATE = new Date(item.PLANNED_END_DATE)
                        }
                        if (item.PLANNED_START_DATE != null || item.PLANNED_START_DATE != '') {
                            item.PLANNED_START_DATE = new Date(item.PLANNED_START_DATE)
                        }
                        if (item.CREATED_AT != null || item.CREATED_AT != '') {
                            item.CREATED_AT = new Date(item.CREATED_AT)
                        }
                        if (item.FIRST_BUILD_ON != null || item.FIRST_BUILD_ON != '') {
                            item.FIRST_BUILD_ON = new Date(item.FIRST_BUILD_ON)
                        }

                        const pa = item.project_analysis;
                        if (pa != null && String(pa).trim() !== '') {
                            vm.AIAnalysis = String(pa).trim();
                        } else {
                            vm.AIAnalysis = null;
                            if (pa == null || pa === '') {
                                item.project_analysis = 'No Analysis';
                            }
                        }
                        vm.TemplateId = item.Template_id;
                        vm.IndustryTypeId = item.IndustryType_id;
                        vm.IsAIAnalysis = true;
                    });
                }
            });
        },
        addTimeWithOffset(time, offset) {
            if (!time || !offset) return time;
            let [hours, minutes] = time.split(":").map(Number);
            let [sign, offH, offM] = offset.match(/([+-])(\d{2}):(\d{2})/).slice(1);
            let totalMinutes = hours * 60 + minutes;
            let offsetMinutes = parseInt(offH) * 60 + parseInt(offM);
            if (sign === "-") offsetMinutes *= -1;
            totalMinutes += offsetMinutes;
            totalMinutes = ((totalMinutes % (12 * 60)) + 12 * 60) % (12 * 60);
            let hh = String(Math.floor(totalMinutes / 60)).padStart(2, "0");
            let mm = String(totalMinutes % 60).padStart(2, "0");
            return `${hh}:${mm}`;
        },
        UpdateAIAnalysis() {
            const ths = this;
            ths.IsAIAnalysis = false;
            ths.AIAnalysis = null;
            ths.Key++;
            ths.$nextTick(() => {
                ths.IsAIAnalysis = true;
            });
        },
        convertSecondsToHHMMSS: function (intSecondsToConvert) {
            var hours = this.convertHours(intSecondsToConvert);
            var minutes = this.getRemainingMinutes(intSecondsToConvert);
            var seconds = this.getRemainingSeconds(intSecondsToConvert);
            var formattedHours = this.formatIndianNumber(hours);
            if (hours < 10) formattedHours = '0' + hours;
            if (minutes < 10) minutes = '0' + minutes;
            if (seconds < 10) seconds = '0' + seconds;

            return formattedHours + '.' + minutes + ' Hrs';
        },
        getRemainingMinutes: function (intSeconds) {
            var intTotalMinutes = this.convertMinutes(intSeconds);
            return intTotalMinutes % this.minutesPerHour;
        },
        getRemainingSeconds: function (intTotalSeconds) {
            return intTotalSeconds % this.secondsPerMinute;
        },
        formatIndianNumber: function (num) {
            var str = num.toString();
            if (str.length <= 3) return str;
            var lastThree = str.slice(-3);
            var remaining = str.slice(0, -3);
            remaining = remaining.replace(/\B(?=(\d{2})+(?!\d))/g, ',');
            return remaining + ',' + lastThree;
        },
        convertHours: function (intSeconds) {
            var minutes = this.convertMinutes(intSeconds);
            var hours = Math.floor(minutes / this.minutesPerHour);
            return hours;
        },
        convertMinutes: function (intSeconds) {
            return Math.floor(intSeconds / this.secondsPerMinute);
        },
        cleanText(text) {
            return text ? text.replace(/<[^>]*>/g, '') : 'N/A';
        },
        getShortText(text) {
            const cleaned = this.cleanText(text);
            return cleaned.slice(0, this.charLimit);
        },
        getRemainingText(text) {
            const cleaned = this.cleanText(text);
            return cleaned.slice(this.charLimit);
        },
        needsTruncate(text) {
            const cleaned = this.cleanText(text);
            return cleaned.length > this.charLimit;
        },
        toggleReadMoreDescription(id) {
            this.$set(this.showMoreDescription, id, !this.showMoreDescription[id]);
        },        
        loadDummyData() {
            this.isLoading = true;
            const params = `ProjectId=${this.projectId}`;
            DataService.GetChartBugProject(params).then((response) => {
                if (response.data.result != null) {
                    if (response.data.result.STATUSDATA != null) {
                        this.IsTaskType = response.data.result.STATUSDATA.length > 0 ? true : false;
                        this.bindComponentChartDataa(response.data.result.STATUSDATA);
                    }
                    if (response.data.result.BUGDATA.length>0) {
                        this.IsBugType = response.data.result.BUGDATA.length > 0 ? true : false;
                        this.bindComponentbugChartDataa(response.data.result.BUGDATA);
                    }
                    if (response.data.result.STAGEDATA != null) {
                        this.IsStage = response.data.result.STAGEDATA.length > 0 ? true : false;
                        this.bindComponentstageChartDataa(response.data.result.STAGEDATA);
                    }
                    if (response.data.result.SPRINTDATA != null) {
                        this.IsSprintType = response.data.result.SPRINTDATA.length > 0 ? true : false;
                        this.bindComponentSprintChartDataa(response.data.result.SPRINTDATA);
                    }
                    if (response.data.result.PHASEDATA != null) {
                        this.isPhase = response.data.result.PHASEDATA.length > 0 ? true : false;
                        this.bindComponenPhaseChartDataa(response.data.result.PHASEDATA);
                    }
                    if (response.data.result.TASKWITHDATE) {
                        this.IsBugTrendDayWise = response.data.result.TASKWITHDATE.length > 0 ? true : false;
                        this.bindChartData(response.data.result.TASKWITHDATE);
                    }
                    if (response.data.result.CRITICALBLOCKERBUGS != null) {
                        this.CriticalBlokersBugs = response.data.result.CRITICALBLOCKERBUGS
                        this.CriticalBlokersBugs.forEach((x) => {
                            x.ispopover = false;
                            x.AssignUser = x.Assign != null ? x.Assign.split(',') : '';
                        });
                    }
                }
                this.isLoading = false;
            }).catch((error) => {
                console.error("Error loading chart data:", error);
                this.isLoading = false;
            });
        }, 
        bindChartData(data) {
            if (!data || data.length === 0) {
                return;
            }
            const totalBugsData = data.map(item => item.total || item.Total || (item.open || 0) + (item.inprogress || 0) + (item.completed || 0) + (item.closed || 0) || 0);
            const inprogressBugsData = data.map(item => item.inprogress || item.Inprogress || item.inProgress || 0);
            const completedBugsData = data.map(item => item.completed || item.Completed || 0);
            const closedBugsData = data.map(item => item.closed || item.Closed || 0);
            const totalSum = totalBugsData.reduce((a, b) => a + b, 0);
            const inprogressSum = inprogressBugsData.reduce((a, b) => a + b, 0);
            const completedSum = completedBugsData.reduce((a, b) => a + b, 0);
            const closedSum = closedBugsData.reduce((a, b) => a + b, 0);
            this.chartOptionss = {
                chart: { type: 'donut', toolbar: { show: false }, fontFamily: 'inherit', offsetY: 0 },
                labels: ["Total Bugs", "Inprogress Bugs", "Completed Bugs", "Closed Bugs"],
                colors: ["#FF4560", "#00E396", "#008FFB", "#775DD0"],
                stroke: { width: 2, colors: ['#fff'] },
                plotOptions: {
                  pie: {
                    expandOnClick: false,
                    donut: {
                      size: '52%',
                      labels: {
                        show: true,
                        name: { show: false },
                        value: { show: false },
                        total: {
                          show: true,
                          showAlways: true,
                          label: 'Total Bugs',
                          fontSize: '13px',
                          fontWeight: 500,
                          color: '#5f6368',
                          formatter: (w) =>
                            String(w.globals.seriesTotals.reduce((a, b) => a + b, 0)),
                        },
                      },
                    },
                  },
                },
                legend: {
                  show: true,
                  showForSingleSeries: true,
                  position: 'bottom',
                  horizontalAlign: 'center',
                  floating: false,
                  fontSize: '12px',
                  fontWeight: 500,
                  offsetY: 4,
                  itemMargin: { horizontal: 10, vertical: 6 },
                  markers: { width: 10, height: 10, radius: 3, offsetX: -2 },
                  formatter: (seriesName, opts) => {
                    const i = opts.seriesIndex;
                    const val = opts.w.globals.series[i];
                    const total = opts.w.globals.series.reduce((a, b) => a + b, 0) || 1;
                    const pct = ((val / total) * 100).toFixed(1);
                    return `${seriesName} (${pct}%)`;
                  },
                },
                dataLabels: { enabled: false },
                tooltip: {
                  y: { formatter: (val) => `${val}` },
                },
            };
            this.seriess = [totalSum, inprogressSum, completedSum, closedSum];
            this.$nextTick(() => {
                this.chartKey++;
            });
        },
        bindComponentbugChartDataa(data) {
            if (!data || !Array.isArray(data) || data.length === 0) {
                this.sprintSeries = [];
                this.bugchartOptions.xaxis.categories = [];
                this.bugchartOptions.fullData = [];
                return;
            }
            const categories = data.map(item =>item.STATUS_NAME || "Task");
            const values = data.map(item => Number(item.TOTAL) || 0 );
            const colors = data.map(item => item.STATUS_BG_COLOR || "#008FFB");
            this.bugSeries = values;
            this.$set(this.bugchartOptions, 'labels', categories);
            this.$set(this.bugchartOptions, 'colors', colors);
        },
        bindComponentstageChartDataa(data) {
            if (!data || data.length === 0) return;
            const categories = data.map(item => item.STAGE_NAME || "Stage");
            const values = data.map(item => Number(item.TOTAL_COUNT) || 1);
            this.stageSeries = values;
            this.$set(this.stagechartOptions, 'labels', categories);
            this.$set(this.stagechartOptions, 'colors', STAGE_COLORS.slice(0, categories.length));
            this.chartKey++;
        },
           bindComponentChartDataa(data) {
            if (!data || data.length === 0) return;
            const categories = data.map(item =>item.component_name || "Task");
            const values = data.map(item => Number(item.total_count) || 0 );
            const colors = data.map(item => item.status_bg_color || "#008FFB");
            this.seriesComponent = values;
            this.$set(this.chartOptionComponent, 'labels', categories);
            this.$set(this.chartOptionComponent, 'colors', colors);
        },
        bindComponenPhaseChartDataa(dataa) {
            if (!dataa || dataa.length === 0) return;
            this.fullPhaseData = dataa;
            const categories = dataa.map(item => item.PHASE_NAME || "Phase");
            const values = dataa.map(item => Number(item.phase_progress) || 0);
            this.phaseseries = values;
            this.phaseChartOptions.labels = categories;
            this.phaseChartOptions.colors = categories.map((_, index) => PHASE_COLORS[index % PHASE_COLORS.length]);
            this.chartKey++;
        },
        bindComponentSprintChartDataa(data) {
            if (!data || !Array.isArray(data) || data.length === 0) {
                this.sprintSeries = [];
                this.sprintchartOptions.labels = [];
                return;
            }
            const categories = data.map(item => {
                const name = item.sprint_name?.trim() || `Sprint ${item.id || '?'}`;
                return name.charAt(0).toUpperCase() + name.slice(1);
            });
            this.sprintSeries = data.map(i => Number(i.total_tasks) || 0);
            this.sprintchartOptions.labels = categories;
            this.sprintchartOptions.colors = categories.map((_, index) => SPRINT_COLORS[index % SPRINT_COLORS.length]);
        },
        

        openviewallteammembers() {
            this.isViewAllTeam = true;

        },
        opendetailModel() {
            this.isProjectDeatil = true
        },
        FetchTeamListing: function () {
            var ths = this;
            ths.isLoading = true;
            return new Promise((resolve, reject) => {
                let url = '';
                if (ths.searchCondition !== '') {
                    url = `projectId=${ths.projectId}&projectName=&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}&${ths.searchCondition}`;
                } else {
                    url = `projectId=${ths.projectId}&projectName=&designationId=&sortBy=${ths.SortBy}&sortExp=${ths.SortExp}&pageSize=${ths.PageSize}&pageNum=${ths.PageNumber}`;
                }
                DataService.GetTeamListing(url)
                    .then((response) => {
                        ths.isLoading = false;

                        if (response.data?.result?.data?.length > 0) {
                            ths.TotalRecords = response.data.result.data[0].Total_Count;
                            ths.TotalPages = Math.ceil(ths.TotalRecords / ths.PageSize);
                            ths.CurrentPage = ths.PageNumber;
                            resolve(response.data.result.data);
                        } else {
                            resolve([]);
                        }
                    })
                    .catch((error) => {
                        ths.isLoading = false;
                        reject(error);
                    });
            });
        },
        GetTeamForAssociateProject() {
            var ths = this;
            return new Promise((resolve, reject) => {
                var url = `refId=${ths.projectId}&refCode=TEAM`;
                DataService.GetTeamForAssociateProject(url)
                    .then((response) => {
                        ths.isLoading = false;
                        if (response.data?.result?.length > 0) {
                            resolve(response.data.result);
                        } else {
                            resolve([]);
                        }
                    })
                    .catch((error) => {
                        ths.isLoading = false;
                        reject(error);
                    });
            });
        },
        stringToColor(str) {
            let hash = 0;
            for (let i = 0; i < str.length; i++) {
                hash = str.charCodeAt(i) + ((hash << 5) - hash);
            }
            let color = "#";
            for (let i = 0; i < 3; i++) {
                const value = (hash >> (i * 8)) & 0xff;
                color += ("00" + value.toString(16)).substr(-2);
            }
            return color;
        },
        getContrastColor(hex) {
            hex = hex.replace("#", "");
            let r = parseInt(hex.substr(0, 2), 16);
            let g = parseInt(hex.substr(2, 2), 16);
            let b = parseInt(hex.substr(4, 2), 16);
            let brightness = (r * 299 + g * 587 + b * 114) / 1000;
            return brightness > 125 ? "black" : "white";
        },
        GetInitalbgColor(item) {
            let bg = this.stringToColor(item.USER_NAME || item.USER_ID);
            let textColor = this.getContrastColor(bg);
            return { background: bg, color: textColor };
        },
        getInitials(name) {
            if (!name) return '';
            return name
                .split(' ')
                .map((n) => n[0])
                .join('')
                .toUpperCase();
        },

     
        AddView() {
            var Obj = {
                TemplateId: this.TemplateId,
                IndustryTypeId: this.IndustryTypeId
            }
            this.$emit('AddView', Obj);
        
        },
        showAssignUser(row) {
            row.ispopover = true;
            this.updateRowData(row);
        },
        hideAssignUser(row) {
            row.ispopover = false;
            this.updateRowData(row);
        },
        updateRowData(updatedRow) {
            const index = this.CriticalBlokersBugs.findIndex(row => row.task_id === updatedRow.task_id);
            if (index !== -1) {
                this.$set(this.CriticalBlokersBugs, index, updatedRow);
            }
        },
        AssignedUser: function (val, users) {
            var vm = this;
            vm.BacklogId = val;
            vm.AssigenedUser = users;
            vm.IsAssignedUser = true;
        },
        openviewallactivity() {
            this.isViewAllActivity = true;
        },
        openDashboardAddView() {
            this.isCriticalandBlockerDetail = true;
        },
        truncate(str, len) {
            if (str == null || str === '') return '—';
            const s = String(str);
            return s.length > len ? `${s.slice(0, len - 1)}…` : s;
        },
        formatCellDate(val) {
            if (!val) return '—';
            const f = this.$options.filters && this.$options.filters.formatDate;
            if (typeof f === 'function') return f(val);
            try {
                const d = val instanceof Date ? val : new Date(val);
                if (Number.isNaN(d.getTime())) return '—';
                const mm = String(d.getMonth() + 1).padStart(2, '0');
                const dd = String(d.getDate()).padStart(2, '0');
                const yy = d.getFullYear();
                return `${mm}/${dd}/${yy}`;
            } catch (e) {
                return '—';
            }
        }
    }
}
</script>


