<template>
  <section>
  <tg-list ref="tgList" :listType="['List']" :IsShowAction="false" :showCheckBox="false" ModuleName="Event"
                 SubModuleCode="Client" IdentityColumn="DONATION_ID" :HeaderText="$t('WaitList')" :ListData="list"
                 :HeaderData="Headers" :HeaderButtons="Buttons" :TotalRecords="TotalRecords"
                 :RenderRowActionMethod="renderActions" :ListDataCallBackFunction="GetEventDonationListing"
                 :SortExp="SortExp" :SortBy="SortBy" :NorecordfoundText="$t('NoRecordfound')" v-on:ActionButtonClick="actionButtonClick"
                 v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
                 v-on:SortdataButtonClick="sortdata" >
                <template  v-slot:slotdata="{ data }">
                 <template v-if="data.column.COLUMN_NAME == 'FULL_NAME'">
                         <a  class="task-dec" :title="data.row.FULL_NAME" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                             {{ data.row.FULL_NAME}}
                         </a>  
                     </template>
                     <template v-if="data.column.COLUMN_NAME == 'EMAIL'">
                         <span :title="data.row.EMAIL" style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                             {{ data.row.EMAIL}}
                         </span>
                     </template>
                     <template v-if="data.column.COLUMN_NAME == 'STATUS_NAME'">
                         <a    :title="data.row.STATUS_NAME" style="cursor: pointer; white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                             {{ data.row.STATUS_NAME}}
                         </a>
                     </template>
                </template>
             </tg-list>
   </section> 
 </template>
 
 <script>
 import DataService from '@/services/DataService';
  import Schema from './WaitlistPortionSchema';
 export default {
   name: 'EventDonationPortion',
   props: { eventId: { type: [Number, String], required: true } },
   data() { return { 
     list: [],
     SortBy: '',
     SortExp: '',
      TotalRecords: 0, 
      PageSize: 10, 
      PageNumber: 1,
      CompanyId:0,
      userId:0,
      listActions: Schema.listActions,
      Headers: Schema.TableHeader,
      Buttons: Schema.buttons,
     }; },
   created() { 
     this.CompanyId = this.GetUserInfo.CompanyId;
     this.userId = this.GetUserInfo.ID;
     this.fetch(); },
   methods: {
     async fetch() {
       try {
         const res = await DataService.GetWaitlistListing(`eventId=${this.eventId}&pageSize=${this.PageSize}&pageNumber=${this.PageNumber}&loggedInUserId=${this.userId}&companyId=${this.CompanyId}`);
         this.list = (res.data && res.data.result && res.data.result.data) ? res.data.result.data : (res.data && res.data.result && Array.isArray(res.data.result)) ? res.data.result : [];
         this.TotalRecords = (res.data && res.data.result) ? (res.data.result.totalRecords || this.list.length) : 0;
       } catch (_) { this.list = []; this.TotalRecords = 0; }
     },
     renderActions: function () {
             var self = this;
             let rtnActionArray = [];
             self.listActions.forEach(actionItem => {
                 let action = { ...actionItem };
                 switch (action.title) {
                     case 'AddWaitList':
                         action.isVisible = true;
                         break;
                     default: {
                         action.isVisible = true;
                     }
                 }
                 rtnActionArray.push(action);
             });
             return rtnActionArray;
         },
         pagerMethod: function (value) {
             this.PageSize = value.PageSize;
             this.PageNumber = value.PageNumber;
             this.fetch();
         },
         actionButtonClick: function (callbackfunction, item) {            
             switch (callbackfunction) {
                 case 'EditWaitList':
                     this.AddWaitList(item);
                     break;
                 case 'DeleteWaitList':
                     this.commonDeleteData(item);
                     break;
             }
         },
         commonHeaderButtonClick: async function (event) {
             var vm = this;
             switch (event.callbackfunction) {
                 case "AddWaitList":
                 vm.AddWaitList();
                     break;
                 case "BackToList":
                 vm.BackToList();
                     break;
                 case "DeleteWaitList":
                     vm.commonDeleteData();
                     break;
             }
         }, 
        async AddWaitList(){
            var vm = this;
            var url = 'controller=Project&action=AddUpdateWaitlist';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    //vm.showAddModal = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
         },
         BackToList: function () {
             this.$router.push({ name: 'ProjectList' });
         },  
        async commonDeleteData(){
            var vm = this;
            var url = 'controller=Project&action=DeleteWaitlist';
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    //vm.showAddModal = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                }
            });
         },
         sortdata: function (s) {
             var SortDir = "sort tb_headerSortDown";
             this.SortBy = s;
             if (s === this.SortBy) {
                 if (this.SortExp == "") {
                     this.SortExp = "ASC";
                     SortDir = "sort tb_headerSortDown";
                 }
                 else if (this.SortExp == "ASC") {
                     this.SortExp = "DESC";
                     SortDir = "sort tb_headerSortUp";
                 }
                 else {
                     this.SortExp = "ASC";
                     SortDir = "sort tb_headerSortDown";
                 }
             }
             this.fetch();
             $("#" + s + '  span:first-child').attr("class", SortDir);
         },   
   }
 };
 </script>
 