<template>
    <section>
        <tg-list ref="tgList" :listType="['List']" :IsShowAction="true" :showCheckBox="false" ModuleName="Event"
            SubModuleCode="Client" IdentityColumn="ID" :HeaderText="$t('Social Media')"
            :ListData="ListingData" :HeaderData="Headers" :widgets="widgets" :HeaderButtons="Buttons"
            :TotalRecords="TotalRecords" :RenderRowActionMethod="renderActions"
            :ListDataCallBackFunction="FetchSocialMedia" :SortExp="SortExp" :SortBy="SortBy"
            :NorecordfoundText="$t('NoRecordfound')" v-on:ActionButtonClick="actionButtonClick"
            v-on:PagerButtonClick="pagerMethod" v-on:HeaderButtonClick="commonHeaderButtonClick"
            v-on:SortdataButtonClick="sortdata">
            <template v-slot:slotdata="{ data }">
                <template v-if="data.column.COLUMN_NAME == 'NAME'">
                    <a @click="GetEventSocalListDetails(data.row)" class="task-dec" :title="data.row.item_type"
                        style="white-space: nowrap;  word-wrap: break-word;  overflow: hidden;  display: block;  text-overflow: ellipsis;">
                        {{ data.row.NAME }}
                    </a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'LINK'">
                    <a v-on:click="OpenLinkUrl(data.row.LINK)" class="text-info" style="cursor: pointer;">{{
                        data.row.LINK }}</a>
                </template>
                <template v-if="data.column.COLUMN_NAME == 'ICON'">
                    <span :title="data.row.ICON" class="text-center single-action">
                        <em class="fa text-primary action-icon" v-html="data.row.ICON"></em>
                    </span>
                </template>
            </template>
        </tg-list>
        <ModalSocialMedia v-if="showSocialMediaAdd" @ReladSocialMedia="ReladSocialMedia" :SocialMediaId="SocialMediaId">
        </ModalSocialMedia>
    </section>
</template>
<script>
import Schema from './SocialMediaPortionSchema';
import DataService from '../../../../services/DataService';
import ModalSocialMedia from '../Modals/ModalSocialMedia.vue';
export default {
    components: { ModalSocialMedia },
    data() {
        return {
            TotalRecords: 0,
            noRecord: false,
            isLoading: false,
            CompanyId: null,
            showSocialMediaAdd: false,
            PageSize: 10,
            statusId: '',
            PageNumber: 1,
            isPaged: 1,
            TotalPages: 0,
            widgets: [],
            SortBy: '',
            SortExp: '',
            listActions: Schema.listActions,
            Headers: Schema.TableHeader,
            ListingData: [],
            searchCondition: '',
            Buttons: Schema.buttons,
            projectId: 0,
            SocialMediaId: 0
        };
    },
    created: async function () {
        this.CompanyId = this.GetUserInfo.CompanyId;
        this.projectId = parseInt(this.$route.params.projectId);
        this.userId = this.GetUserInfo.ID;
        await this.FetchSocialMedia();
    },
    methods: {
        renderActions: function () {
            var self = this;
            let rtnActionArray = [];
            self.listActions.forEach(actionItem => {
                let action = { ...actionItem };
                switch (action.title) {
                    case 'AddWishList':
                        action.isVisible = true;
                        break;
                    default: {
                        action.isVisible = true;
                    }
                }
                rtnActionArray.push(action);
            });
            return rtnActionArray;
        },
        pagerMethod: function (value) {
            this.PageSize = value.PageSize;
            this.PageNumber = value.PageNumber;
            this.FetchWishList();
        },
        actionButtonClick: function (callbackfunction, item) {
            switch (callbackfunction) {
                case 'GetEventSocalListDetails':
                    this.GetEventSocalListDetails(item);
                    break;
                case 'DeleteSocialMedia':
                    this.DeleteSocialMedia(item.ID);
                    break;

            }
        },
        commonHeaderButtonClick: async function (event) {
            var vm = this;
            switch (event.callbackfunction) {
                case "OpenAddSocialMedia":
                    vm.OpenAddSocialMedia();
                    break;
                case "BackToList":
                    vm.BackToList();
                    break;
            }
        },
        OpenAddSocialMedia: async function () {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateSocialMedia'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.SocialMediaId = 0;
                    vm.showSocialMediaAdd = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    vm.showSocialMediaAdd = false;
                }
            });
        },
        sortdata: function (s) {
            var SortDir = "sort tb_headerSortDown";
            this.SortBy = s;
            if (s === this.SortBy) {
                if (this.SortExp == "") {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
                else if (this.SortExp == "ASC") {
                    this.SortExp = "DESC";
                    SortDir = "sort tb_headerSortUp";
                }
                else {
                    this.SortExp = "ASC";
                    SortDir = "sort tb_headerSortDown";
                }
            }
            this.FetchWishList();
            $("#" + s + '  span:first-child').attr("class", SortDir);
        },
        DeleteSocialMedia: async function (id) {
            var vm = this;
            var url = 'controller=Project&action=DeleteSocialMedia'
            await DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {

                    vm.confirmR(vm.$t("ConfirmDelete"), true, (vm.$t("Delete") + "  " + vm.$t("Group")), function () {
                        var data = {
                            ID: id
                        };
                        var objectPostString = JSON.stringify(data);
                        DataService.DeleteSocialMedia(objectPostString).then(function (response) {
                            vm.isLoading = false;
                            if (response.status == 200) {
                                vm.ShowAlert(vm.$t('DeletedSuccess', [vm.$t('WishList')]), "success", true, vm.$t("Alert"));
                                vm.FetchSocialMedia();
                            }
                            else {
                                vm.ShowAlert(vm.$t('DeletedError', [vm.$t('WishList')]), "warning", true, vm.$t("Alert"));
                            }
                        });
                    });
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");                  
                }
            });
        },
        BackToList: function () {
            this.$router.push({ name: 'ProjectList' });
        },
        FetchSocialMedia: async function () {
            this.isLoading = true;
            const params = `referenceid=${this.projectId}&companyId=${this.CompanyId}&sortBy=${this.SortBy}&sortExp=${this.SortExp}&pageSize=${this.PageSize}&pageNum=${this.PageNumber}&search=`;
            await DataService.GetSocialMediaListing(params).then(response => {
                const data = response.data.result.data;
                if (data.length > 0) {
                    this.ListingData = response.data.result.data;
                    this.TotalRecords = response.data.result.data[0].TOTALRECORDS;
                    this.TotalPages = Math.ceil(this.TotalRecords / this.PageSize);                    
                } else {
                    this.TotalRecords = 0;
                    this.TotalPages = 1;
                    this.ListingData = [];
                }
            });
        },
        ReladSocialMedia() {
            var ths = this;
            ths.showSocialMediaAdd = false;
            ths.FetchSocialMedia();
        },
        GetEventSocalListDetails(socialmediaId) {
            var vm = this;
            var url = 'controller=Project&action=AddUpdateSocialMedia'
            DataService.CheckPrivilege(url).then(async function (response) {
                if (response.data) {
                    vm.SocialMediaId = socialmediaId.ID;
                    vm.showSocialMediaAdd = true;
                }
                else {
                    vm.ShowAlert(vm.$t('NotAuthorizedSection'), "failure", true, "Alert");
                    vm.showSocialMediaAdd = false;
                }
            });
        },
        OpenLinkUrl: function (item) {
            window.open('//' + item);
        },

    }
};
</script>
